const ACTIVITY_BACKGROUND_BLOCK_TYPES: &[&str] = &[
    "situational-dialogue",
    "image-text",
    "image-grid",
    "point-of-interest",
    "find-elements",
    "complete",
    "card-sort",
    "matching",
    "media",
    "slides",
    "rich-text",
    "tabs",
    "flip-cards",
    "divider",
    "section-marker",
    "quote",
    "note",
    "image",
    "accordion",
    "timeline",
    "result-message",
    "attachment",
    "links-resources",
    "audio",
    "continue",
    "course-exit",
    "quiz",
    "question-multiple",
    "question-unique",
    "question-true-false",
    "question-random",
    "html-custom",
    "image-360",
];

fn supports_activity_background(block_type: &str) -> bool {
    ACTIVITY_BACKGROUND_BLOCK_TYPES.contains(&block_type)
}

fn supports_activity_frame_appearance(block_type: &str, property: &str) -> bool {
    const FULL: &[&str] = &["note", "audio", "accordion", "tabs", "links-resources", "quote"];
    match property {
        "panelBackgroundColor" | "panelBorderColor" => FULL.contains(&block_type) || block_type == "attachment",
        "activityAccentColor" => matches!(block_type, "audio" | "accordion" | "tabs" | "links-resources" | "quote"),
        "panelBorderWidth" | "panelBorderStyle" => FULL.contains(&block_type) || block_type == "flip-cards",
        "panelRounded" => FULL.contains(&block_type) || block_type == "attachment",
        "panelShadow" => FULL.contains(&block_type),
        _ => false,
    }
}

fn apply_section_background_update(
    block: &mut PaideiaBlock,
    block_type: &str,
    color: Option<String>,
    image_ref: Option<String>,
    opacity: Option<f64>,
    overlay_dark: Option<bool>,
    blur: Option<f64>,
    position_y: Option<f64>,
    rounded: Option<bool>,
    wide: Option<bool>,
    height: Option<String>,
) {
    if supports_activity_background(block_type) {
        block.section_background_color = color.or_else(|| block.section_background_color.clone());
        block.section_background_image_ref =
            image_ref.or_else(|| block.section_background_image_ref.clone());
        if let Some(value) = opacity {
            block.section_background_opacity = Some(value);
        }
        if let Some(value) = overlay_dark {
            block.section_background_overlay_dark = Some(value);
        }
        if let Some(value) = blur {
            block.section_background_blur = Some(value);
        }
        if let Some(value) = position_y {
            block.section_background_position_y = Some(value.clamp(0.0, 100.0));
        }
        if let Some(value) = rounded {
            block.section_background_rounded = Some(value);
        }
        if let Some(value) = wide {
            block.section_background_wide = Some(value);
        }
        block.section_background_height =
            height.or_else(|| block.section_background_height.clone());
        return;
    }

    if block_type == "header" {
        // The header image uses only blur and overlay from the shared background model.
        if let Some(value) = opacity {
            block.section_background_opacity = Some(value);
        }
        if let Some(value) = overlay_dark {
            block.section_background_overlay_dark = Some(value);
        }
        if let Some(value) = blur {
            block.section_background_blur = Some(value);
        }
        block.section_background_color = None;
        block.section_background_image_ref = None;
        block.section_background_position_y = None;
        block.section_background_rounded = None;
        block.section_background_wide = None;
        block.section_background_height = None;
        return;
    }

    block.section_background_color = None;
    block.section_background_image_ref = None;
    block.section_background_opacity = None;
    block.section_background_overlay_dark = None;
    block.section_background_blur = None;
    block.section_background_position_y = None;
    block.section_background_rounded = None;
    block.section_background_wide = None;
    block.section_background_height = None;
}

