fn is_webview2_runtime_root(path: &Path) -> bool {
    path.join("msedgewebview2.exe").exists()
}

fn detect_webview2_runtime_root(app: &tauri::AppHandle) -> Option<PathBuf> {
    if let Ok(env_path) = std::env::var("WEBVIEW2_BROWSER_EXECUTABLE_FOLDER") {
        let path = PathBuf::from(env_path);
        if is_webview2_runtime_root(&path) {
            return Some(path);
        }
    }

    let mut candidates = Vec::new();

    if let Ok(exe_path) = std::env::current_exe() {
        if let Some(exe_dir) = exe_path.parent() {
            candidates.push(exe_dir.join("webview2-fixed-runtime"));
            candidates.push(exe_dir.to_path_buf());
        }
    }

    if let Ok(resource_dir) = app.path().resource_dir() {
        candidates.push(resource_dir.join("webview2-fixed-runtime"));
        candidates.push(resource_dir);
    }

    for candidate in candidates {
        if is_webview2_runtime_root(&candidate) {
            return Some(candidate);
        }
        if let Ok(children) = fs::read_dir(&candidate) {
            for child in children.flatten() {
                let child_path = child.path();
                if child_path.is_dir() && is_webview2_runtime_root(&child_path) {
                    return Some(child_path);
                }
            }
        }
    }

    None
}

fn extract_webview2_runtime_version(runtime_root: &Path) -> Option<String> {
    let manifests = fs::read_dir(runtime_root)
        .ok()?
        .flatten()
        .map(|entry| entry.path())
        .filter(|path| path.extension().and_then(|extension| extension.to_str()) == Some("manifest"))
        .collect::<Vec<_>>();

    // A fixed runtime contains exactly one version manifest. Returning no value
    // is safer than displaying a stale version if a generated resource folder
    // was accidentally merged with an older runtime.
    if manifests.len() != 1 {
        return None;
    }

    let manifest = fs::read_to_string(&manifests[0]).ok()?;
    let assembly_version = Regex::new(
        r#"(?is)<assemblyIdentity\b[^>]*\bversion\s*=\s*['\"]([^'\"]+)['\"]"#,
    )
    .expect("valid WebView2 manifest version regex");

    assembly_version
        .captures(&manifest)
        .and_then(|captures| captures.get(1))
        .map(|version| version.as_str().to_string())
}

#[tauri::command]
pub fn get_embedded_webview2_runtime_version(app: tauri::AppHandle) -> Option<String> {
    detect_webview2_runtime_root(&app)
        .and_then(|runtime_root| extract_webview2_runtime_version(&runtime_root))
}

