#[tauri::command]
pub fn save_user_situational_dialogue_character(
    input: SaveUserSituationalDialogueCharacterInput,
) -> Result<UserSituationalDialogueCharacterDescriptor, String> {
    let root = ensure_user_situational_dialogue_character_bank()?;
    let name = input.name.trim();
    if name.is_empty() {
        return Err("Le nom du personnage est requis".to_string());
    }
    let previous_id = input
        .id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(sanitize_user_character_id)
        .transpose()?;
    let mut metadata = read_user_character_bank_metadata(&root)?;
    let id = unique_user_character_id(&root, &metadata, name, previous_id.as_deref());
    let character_root = root.join("personnages");
    fs::create_dir_all(&character_root).map_err(|err| err.to_string())?;
    if let Some(previous_id) = previous_id
        .as_deref()
        .filter(|previous| !previous.eq_ignore_ascii_case(&id))
    {
        let previous_dir = character_root.join(previous_id);
        let next_dir = character_root.join(&id);
        if previous_dir.exists() {
            fs::rename(&previous_dir, &next_dir).map_err(|err| err.to_string())?;
        } else {
            fs::create_dir_all(&next_dir).map_err(|err| err.to_string())?;
        }
        let previous_prefix = format!("personnages/{}/", previous_id);
        let next_prefix = format!("personnages/{}/", id);
        for entry in metadata.characters.iter_mut() {
            if entry.id.eq_ignore_ascii_case(previous_id) {
                entry.id = id.clone();
                if let Some(preview_ref) = entry.preview_ref.as_mut() {
                    if preview_ref.starts_with(&previous_prefix) {
                        *preview_ref = preview_ref.replacen(&previous_prefix, &next_prefix, 1);
                    }
                }
            }
        }
    }
    let character_dir = character_root.join(&id);
    fs::create_dir_all(&character_dir).map_err(|err| err.to_string())?;

    let existing_preview_ref = metadata
        .characters
        .iter()
        .find(|candidate| candidate.id.eq_ignore_ascii_case(&id))
        .and_then(|entry| entry.preview_ref.clone())
        .filter(|value| !value.is_empty())
        .filter(|asset_ref| safe_user_character_asset_path(&root, asset_ref).is_ok());
    let portable_id = metadata
        .characters
        .iter()
        .find(|candidate| candidate.id.eq_ignore_ascii_case(&id))
        .and_then(|entry| entry.portable_id.clone())
        .filter(|value| uuid::Uuid::parse_str(value).is_ok())
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());

    let role = input.role.and_then(|value| {
        let trimmed = value.trim().to_string();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed)
        }
    });
    let description = input.description.and_then(|value| {
        let trimmed = value.trim().to_string();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed)
        }
    });
    let entry = UserCharacterBankEntry {
        id: id.clone(),
        resource_modified_at: None,
        portable_id: Some(portable_id),
        name: Some(name.to_string()),
        role: role.clone(),
        description: description.clone(),
        preview_ref: existing_preview_ref,
    };
    if let Some(existing) = metadata
        .characters
        .iter_mut()
        .find(|candidate| candidate.id.eq_ignore_ascii_case(&id))
    {
        *existing = entry;
    } else {
        metadata.characters.push(entry);
    }
    write_user_character_bank_metadata(&root, &metadata)?;
    scan_user_situational_dialogue_character_bank()?
        .into_iter()
        .find(|candidate| candidate.id.eq_ignore_ascii_case(&id))
        .or_else(|| {
            Some(UserSituationalDialogueCharacterDescriptor {
                id: id.clone(),
                resource_modified_at: Some(Utc::now().timestamp_millis()),
                name: name.to_string(),
                role,
                description,
                preview_ref: None,
                poses: Vec::new(),
            })
        })
        .ok_or_else(|| "Personnage utilisateur introuvable".to_string())
}

#[tauri::command]
pub fn duplicate_user_situational_dialogue_character(
    character_id: String,
) -> Result<UserSituationalDialogueCharacterDescriptor, String> {
    let root = ensure_user_situational_dialogue_character_bank()?;
    let source_id = sanitize_user_character_id(&character_id)?;
    let mut metadata = read_user_character_bank_metadata(&root)?;
    let source = metadata
        .characters
        .iter()
        .find(|entry| entry.id.eq_ignore_ascii_case(&source_id))
        .cloned()
        .ok_or_else(|| "Personnage utilisateur introuvable".to_string())?;
    let name = format!("{} — copie", source.name.as_deref().unwrap_or(&source.id));
    let id = unique_user_character_id(&root, &metadata, &name, None);
    let source_dir = root.join("personnages").join(&source_id);
    let destination_dir = root.join("personnages").join(&id);
    if !source_dir.is_dir() {
        return Err("Dossier du personnage introuvable".to_string());
    }
    copy_dir_contents(&source_dir, &destination_dir)?;
    let preview_ref = source.preview_ref.map(|value| {
        value.replacen(
            &format!("personnages/{}/", source.id),
            &format!("personnages/{}/", id),
            1,
        )
    });
    metadata.characters.push(UserCharacterBankEntry {
        id: id.clone(),
        resource_modified_at: None,
        portable_id: Some(uuid::Uuid::new_v4().to_string()),
        name: Some(name),
        role: source.role,
        description: source.description,
        preview_ref,
    });
    write_user_character_bank_metadata(&root, &metadata)?;
    scan_user_situational_dialogue_character_bank()?
        .into_iter()
        .find(|entry| entry.id == id)
        .ok_or_else(|| "Copie du personnage introuvable".to_string())
}

#[tauri::command]
pub fn upload_user_situational_dialogue_character_pose(
    character_id: String,
    state: String,
    file_name: String,
    file_bytes: Vec<u8>,
    make_default: bool,
) -> Result<Vec<UserSituationalDialogueCharacterDescriptor>, String> {
    validate_user_image_file(&file_name, &file_bytes)?;
    let root = ensure_user_situational_dialogue_character_bank()?;
    let safe_character_id = sanitize_user_character_id(&character_id)?;
    let safe_state = sanitize_user_character_state(&state)?;
    let extension = supported_character_image_extension(&file_name)
        .ok_or_else(|| "Format de pose utilisateur non supportÃ©".to_string())?;
    let state_dir = root
        .join("personnages")
        .join(&safe_character_id)
        .join(&safe_state);
    fs::create_dir_all(&state_dir).map_err(|err| err.to_string())?;
    let target = if make_default {
        archive_default_user_pose(&state_dir, &safe_state, None)?;
        state_dir.join(format!("{}.{}", safe_state, extension))
    } else {
        next_user_pose_path(&state_dir, &safe_state, &extension)
    };
    fs::write(target, file_bytes).map_err(|err| err.to_string())?;
    scan_user_situational_dialogue_character_bank()
}

#[tauri::command]
pub fn set_user_situational_dialogue_character_default_pose(
    character_id: String,
    state: String,
    asset_ref: String,
) -> Result<Vec<UserSituationalDialogueCharacterDescriptor>, String> {
    let root = ensure_user_situational_dialogue_character_bank()?;
    let safe_character_id = sanitize_user_character_id(&character_id)?;
    let safe_state = sanitize_user_character_state(&state)?;
    let source = safe_user_character_asset_path(&root, &asset_ref)?;
    let state_dir = root
        .join("personnages")
        .join(&safe_character_id)
        .join(&safe_state);
    let source_parent = source
        .parent()
        .ok_or_else(|| "Pose utilisateur introuvable".to_string())?;
    if source_parent
        .canonicalize()
        .map_err(|err| err.to_string())?
        != state_dir.canonicalize().map_err(|err| err.to_string())?
    {
        return Err("La pose ne correspond pas au state demandÃ©".to_string());
    }
    let extension = source
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("png")
        .to_ascii_lowercase();
    let target = state_dir.join(format!("{}.{}", safe_state, extension));
    if source != target {
        archive_default_user_pose(&state_dir, &safe_state, Some(&source))?;
        fs::rename(&source, &target).map_err(|err| err.to_string())?;
    }
    scan_user_situational_dialogue_character_bank()
}

#[tauri::command]
pub fn upload_user_situational_dialogue_character_preview(
    character_id: String,
    file_name: String,
    file_bytes: Vec<u8>,
) -> Result<Vec<UserSituationalDialogueCharacterDescriptor>, String> {
    validate_user_image_file(&file_name, &file_bytes)?;
    let root = ensure_user_situational_dialogue_character_bank()?;
    let safe_character_id = sanitize_user_character_id(&character_id)?;
    let extension = supported_character_image_extension(&file_name)
        .ok_or_else(|| "Format de preview utilisateur non supportÃ©".to_string())?;
    let character_dir = root.join("personnages").join(&safe_character_id);
    fs::create_dir_all(&character_dir).map_err(|err| err.to_string())?;
    let image_name = versioned_user_image_name("preview", &extension, &file_bytes);
    let target = character_dir.join(&image_name);
    fs::write(&target, file_bytes).map_err(|err| err.to_string())?;
    let preview_ref = format!("personnages/{}/{}", safe_character_id, image_name);
    let mut metadata = read_user_character_bank_metadata(&root)?;
    let mut previous_ref = None;
    if let Some(entry) = metadata
        .characters
        .iter_mut()
        .find(|entry| entry.id.eq_ignore_ascii_case(&safe_character_id))
    {
        previous_ref = entry.preview_ref.clone();
        entry.preview_ref = Some(preview_ref);
    }
    write_user_character_bank_metadata(&root, &metadata)?;
    remove_replaced_user_image(&root, previous_ref.as_deref(), &target);
    scan_user_situational_dialogue_character_bank()
}

#[tauri::command]
pub fn delete_user_situational_dialogue_character(
    character_id: String,
) -> Result<Vec<UserSituationalDialogueCharacterDescriptor>, String> {
    let root = ensure_user_situational_dialogue_character_bank()?;
    let safe_character_id = sanitize_user_character_id(&character_id)?;
    let character_dir = root.join("personnages").join(&safe_character_id);
    let canonical_root = root.canonicalize().map_err(|err| err.to_string())?;
    if character_dir.exists() {
        let canonical_character_dir = character_dir
            .canonicalize()
            .map_err(|err| err.to_string())?;
        if !canonical_character_dir.starts_with(canonical_root.join("personnages")) {
            return Err("Chemin de personnage utilisateur invalide".to_string());
        }
        fs::remove_dir_all(canonical_character_dir).map_err(|err| err.to_string())?;
    }
    let mut metadata = read_user_character_bank_metadata(&root)?;
    metadata
        .characters
        .retain(|entry| !entry.id.eq_ignore_ascii_case(&safe_character_id));
    write_user_character_bank_metadata(&root, &metadata)?;
    scan_user_situational_dialogue_character_bank()
}

#[tauri::command]
pub fn import_user_situational_dialogue_character(
    project_path: String,
    block_id: String,
    character_id: String,
) -> Result<SituationalDialogueCharacter, String> {
    let root = resolve_project_path(&project_path);
    let assets_dir = root.join("assets");
    fs::create_dir_all(&assets_dir).map_err(|err| err.to_string())?;

    let characters = scan_user_situational_dialogue_character_bank()?;
    let character = characters
        .into_iter()
        .find(|candidate| candidate.id == character_id)
        .ok_or_else(|| "Personnage utilisateur introuvable".to_string())?;

    let bank_root = user_situational_dialogue_character_bank_root()?;
    let character_slug = sanitize_filename(&character.id)
        .trim_matches('-')
        .trim_matches('_')
        .to_string();
    let character_slug = if character_slug.is_empty() {
        "character".to_string()
    } else {
        character_slug
    };
    let safe_block_id = sanitize_filename(&block_id);
    let imported_character_id = format!(
        "situational_dialogue_user_character_{}_{}",
        character_slug,
        compact_timestamp()
    );
    let mut poses = Vec::new();

    for (index, pose) in character.poses.iter().enumerate() {
        let source = safe_user_character_asset_path(&bank_root, &pose.asset_ref)?;
        let extension = source
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or("png")
            .to_ascii_lowercase();
        let safe_extension = if matches!(extension.as_str(), "jpg" | "jpeg" | "png" | "webp") {
            extension
        } else {
            "png".to_string()
        };
        let state_slug = sanitize_filename(&pose.state)
            .trim_matches('-')
            .trim_matches('_')
            .to_string();
        let state_slug = if state_slug.is_empty() {
            "pose".to_string()
        } else {
            state_slug
        };
        let stored_ref = format!(
            "situational-dialogue/{}/characters/{}/{}-{:02}.{}",
            safe_block_id,
            character_slug,
            state_slug,
            index + 1,
            safe_extension
        );
        let destination = assets_dir.join(&stored_ref);
        if let Some(parent) = destination.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::copy(&source, &destination).map_err(|err| err.to_string())?;
        let pose_id = format!("{}_pose_{}", imported_character_id, index + 1);
        poses.push(crate::models::SituationalDialogueCharacterPose {
            id: pose_id.clone(),
            label: pose.label.clone(),
            state: Some(pose.state.clone()),
            usage: Some(match pose.state.as_str() {
                "introduction" => "introduction".to_string(),
                "question" => "question".to_string(),
                "conclusion" => "conclusion".to_string(),
                "neutral" => "neutral".to_string(),
                _ => "response".to_string(),
            }),
            emotion: Some(match pose.state.as_str() {
                "positive" => "happy".to_string(),
                "negative" => "disappointed".to_string(),
                _ => "neutral".to_string(),
            }),
            asset_ref: Some(stored_ref),
        });
    }

    Ok(SituationalDialogueCharacter {
        id: imported_character_id,
        name: character.name,
        default_character_id: None,
        role: character.role,
        description: character.description,
        show_name_role: Some(true),
        background_ref: None,
        default_pose_id: poses.first().map(|pose| pose.id.clone()),
        poses,
    })
}

fn open_character_package(path: &Path) -> Result<ZipArchive<fs::File>, String> {
    let metadata = fs::metadata(path).map_err(|err| err.to_string())?;
    if !metadata.is_file() || metadata.len() > CHARACTER_PACKAGE_MAX_COMPRESSED_BYTES {
        return Err("Le paquet de personnages est absent ou trop volumineux".to_string());
    }
    let archive = ZipArchive::new(fs::File::open(path).map_err(|err| err.to_string())?)
        .map_err(|_| "Le fichier sélectionné n’est pas un paquet ZIP valide".to_string())?;
    if archive.len() > CHARACTER_PACKAGE_MAX_ENTRIES {
        return Err("Le paquet contient trop de fichiers".to_string());
    }
    Ok(archive)
}

fn read_character_package_manifest(path: &Path) -> Result<CharacterPackageManifest, String> {
    let mut archive = open_character_package(path)?;
    let mut file = archive
        .by_name("manifest.json")
        .map_err(|_| "Le manifeste du paquet de personnages est absent".to_string())?;
    if file.size() > CHARACTER_PACKAGE_MANIFEST_MAX_BYTES {
        return Err("Le manifeste du paquet est trop volumineux".to_string());
    }
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)
        .map_err(|err| err.to_string())?;
    let manifest: CharacterPackageManifest = serde_json::from_slice(&bytes)
        .map_err(|_| "Le manifeste du paquet de personnages est invalide".to_string())?;
    if manifest.format != CHARACTER_PACKAGE_FORMAT || manifest.version != CHARACTER_PACKAGE_VERSION
    {
        return Err("Cette version du paquet de personnages n’est pas prise en charge".to_string());
    }
    if manifest.characters.is_empty()
        || manifest.characters.len() > CHARACTER_PACKAGE_MAX_CHARACTERS
    {
        return Err("Le paquet doit contenir entre 1 et 200 personnages".to_string());
    }
    let mut portable_ids = HashSet::new();
    for character in &manifest.characters {
        if uuid::Uuid::parse_str(&character.portable_id).is_err()
            || !portable_ids.insert(character.portable_id.to_ascii_lowercase())
            || character.name.trim().is_empty()
        {
            return Err("Le manifeste contient un personnage invalide ou dupliqué".to_string());
        }
        if let Some(preview_file) = &character.preview_file {
            validate_character_package_file_name(preview_file)?;
        }
    }
    Ok(manifest)
}

fn validate_character_package_file_name(file_name: &str) -> Result<(), String> {
    let path = Path::new(file_name);
    if file_name.is_empty()
        || file_name
            .chars()
            .any(|character| character.is_control() || "\\/:*?\"<>|".contains(character))
        || path.file_name().and_then(|value| value.to_str()) != Some(file_name)
        || supported_character_image_extension(file_name).is_none()
    {
        return Err("Le paquet contient un nom de fichier image invalide".to_string());
    }
    Ok(())
}

fn normalized_character_package_entry_path(name: &str) -> Result<Vec<String>, String> {
    if name.contains('\\') || name.starts_with('/') || name.ends_with('/') {
        return Err("Le paquet contient un chemin interdit".to_string());
    }
    let parts = name.split('/').map(str::to_string).collect::<Vec<_>>();
    if parts
        .iter()
        .any(|part| part.is_empty() || part == "." || part == "..")
    {
        return Err("Le paquet contient un chemin interdit".to_string());
    }
    Ok(parts)
}

#[tauri::command]
pub fn export_user_situational_dialogue_characters(
    character_ids: Vec<String>,
    destination_path: String,
) -> Result<String, String> {
    let _guard = CHARACTER_PACKAGE_WRITE_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .map_err(|_| "Gestionnaire de paquets de personnages indisponible".to_string())?;
    if character_ids.is_empty() || character_ids.len() > CHARACTER_PACKAGE_MAX_CHARACTERS {
        return Err("Sélectionnez entre 1 et 200 personnages".to_string());
    }
    let root = ensure_user_situational_dialogue_character_bank()?;
    let mut metadata = read_user_character_bank_metadata(&root)?;
    let mut selected = Vec::new();
    let mut changed = false;
    let mut requested = HashSet::new();
    for requested_id in character_ids {
        let safe_id = sanitize_user_character_id(&requested_id)?;
        if !requested.insert(safe_id.to_ascii_lowercase()) {
            continue;
        }
        let entry = metadata
            .characters
            .iter_mut()
            .find(|entry| entry.id.eq_ignore_ascii_case(&safe_id))
            .ok_or_else(|| format!("Personnage introuvable : {}", safe_id))?;
        let portable_id = entry
            .portable_id
            .clone()
            .filter(|value| uuid::Uuid::parse_str(value).is_ok())
            .unwrap_or_else(|| {
                changed = true;
                uuid::Uuid::new_v4().to_string()
            });
        entry.portable_id = Some(portable_id.clone());
        selected.push(CharacterPackageEntry {
            portable_id,
            source_id: entry.id.clone(),
            name: entry
                .name
                .clone()
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| humanize_default_character_name(&entry.id)),
            role: entry.role.clone(),
            description: entry.description.clone(),
            preview_file: entry.preview_ref.as_ref().and_then(|asset_ref| {
                Path::new(asset_ref)
                    .file_name()
                    .and_then(|value| value.to_str())
                    .map(str::to_string)
            }),
        });
    }
    if changed {
        write_user_character_bank_metadata(&root, &metadata)?;
    }
    let destination = PathBuf::from(destination_path);
    let parent = destination
        .parent()
        .ok_or_else(|| "Chemin d’export invalide".to_string())?;
    fs::create_dir_all(parent).map_err(|err| err.to_string())?;
    let destination_name = destination
        .file_name()
        .and_then(|v| v.to_str())
        .unwrap_or("personnages.zip");
    let temporary = unique_sibling_path(parent, destination_name, "tmp");
    let backup = unique_sibling_path(parent, destination_name, "bak");
    let result = (|| -> Result<(), String> {
        let file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|err| err.to_string())?;
        let mut zip = ZipWriter::new(file);
        let options = SimpleFileOptions::default().compression_method(CompressionMethod::Deflated);
        let manifest = CharacterPackageManifest {
            format: CHARACTER_PACKAGE_FORMAT.to_string(),
            version: CHARACTER_PACKAGE_VERSION,
            exported_at: now_iso(),
            characters: selected.clone(),
        };
        zip.start_file("manifest.json", options)
            .map_err(|err| err.to_string())?;
        zip.write_all(&serde_json::to_vec_pretty(&manifest).map_err(|err| err.to_string())?)
            .map_err(|err| err.to_string())?;
        for character in &selected {
            let source_root = root.join("personnages").join(&character.source_id);
            if !source_root.is_dir() {
                return Err(format!(
                    "Dossier du personnage introuvable : {}",
                    character.name
                ));
            }
            let mut pending = vec![source_root.clone()];
            while let Some(directory) = pending.pop() {
                for child in fs::read_dir(&directory).map_err(|err| err.to_string())? {
                    let child = child.map_err(|err| err.to_string())?;
                    let kind = child.file_type().map_err(|err| err.to_string())?;
                    if kind.is_symlink() {
                        return Err("Les liens symboliques ne sont pas exportables".to_string());
                    }
                    if kind.is_dir() {
                        pending.push(child.path());
                        continue;
                    }
                    if !kind.is_file() || !is_supported_character_image_path(&child.path()) {
                        continue;
                    }
                    let relative = child
                        .path()
                        .strip_prefix(&source_root)
                        .map_err(|err| err.to_string())?
                        .components()
                        .map(|part| part.as_os_str().to_string_lossy().to_string())
                        .collect::<Vec<_>>()
                        .join("/");
                    zip.start_file(
                        format!("characters/{}/{}", character.portable_id, relative),
                        options,
                    )
                    .map_err(|err| err.to_string())?;
                    std::io::copy(
                        &mut fs::File::open(child.path()).map_err(|err| err.to_string())?,
                        &mut zip,
                    )
                    .map_err(|err| err.to_string())?;
                }
            }
        }
        zip.finish()
            .map_err(|err| err.to_string())?
            .sync_all()
            .map_err(|err| err.to_string())?;
        if destination.exists() {
            fs::rename(&destination, &backup).map_err(|err| err.to_string())?;
        }
        if let Err(error) = fs::rename(&temporary, &destination) {
            if backup.exists() {
                let _ = fs::rename(&backup, &destination);
            }
            return Err(error.to_string());
        }
        if backup.exists() {
            let _ = fs::remove_file(&backup);
        }
        Ok(())
    })();
    if temporary.exists() {
        let _ = fs::remove_file(&temporary);
    }
    if result.is_err() && backup.exists() && !destination.exists() {
        let _ = fs::rename(&backup, &destination);
    }
    result?;
    Ok(destination.to_string_lossy().to_string())
}

#[tauri::command]
pub fn inspect_user_situational_dialogue_character_package(
    package_path: String,
) -> Result<CharacterPackageInspection, String> {
    let manifest = read_character_package_manifest(Path::new(&package_path))?;
    let metadata =
        read_user_character_bank_metadata(&ensure_user_situational_dialogue_character_bank()?)?;
    let conflicts = manifest
        .characters
        .iter()
        .filter_map(|incoming| {
            metadata
                .characters
                .iter()
                .find(|existing| {
                    existing
                        .portable_id
                        .as_deref()
                        .map(|value| value.eq_ignore_ascii_case(&incoming.portable_id))
                        .unwrap_or(false)
                })
                .map(|existing| CharacterPackageConflict {
                    portable_id: incoming.portable_id.clone(),
                    name: incoming.name.clone(),
                    existing_name: existing
                        .name
                        .clone()
                        .unwrap_or_else(|| humanize_default_character_name(&existing.id)),
                })
        })
        .collect();
    Ok(CharacterPackageInspection {
        character_count: manifest.characters.len(),
        names: manifest
            .characters
            .iter()
            .map(|entry| entry.name.clone())
            .collect(),
        conflicts,
    })
}

#[tauri::command]
pub fn import_user_situational_dialogue_character_package(
    package_path: String,
    conflict_policy: String,
) -> Result<CharacterPackageImportResult, String> {
    let _guard = CHARACTER_PACKAGE_WRITE_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .map_err(|_| "Gestionnaire de paquets de personnages indisponible".to_string())?;
    if !matches!(conflict_policy.as_str(), "update" | "copy" | "skip") {
        return Err("Politique de conflit invalide".to_string());
    }
    let package = PathBuf::from(package_path);
    let manifest = read_character_package_manifest(&package)?;
    let root = ensure_user_situational_dialogue_character_bank()?;
    let mut metadata = read_user_character_bank_metadata(&root)?;
    let staging = root.join(format!(".character-import-{}", uuid::Uuid::new_v4()));
    fs::create_dir_all(staging.join("personnages")).map_err(|err| err.to_string())?;
    let mut targets = HashMap::new();
    let mut imported_count = 0;
    let mut updated_count = 0;
    let mut copied_count = 0;
    for incoming in &manifest.characters {
        let existing_index = metadata.characters.iter().position(|entry| {
            entry
                .portable_id
                .as_deref()
                .map(|value| value.eq_ignore_ascii_case(&incoming.portable_id))
                .unwrap_or(false)
        });
        if existing_index.is_some() && conflict_policy == "skip" {
            continue;
        }
        let (target_id, portable_id) = match existing_index {
            Some(index) if conflict_policy == "update" => {
                updated_count += 1;
                (
                    metadata.characters[index].id.clone(),
                    incoming.portable_id.clone(),
                )
            }
            Some(_) => {
                copied_count += 1;
                (
                    unique_user_character_id(&root, &metadata, &incoming.name, None),
                    uuid::Uuid::new_v4().to_string(),
                )
            }
            None => {
                imported_count += 1;
                (
                    unique_user_character_id(&root, &metadata, &incoming.name, None),
                    incoming.portable_id.clone(),
                )
            }
        };
        let preview_ref = incoming
            .preview_file
            .as_ref()
            .map(|name| format!("personnages/{}/{}", target_id, name));
        let next_entry = UserCharacterBankEntry {
            id: target_id.clone(),
            resource_modified_at: None,
            portable_id: Some(portable_id),
            name: Some(incoming.name.trim().to_string()),
            role: incoming.role.clone(),
            description: incoming.description.clone(),
            preview_ref,
        };
        if let Some(index) = existing_index.filter(|_| conflict_policy == "update") {
            metadata.characters[index] = next_entry;
        } else {
            metadata.characters.push(next_entry);
        }
        fs::create_dir_all(staging.join("personnages").join(&target_id))
            .map_err(|err| err.to_string())?;
        targets.insert(incoming.portable_id.to_ascii_lowercase(), target_id);
    }
    let operation = (|| -> Result<(), String> {
        let mut archive = open_character_package(&package)?;
        let mut expanded = 0_u64;
        let known_portable_ids = manifest
            .characters
            .iter()
            .map(|character| character.portable_id.to_ascii_lowercase())
            .collect::<HashSet<_>>();
        let mut archive_paths = HashSet::new();
        for index in 0..archive.len() {
            let mut entry = archive.by_index(index).map_err(|err| err.to_string())?;
            if entry.name() == "manifest.json" {
                continue;
            }
            if entry.is_dir()
                || entry
                    .unix_mode()
                    .map(|mode| mode & 0o170000 == 0o120000)
                    .unwrap_or(false)
            {
                return Err("Le paquet contient un type d’entrée interdit".to_string());
            }
            let parts = normalized_character_package_entry_path(entry.name())?;
            if !archive_paths.insert(entry.name().to_ascii_lowercase()) {
                return Err("Le paquet contient deux fichiers au même emplacement".to_string());
            }
            if (parts.len() != 3 && parts.len() != 4) || parts[0] != "characters" {
                return Err("Le paquet contient une arborescence invalide".to_string());
            }
            if !known_portable_ids.contains(&parts[1].to_ascii_lowercase()) {
                return Err(
                    "Le paquet contient les ressources d’un personnage non déclaré".to_string(),
                );
            }
            let Some(target_id) = targets.get(&parts[1].to_ascii_lowercase()) else {
                continue;
            };
            let relative = if parts.len() == 3 {
                PathBuf::from(&parts[2])
            } else {
                sanitize_user_character_state(&parts[2])?;
                PathBuf::from(&parts[2]).join(&parts[3])
            };
            let file_name = relative
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or_default();
            validate_character_package_file_name(file_name)?;
            let size = entry.size();
            if size > CHARACTER_PACKAGE_MAX_ENTRY_BYTES {
                return Err("Une image du paquet est trop volumineuse".to_string());
            }
            expanded = expanded
                .checked_add(size)
                .ok_or_else(|| "Taille du paquet invalide".to_string())?;
            if expanded > CHARACTER_PACKAGE_MAX_EXPANDED_BYTES {
                return Err("Le paquet décompressé est trop volumineux".to_string());
            }
            let mut bytes = Vec::with_capacity(size as usize);
            entry
                .read_to_end(&mut bytes)
                .map_err(|err| err.to_string())?;
            validate_user_image_file(file_name, &bytes)?;
            let destination = staging.join("personnages").join(target_id).join(relative);
            if let Some(parent) = destination.parent() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
            fs::write(destination, bytes).map_err(|err| err.to_string())?;
        }
        for incoming in &manifest.characters {
            let Some(target_id) = targets.get(&incoming.portable_id.to_ascii_lowercase()) else {
                continue;
            };
            let character_dir = staging.join("personnages").join(target_id);
            if let Some(preview) = &incoming.preview_file {
                if !character_dir.join(preview).is_file() {
                    return Err(format!(
                        "L’aperçu du personnage « {} » est absent",
                        incoming.name
                    ));
                }
            }
        }
        let staged_index = staging.join("character-bank.json");
        fs::write(
            &staged_index,
            format!(
                "{}\n",
                serde_json::to_string_pretty(&metadata).map_err(|err| err.to_string())?
            ),
        )
        .map_err(|err| err.to_string())?;
        let backup_root = staging.join("backup");
        fs::create_dir_all(&backup_root).map_err(|err| err.to_string())?;
        let mut installed = Vec::new();
        for target_id in targets.values() {
            let destination = root.join("personnages").join(target_id);
            let backup = backup_root.join(target_id);
            if destination.exists() {
                if let Err(error) = fs::rename(&destination, &backup) {
                    for previous in installed.iter().rev() {
                        let previous_destination = root.join("personnages").join(previous);
                        let _ = fs::remove_dir_all(&previous_destination);
                        let previous_backup = backup_root.join(previous);
                        if previous_backup.exists() {
                            let _ = fs::rename(previous_backup, previous_destination);
                        }
                    }
                    return Err(error.to_string());
                }
            }
            if let Err(error) =
                fs::rename(staging.join("personnages").join(target_id), &destination)
            {
                if backup.exists() {
                    let _ = fs::rename(&backup, &destination);
                }
                for previous in installed.iter().rev() {
                    let previous_destination = root.join("personnages").join(previous);
                    let _ = fs::remove_dir_all(&previous_destination);
                    let previous_backup = backup_root.join(previous);
                    if previous_backup.exists() {
                        let _ = fs::rename(previous_backup, previous_destination);
                    }
                }
                return Err(error.to_string());
            }
            installed.push(target_id.clone());
        }
        let index_path = root.join("character-bank.json");
        let old_index = staging.join("character-bank.previous.json");
        if index_path.exists() {
            if let Err(error) = fs::rename(&index_path, &old_index) {
                for target_id in installed.iter().rev() {
                    let destination = root.join("personnages").join(target_id);
                    let _ = fs::remove_dir_all(&destination);
                    let backup = backup_root.join(target_id);
                    if backup.exists() {
                        let _ = fs::rename(backup, destination);
                    }
                }
                return Err(error.to_string());
            }
        }
        if let Err(error) = fs::rename(&staged_index, &index_path) {
            for target_id in installed.iter().rev() {
                let destination = root.join("personnages").join(target_id);
                let _ = fs::remove_dir_all(&destination);
                let backup = backup_root.join(target_id);
                if backup.exists() {
                    let _ = fs::rename(backup, destination);
                }
            }
            if old_index.exists() {
                let _ = fs::rename(&old_index, &index_path);
            }
            return Err(error.to_string());
        }
        Ok(())
    })();
    if staging.exists() {
        let _ = fs::remove_dir_all(&staging);
    }
    operation?;
    Ok(CharacterPackageImportResult {
        characters: scan_user_situational_dialogue_character_bank()?,
        imported_count,
        updated_count,
        copied_count,
    })
}

