    crate::resource_bank_store::remove(&root, crate::resource_bank_store::Family::Assistants, &assistant_id)?;
    let mut metadata = read_user_assistant_bank_metadata(&root)?;
    let assistant = metadata
        .assistants
        .iter()
        .find(|candidate| candidate.id == assistant_id)
        .cloned();
    metadata
        .assistants
        .retain(|assistant| assistant.id != assistant_id);
    let assistants = normalize_glossary_assistants(metadata.assistants);
