fn read_user_assistant_bank_metadata(root: &Path) -> Result<UserAssistantBankFile, String> {
    let values = crate::resource_bank_store::all(root, crate::resource_bank_store::Family::Assistants)?;
    let mut metadata = UserAssistantBankFile { version: 1, assistants: serde_json::from_value(serde_json::json!(values)).map_err(|e| e.to_string())? };
    sanitize_rich_text_fields(&mut metadata)?;
    Ok(metadata)
}

fn write_user_assistant_bank_metadata(root: &Path, metadata: &UserAssistantBankFile) -> Result<(), String> {
    let values = metadata.assistants.iter().map(serde_json::to_value).collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())?;
    crate::resource_bank_store::upsert(root, crate::resource_bank_store::Family::Assistants, &values)
}

fn normalize_glossary_assistants(
    assistants: Vec<GlossaryAssistantResource>,
) -> Vec<GlossaryAssistantResource> {
    let mut assistants = assistants
        .into_iter()
        .map(|mut assistant| {
            assistant.shortcut = "Maj+<".to_string();
            assistant.assistant_enabled = true;
            assistant
                .entries
                .sort_by(|left, right| left.term.to_lowercase().cmp(&right.term.to_lowercase()));
            assistant
        })
        .collect::<Vec<_>>();
    assistants.sort_by(|left, right| left.name.to_lowercase().cmp(&right.name.to_lowercase()));
    assistants
}

fn sync_glossary_assistants_to_projects(
    bank_root: &Path,
    assistants: &[GlossaryAssistantResource],
    project_paths_to_sync: &[String],
) -> Result<(), String> {
    for project_path in project_paths_to_sync {
        if project_path.trim().is_empty() {
            continue;
        }
        let mut project = load_project_from_path(project_path)?;
        let root = resolve_project_path(project_path);
        let assets_dir = root.join("assets");
        let mut project_assistants = Vec::new();
        for assistant in assistants {
            if !assistant
                .project_paths
                .iter()
                .any(|path| path.eq_ignore_ascii_case(project_path))
            {
                continue;
            }
            let mut copied = assistant.clone();
            copied.project_paths = Vec::new();
            copied.collection_ids = Vec::new();
            copied.lesson_ids = Vec::new();
            if let Some(avatar_ref) = assistant
                .avatar_ref
                .as_deref()
                .filter(|value| !value.trim().is_empty())
            {
                let normalized = normalize_scorm_asset_ref(avatar_ref);
                let source = bank_root.join(&normalized);
                if source.exists() {
                    let extension = source
                        .extension()
                        .and_then(|value| value.to_str())
                        .unwrap_or("png");
                    let target_ref = format!(
                        "assistants/{}/avatar.{}",
                        sanitize_filename(&assistant.id),
                        extension
                    );
                    let target = assets_dir.join(&target_ref);
                    if let Some(parent) = target.parent() {
                        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
                    }
                    fs::copy(&source, &target).map_err(|err| err.to_string())?;
                    copied.avatar_ref = Some(target_ref);
                }
            }
            project_assistants.push(copied);
        }
        project.glossary_assistants = normalize_glossary_assistants(project_assistants);
        save_project_to_path(project_path, &project)?;
    }
    Ok(())
}

fn scan_default_situational_dialogue_character_roots(
    character_roots: Vec<PathBuf>,
) -> Result<Vec<DefaultSituationalDialogueCharacterDescriptor>, String> {
    if character_roots.is_empty() {
        return Ok(Vec::new());
    }

    let ordered_states = [
        "introduction",
        "neutral",
        "question",
        "positive",
        "negative",
        "conclusion",
    ];
    let mut characters = Vec::new();
    let mut seen_character_ids = HashSet::new();

    for characters_root in character_roots {
        for entry in fs::read_dir(&characters_root).map_err(|err| err.to_string())? {
            let entry = entry.map_err(|err| err.to_string())?;
            let path = entry.path();
            if !entry.file_type().map_err(|err| err.to_string())?.is_dir() {
                continue;
            }

            let id = entry.file_name().to_string_lossy().trim().to_string();
            if id.is_empty() || !seen_character_ids.insert(id.to_ascii_lowercase()) {
                continue;
            }

            let mut poses = Vec::new();
            for state in ordered_states {
                let state_dir = path.join(state);
                if !state_dir.exists() || !state_dir.is_dir() {
                    continue;
                }

                let mut files = fs::read_dir(&state_dir)
                    .map_err(|err| err.to_string())?
                    .filter_map(|child| child.ok())
                    .filter(|child| child.file_type().map(|ft| ft.is_file()).unwrap_or(false))
                    .map(|child| child.path())
                    .filter(|child| {
                        child
                            .extension()
                            .and_then(|value| value.to_str())
                            .map(|ext| {
                                matches!(
                                    ext.to_ascii_lowercase().as_str(),
                                    "png" | "webp" | "jpg" | "jpeg"
                                )
                            })
                            .unwrap_or(false)
                    })
                    .collect::<Vec<_>>();
                files.sort();

                if let Some(file) = files.into_iter().next() {
                    let filename = file
                        .file_name()
                        .and_then(|value| value.to_str())
                        .unwrap_or_default()
                        .to_string();
                    poses.push(DefaultSituationalDialogueCharacterPoseDescriptor {
                        state: state.to_string(),
                        label: format!("{} - {}", state, filename),
                        asset_ref: format!("default-characters/{}/{}/{}", id, state, filename),
                    });
                }
            }

            if poses.is_empty() {
                continue;
            }

            characters.push(DefaultSituationalDialogueCharacterDescriptor {
                id: id.clone(),
                name: humanize_default_character_name(&id),
                role: None,
                description: None,
                poses,
            });
        }
    }

    characters.sort_by(|left, right| left.name.cmp(&right.name));
    Ok(characters)
}

fn user_situational_dialogue_character_bank_root() -> Result<PathBuf, String> {
    if let Some(root) = distribution::current().resources_root() {
        return Ok(root.join("user-characters"));
    }
    let documents = std::env::var_os("USERPROFILE")
        .map(PathBuf::from)
        .map(|profile| profile.join("Documents"))
        .ok_or_else(|| "Impossible de trouver le dossier Documents utilisateur".to_string())?;
    Ok(documents.join("PAIDEIA").join("user-characters"))
}

fn ensure_user_situational_dialogue_character_bank() -> Result<PathBuf, String> {
    let root = user_situational_dialogue_character_bank_root()?;
    fs::create_dir_all(root.join("personnages")).map_err(|err| err.to_string())?;
    let index_path = root.join("character-bank.json");
    if !index_path.exists() {
        fs::write(
            &index_path,
            "{\n  \"version\": 1,\n  \"characters\": []\n}\n",
        )
        .map_err(|err| err.to_string())?;
    }
    Ok(root)
}

fn scan_user_situational_dialogue_character_bank(
) -> Result<Vec<UserSituationalDialogueCharacterDescriptor>, String> {
    let root = ensure_user_situational_dialogue_character_bank()?;
    let metadata = read_user_character_bank_metadata(&root)?;
    let characters_dir = root.join("personnages");
    if !characters_dir.exists() {
        return Ok(Vec::new());
    }

    let ordered_states = [
        "introduction",
        "question",
        "neutral",
        "positive",
        "negative",
        "conclusion",
    ];
    let mut characters = Vec::new();

    for entry in fs::read_dir(&characters_dir).map_err(|err| err.to_string())? {
        let entry = entry.map_err(|err| err.to_string())?;
        let path = entry.path();
        if !entry.file_type().map_err(|err| err.to_string())?.is_dir() {
            continue;
        }
        let id = entry.file_name().to_string_lossy().trim().to_string();
        if id.is_empty() {
            continue;
        }
        let bank_entry = metadata
            .characters
            .iter()
            .find(|candidate| candidate.id.eq_ignore_ascii_case(&id));
        let mut poses = Vec::new();
        let mut resource_modified_at = bank_entry.and_then(|entry| entry.resource_modified_at)
            .max(crate::resource_bank_store::file_modified_at(&path));
        for state in ordered_states {
            let state_dir = path.join(state);
            if !state_dir.exists() || !state_dir.is_dir() {
                continue;
            }
            migrate_legacy_default_user_pose_names(&state_dir, state)?;
            resource_modified_at = resource_modified_at.max(crate::resource_bank_store::file_modified_at(&state_dir));
            let mut files = fs::read_dir(&state_dir)
                .map_err(|err| err.to_string())?
                .filter_map(|child| child.ok())
                .filter(|child| child.file_type().map(|ft| ft.is_file()).unwrap_or(false))
                .map(|child| child.path())
                .filter(|child| is_supported_character_image_path(child))
                .collect::<Vec<_>>();
            files.sort_by(|left, right| {
                character_pose_sort_key(left)
                    .cmp(&character_pose_sort_key(right))
                    .then_with(|| left.cmp(right))
            });
            for file in files {
                resource_modified_at = resource_modified_at.max(crate::resource_bank_store::file_modified_at(&file));
                let filename = file
                    .file_name()
                    .and_then(|value| value.to_str())
                    .unwrap_or_default()
                    .to_string();
                poses.push(UserSituationalDialogueCharacterPoseDescriptor {
                    state: state.to_string(),
                    label: format!("{} - {}", state, filename),
                    asset_ref: format!("personnages/{}/{}/{}", id, state, filename),
                });
            }
        }
        let preview_ref = bank_entry
            .and_then(|entry| entry.preview_ref.clone())
            .filter(|asset_ref| safe_user_character_asset_path(&root, asset_ref).is_ok());
        characters.push(UserSituationalDialogueCharacterDescriptor {
            id: id.clone(),
            resource_modified_at,
            name: bank_entry
                .and_then(|entry| entry.name.clone())
                .filter(|name| !name.trim().is_empty())
                .unwrap_or_else(|| humanize_default_character_name(&id)),
            role: bank_entry.and_then(|entry| entry.role.clone()),
            description: bank_entry.and_then(|entry| entry.description.clone()),
            preview_ref,
            poses,
        });
    }

    characters.sort_by(|left, right| left.name.cmp(&right.name));
    Ok(characters)
}

fn read_user_character_bank_metadata(root: &Path) -> Result<UserCharacterBankFile, String> {
    let index_path = root.join("character-bank.json");
    let content = fs::read_to_string(index_path).map_err(|err| err.to_string())?;
    serde_json::from_str(&content).or_else(|_| {
        Ok(UserCharacterBankFile {
            version: 1,
            characters: Vec::new(),
        })
    })
}

fn write_user_character_bank_metadata(
    root: &Path,
    metadata: &UserCharacterBankFile,
) -> Result<(), String> {
    let index_path = root.join("character-bank.json");
    let previous = read_user_character_bank_metadata(root).ok();
    let mut metadata = metadata.clone();
    for entry in &mut metadata.characters {
        let old = previous.as_ref().and_then(|bank| bank.characters.iter().find(|old| old.id == entry.id));
        entry.resource_modified_at = old.and_then(|old| old.resource_modified_at);
        if old != Some(entry) {
            entry.resource_modified_at = Some(Utc::now().timestamp_millis());
        }
    }
    let content = serde_json::to_string_pretty(&metadata).map_err(|err| err.to_string())?;
    fs::write(index_path, format!("{}\n", content)).map_err(|err| err.to_string())
}

fn unique_user_character_id(
    root: &Path,
    metadata: &UserCharacterBankFile,
    wanted: &str,
    current_id: Option<&str>,
) -> String {
    let base = sanitize_user_character_id_lossy(wanted);
    let base = if base.is_empty() {
        format!("personnage-{}", compact_timestamp())
    } else {
        base
    };
    let current = current_id.map(|value| value.to_ascii_lowercase());
    let mut candidate = base.clone();
    let mut index = 1;
    loop {
        let candidate_lower = candidate.to_ascii_lowercase();
        let is_current = current.as_deref() == Some(candidate_lower.as_str());
        let metadata_exists = metadata
            .characters
            .iter()
            .any(|entry| entry.id.eq_ignore_ascii_case(&candidate));
        let dir_exists = root.join("personnages").join(&candidate).exists();
        if is_current || (!metadata_exists && !dir_exists) {
            return candidate;
        }
        candidate = format!("{}_{}", base, index);
        index += 1;
    }
}

fn sanitize_user_character_id_lossy(value: &str) -> String {
    let mut result = String::new();
    let mut last_was_separator = false;
    for character in value.trim().chars() {
        if character == '/' || character == '\\' || character == ':' {
            if !last_was_separator {
                result.push('-');
                last_was_separator = true;
            }
            continue;
        }
        if character.is_alphanumeric() {
            result.push(character);
            last_was_separator = false;
        } else if !last_was_separator {
            result.push('-');
            last_was_separator = true;
        }
    }
    result.trim_matches('-').trim_matches('_').to_string()
}

fn next_user_pose_path(state_dir: &Path, state: &str, extension: &str) -> PathBuf {
    let mut index = 1;
    loop {
        let candidate = state_dir.join(format!("{}_{}.{}", state, index, extension));
        if !candidate.exists() {
            return candidate;
        }
        index += 1;
    }
}

fn default_user_pose_files(state_dir: &Path, state: &str) -> Result<Vec<PathBuf>, String> {
    if !state_dir.exists() {
        return Ok(Vec::new());
    }
    let mut files = fs::read_dir(state_dir)
        .map_err(|err| err.to_string())?
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .file_type()
                .map(|kind| kind.is_file())
                .unwrap_or(false)
        })
        .map(|entry| entry.path())
        .filter(|path| {
            is_supported_character_image_path(path)
                && path
                    .file_stem()
                    .and_then(|value| value.to_str())
                    .map(|stem| stem.eq_ignore_ascii_case(state))
                    .unwrap_or(false)
        })
        .collect::<Vec<_>>();
    files.sort();
    Ok(files)
}

fn archive_default_user_pose(
    state_dir: &Path,
    state: &str,
    excluded: Option<&Path>,
) -> Result<(), String> {
    for file in default_user_pose_files(state_dir, state)? {
        if excluded.map(|path| path == file.as_path()).unwrap_or(false) {
            continue;
        }
        let extension = file
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or("png")
            .to_ascii_lowercase();
        let archived = next_user_pose_path(state_dir, state, &extension);
        fs::rename(&file, archived).map_err(|err| err.to_string())?;
    }
    Ok(())
}

fn migrate_legacy_default_user_pose_names(state_dir: &Path, state: &str) -> Result<(), String> {
    if !state_dir.exists() {
        return Ok(());
    }
    let mut files = fs::read_dir(state_dir)
        .map_err(|err| err.to_string())?
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .file_type()
                .map(|kind| kind.is_file())
                .unwrap_or(false)
        })
        .map(|entry| entry.path())
        .filter(|path| {
            is_supported_character_image_path(path)
                && path
                    .file_stem()
                    .and_then(|value| value.to_str())
                    .map(|stem| {
                        let normalized = stem.to_ascii_lowercase();
                        normalized == "default"
                            || normalized.starts_with("default-")
                            || normalized.starts_with("default_")
                    })
                    .unwrap_or(false)
        })
        .collect::<Vec<_>>();
    files.sort_by(|left, right| {
        character_pose_sort_key(left)
            .cmp(&character_pose_sort_key(right))
            .then_with(|| left.cmp(right))
    });
    for file in files {
        let extension = file
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or("png")
            .to_ascii_lowercase();
        let default_target = state_dir.join(format!("{}.{}", state, extension));
        let target = if !default_target.exists() {
            default_target
        } else {
            next_user_pose_path(state_dir, state, &extension)
        };
        if file != target {
            fs::rename(&file, target).map_err(|err| err.to_string())?;
        }
    }
    Ok(())
}

fn sanitize_user_character_id(value: &str) -> Result<String, String> {
    let id = sanitize_user_character_id_lossy(value);
    if id.is_empty()
        || id.contains("..")
        || id.contains('/')
        || id.contains('\\')
        || Path::new(&id).is_absolute()
    {
        return Err("Identifiant de personnage utilisateur invalide".to_string());
    }
    Ok(id)
}

fn sanitize_user_character_state(value: &str) -> Result<String, String> {
    let state = value.trim().to_ascii_lowercase();
    if matches!(
        state.as_str(),
        "introduction" | "neutral" | "question" | "positive" | "negative" | "conclusion"
    ) {
        Ok(state)
    } else {
        Err("State de pose utilisateur invalide".to_string())
    }
}

fn supported_character_image_extension(file_name: &str) -> Option<String> {
    let extension = Path::new(file_name)
        .extension()
        .and_then(|value| value.to_str())?
        .to_ascii_lowercase();
    if matches!(extension.as_str(), "jpg" | "jpeg" | "png" | "webp") {
        Some(extension)
    } else {
        None
    }
}

fn versioned_user_image_name(stem: &str, extension: &str, bytes: &[u8]) -> String {
    format!("{}-{:x}.{}", stem, Sha256::digest(bytes), extension)
}

fn remove_replaced_user_image(root: &Path, previous_ref: Option<&str>, target: &Path) {
    let Some(previous_ref) = previous_ref else {
        return;
    };
    let relative = Path::new(previous_ref);
    if relative.is_absolute()
        || relative
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return;
    }
    let previous = root.join(relative);
    if previous != target && previous.parent() == target.parent() {
        let _ = fs::remove_file(previous);
    }
}

fn is_supported_character_image_path(path: &Path) -> bool {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|ext| {
            matches!(
                ext.to_ascii_lowercase().as_str(),
                "jpg" | "jpeg" | "png" | "webp"
            )
        })
        .unwrap_or(false)
}

fn character_pose_sort_key(path: &Path) -> (u8, String) {
    let filename = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let state = path
        .parent()
        .and_then(|parent| parent.file_name())
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let rank = if filename == format!("{}.png", state)
        || filename == format!("{}.jpg", state)
        || filename == format!("{}.jpeg", state)
        || filename == format!("{}.webp", state)
        || filename.starts_with("default.")
        || filename.starts_with("default_")
        || filename.starts_with("default-")
    {
        0
    } else {
        1
    };
    (rank, filename)
}

fn safe_user_character_asset_path(root: &Path, asset_ref: &str) -> Result<PathBuf, String> {
    let normalized = asset_ref.replace('\\', "/");
    if normalized.contains("..") || normalized.starts_with('/') {
        return Err("Chemin de pose utilisateur invalide".to_string());
    }
    let path = root.join(normalized);
    let canonical_root = root.canonicalize().map_err(|err| err.to_string())?;
    let canonical_path = path.canonicalize().map_err(|err| err.to_string())?;
    if !canonical_path.starts_with(&canonical_root) || !canonical_path.is_file() {
        return Err("Pose utilisateur introuvable".to_string());
    }
    if !is_supported_character_image_path(&canonical_path) {
        return Err("Format de pose utilisateur non supportÃ©".to_string());
    }
    Ok(canonical_path)
}

static PENDING_PAIDEIA_ARCHIVES: std::sync::LazyLock<
    std::sync::Mutex<std::collections::VecDeque<String>>,
> = std::sync::LazyLock::new(|| {
    std::sync::Mutex::new(
        std::env::args()
            .skip(1)
            .filter(|arg| arg.to_ascii_lowercase().ends_with(".paideia"))
            .collect(),
    )
});

pub(crate) fn queue_paideia_archives(args: Vec<String>, cwd: &str) {
    let mut pending = PENDING_PAIDEIA_ARCHIVES
        .lock()
        .unwrap_or_else(|err| err.into_inner());
    for arg in args
        .into_iter()
        .skip(1)
        .filter(|arg| arg.to_ascii_lowercase().ends_with(".paideia"))
    {
        let path = PathBuf::from(arg);
        let path = if path.is_absolute() {
            path
        } else {
            Path::new(cwd).join(path)
        };
        let path = path.to_string_lossy().into_owned();
        if !pending.contains(&path) {
            pending.push_back(path);
        }
    }
}

#[tauri::command]
pub fn get_startup_paideia_archive() -> Option<String> {
    PENDING_PAIDEIA_ARCHIVES
        .lock()
        .unwrap_or_else(|err| err.into_inner())
        .pop_front()
}

