#[tauri::command]
pub fn activate_library_asset_root(app: AppHandle, library_root: String) -> Result<String, String> {
    let root = canonical_existing_directory(&library_root)?;
    let default_root = default_user_projects_root()?
        .canonicalize()
        .map_err(|err| format!("Bibliothèque PAIDEIA par défaut inaccessible : {err}"))?;
    let configured_root = read_active_library_root(&app)?;

    if let Some(configured_root) = configured_root {
        if configured_root != root {
            return Err(
                "La bibliothèque demandée ne correspond pas à la bibliothèque PAIDEIA active."
                    .to_string(),
            );
        }
    } else if root != default_root && !is_paideia_migration_destination(&root)? {
        return Err(
            "La bibliothèque personnalisée n'a pas été créée par la migration PAIDEIA.".to_string(),
        );
    }

    persist_and_allow_library_root(&app, &root)?;
    Ok(path_for_frontend(&root))
}

#[tauri::command]
pub fn migrate_library_root(
    app: AppHandle,
    source_root: String,
    destination_root: String,
) -> Result<String, String> {
    let source = canonical_existing_directory(&source_root)?;
    let destination = canonical_existing_directory(&destination_root)?;
    let active_root = match read_active_library_root(&app)? {
        Some(root) => root,
        None => default_user_projects_root()?
            .canonicalize()
            .map_err(|err| format!("Bibliothèque PAIDEIA par défaut inaccessible : {err}"))?,
    };
    if source != active_root {
        return Err("La migration doit partir de la bibliothèque PAIDEIA active.".to_string());
    }
    if !app.asset_protocol_scope().is_allowed(&destination) {
        return Err(
            "La destination doit être choisie avec le sélecteur de dossier PAIDEIA.".to_string(),
        );
    }
    let default_root = default_user_projects_root()?
        .canonicalize()
        .map_err(|err| format!("Bibliothèque PAIDEIA par défaut inaccessible : {err}"))?;
    if destination != default_root && destination.starts_with(&default_root) {
        return Err(
            "Un sous-dossier de la bibliothèque PAIDEIA par défaut ne peut pas devenir sa racine."
                .to_string(),
        );
    }
    if let Ok(resource_root) = app.path().resource_dir() {
        if let Ok(resource_root) = resource_root.canonicalize() {
            if destination.starts_with(resource_root) {
                return Err(
                    "Les ressources internes de PAIDEIA ne peuvent pas recevoir la bibliothèque."
                        .to_string(),
                );
            }
        }
    }

    if source == destination {
        ensure_library_dirs(&destination)?;
        let destination = destination
            .canonicalize()
            .map_err(|err| format!("Bibliothèque PAIDEIA inaccessible : {err}"))?;
        persist_and_allow_library_root(&app, &destination)?;
        return Ok(path_for_frontend(&destination));
    }
    if destination.starts_with(&source) || source.starts_with(&destination) {
        return Err(
            "La migration vers un dossier parent ou enfant du dossier courant est refusÃ©e."
                .to_string(),
        );
    }

    if source.exists() {
        let source_inventory = inventory_tree(&source)?;
        let destination_parent = destination.parent().ok_or_else(|| {
            "Impossible de trouver le dossier parent de la destination.".to_string()
        })?;
        fs::create_dir_all(destination_parent).map_err(|err| err.to_string())?;

        let temp_name = format!(
            "{}.migration-{}",
            destination
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("PAIDEIA"),
            compact_timestamp()
        );
        let temp_destination = destination_parent.join(temp_name);
        if temp_destination.exists() {
            remove_path(&temp_destination)?;
        }

        copy_dir_contents(&source, &temp_destination)?;
        ensure_library_dirs(&temp_destination)?;
        if destination.exists() {
            remove_path(&destination)?;
        }
        fs::rename(&temp_destination, &destination).map_err(|err| err.to_string())?;
        let destination_inventory = inventory_tree(&destination)?;
        write_migration_log(
            &destination,
            &source,
            &destination,
            &source_inventory,
            &destination_inventory,
        )?;
        fs::remove_dir_all(&source).map_err(|err| err.to_string())?;
    } else {
        ensure_library_dirs(&destination)?;
        let destination_inventory = inventory_tree(&destination)?;
        write_migration_log(
            &destination,
            &source,
            &destination,
            &[],
            &destination_inventory,
        )?;
    }

    let destination = destination
        .canonicalize()
        .map_err(|err| format!("Bibliothèque PAIDEIA inaccessible : {err}"))?;
    persist_and_allow_library_root(&app, &destination)?;

    Ok(path_for_frontend(&destination))
}

#[tauri::command(async)]
pub fn list_personal_library_projects(app: AppHandle) -> Result<Vec<LibraryProjectEntry>, String> {
    let library = match read_active_library_root(&app)? {
        Some(root) => root,
        None => default_user_projects_root()?,
    };
    let mut entries = crate::library_discovery::personal_project_dirs(&library)?
        .into_iter()
        .filter_map(|path| build_library_project_entry(&path).ok())
        .collect::<Vec<_>>();
    entries.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    Ok(entries)
}

#[tauri::command(async)]
pub fn list_library_projects(
    search_roots: Vec<String>,
    include_archives: Vec<String>,
) -> Result<Vec<LibraryProjectEntry>, String> {
    let mut project_dirs = HashSet::new();
    for root in &search_roots {
        // Explicit project lookups (collaboration) are not discovery roots.
        let path = PathBuf::from(root);
        if path.join("project.json").is_file() && path.join("content/course.json").is_file() {
            project_dirs.insert(path.canonicalize().map_err(|error| error.to_string())?);
        }
    }

    let mut archives = HashSet::new();
    for archive in include_archives {
        if archive.to_ascii_lowercase().ends_with(".paideia") {
            archives.insert(PathBuf::from(archive));
        }
    }

    let mut entries = project_dirs
        .into_iter()
        .filter_map(|project_path| build_library_project_entry(&project_path).ok())
        .collect::<Vec<_>>();
    entries.extend(
        archives
            .into_iter()
            .filter_map(|archive_path| build_library_archive_entry(&archive_path).ok()),
    );

    entries.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    Ok(entries)
}

#[tauri::command]
pub fn delete_paideia_archive(archive_path: String, library_root: String) -> Result<(), String> {
    let Some(path) = resolve_library_deletion_target(&archive_path, &library_root)? else {
        return Ok(());
    };
    if path.is_dir() {
        fs::remove_dir_all(path).map_err(|err| err.to_string())?;
        return Ok(());
    }

    fs::remove_file(path).map_err(|err| err.to_string())?;
    Ok(())
}

fn resolve_library_deletion_target(
    archive_path: &str,
    library_root: &str,
) -> Result<Option<PathBuf>, String> {
    let requested_path = normalize_absolute_path(&PathBuf::from(archive_path))?;
    if !requested_path.exists() {
        return Ok(None);
    }
    let root = normalize_absolute_path(&PathBuf::from(library_root))?
        .canonicalize()
        .map_err(|err| format!("Bibliothèque PAIDEIA inaccessible : {err}"))?;
    let target = requested_path
        .canonicalize()
        .map_err(|err| format!("Élément de bibliothèque inaccessible : {err}"))?;

    if target.is_dir() {
        let projects_root = root
            .join("projects")
            .canonicalize()
            .map_err(|err| format!("Dossier des projets PAIDEIA inaccessible : {err}"))?;
        if target == projects_root || !target.starts_with(&projects_root) {
            return Err("Suppression refusée hors du dossier des projets PAIDEIA".to_string());
        }
        if !target.join("project.json").is_file() {
            return Err(
                "Seuls les dossiers projets PAIDEIA peuvent être supprimés depuis la bibliothèque"
                    .to_string(),
            );
        }
        return Ok(Some(target));
    }

    let is_paideia = target
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.eq_ignore_ascii_case("paideia"))
        .unwrap_or(false);
    if !is_paideia {
        return Err(
            "Seuls les fichiers .paideia peuvent être supprimés depuis la bibliothèque".to_string(),
        );
    }
    let archives_root = root
        .join("archives")
        .canonicalize()
        .map_err(|err| format!("Dossier des archives PAIDEIA inaccessible : {err}"))?;
    let backups_root = root
        .join("backups")
        .canonicalize()
        .map_err(|err| format!("Dossier des sauvegardes PAIDEIA inaccessible : {err}"))?;
    if !target.starts_with(&archives_root) && !target.starts_with(&backups_root) {
        return Err("Suppression refusée hors des dossiers d’archives PAIDEIA".to_string());
    }
    Ok(Some(target))
}

