fn decode_transcript_text(bytes: &[u8]) -> String {
    if bytes.starts_with(&[0xef, 0xbb, 0xbf]) {
        return String::from_utf8_lossy(&bytes[3..]).into_owned();
    }
    if bytes.starts_with(&[0xff, 0xfe]) {
        let units = bytes[2..]
            .chunks_exact(2)
            .map(|chunk| u16::from_le_bytes([chunk[0], chunk[1]]))
            .collect::<Vec<_>>();
        return String::from_utf16_lossy(&units);
    }
    if bytes.starts_with(&[0xfe, 0xff]) {
        let units = bytes[2..]
            .chunks_exact(2)
            .map(|chunk| u16::from_be_bytes([chunk[0], chunk[1]]))
            .collect::<Vec<_>>();
        return String::from_utf16_lossy(&units);
    }
    match std::str::from_utf8(bytes) {
        Ok(value) => value.to_string(),
        Err(_) => encoding_rs::WINDOWS_1252.decode(bytes).0.into_owned(),
    }
}

fn decode_xml_entities(value: &str) -> String {
    let numeric = Regex::new(r"&#(?:x([0-9a-fA-F]+)|(\d+));").expect("valid XML entity regex");
    let decoded = numeric.replace_all(value, |captures: &regex::Captures<'_>| {
        let code = captures
            .get(1)
            .and_then(|value| u32::from_str_radix(value.as_str(), 16).ok())
            .or_else(|| {
                captures
                    .get(2)
                    .and_then(|value| value.as_str().parse::<u32>().ok())
            });
        code.and_then(char::from_u32)
            .unwrap_or('\u{fffd}')
            .to_string()
    });
    decoded
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&amp;", "&")
}

fn normalize_transcript_plain_text(value: &str) -> String {
    let normalized = value.replace("\r\n", "\n").replace('\r', "\n");
    let excess_breaks = Regex::new(r"\n[\t ]*\n(?:[\t ]*\n)+").expect("valid line-break regex");
    excess_breaks
        .replace_all(normalized.trim(), "\n\n")
        .into_owned()
}

fn transcript_plain_text_from_xml(xml: &str, document_type: &str) -> String {
    let mut expanded = xml.to_string();
    if document_type == "docx" {
        let tab = Regex::new(r"(?i)<w:tab\b[^>]*/>").expect("valid DOCX tab regex");
        let line_break = Regex::new(r"(?i)<w:(?:br|cr)\b[^>]*/>").expect("valid DOCX break regex");
        let paragraph = Regex::new(r"(?i)</w:p\s*>").expect("valid DOCX paragraph regex");
        expanded = tab.replace_all(&expanded, "\t").into_owned();
        expanded = line_break.replace_all(&expanded, "\n").into_owned();
        expanded = paragraph.replace_all(&expanded, "\n\n").into_owned();
    } else {
        let tab = Regex::new(r"(?i)<text:tab\b[^>]*/>").expect("valid ODT tab regex");
        let spaces = Regex::new(r#"(?i)<text:s(?:\s+text:c="(\d+)")?\s*/>"#)
            .expect("valid ODT spaces regex");
        let line_break =
            Regex::new(r"(?i)<text:line-break\b[^>]*/>").expect("valid ODT break regex");
        let paragraph = Regex::new(r"(?i)</text:(?:p|h)\s*>").expect("valid ODT paragraph regex");
        expanded = tab.replace_all(&expanded, "\t").into_owned();
        expanded = spaces
            .replace_all(&expanded, |captures: &regex::Captures<'_>| {
                " ".repeat(
                    captures
                        .get(1)
                        .and_then(|value| value.as_str().parse::<usize>().ok())
                        .unwrap_or(1)
                        .min(100),
                )
            })
            .into_owned();
        expanded = line_break.replace_all(&expanded, "\n").into_owned();
        expanded = paragraph.replace_all(&expanded, "\n\n").into_owned();
    }
    let tags = Regex::new(r"(?s)<[^>]*>").expect("valid XML tag regex");
    normalize_transcript_plain_text(&decode_xml_entities(&tags.replace_all(&expanded, "")))
}

fn transcript_plain_text_from_rtf(rtf: &str) -> String {
    let destinations = [
        "fonttbl",
        "colortbl",
        "stylesheet",
        "info",
        "pict",
        "object",
        "header",
        "footer",
    ];
    let bytes = rtf.as_bytes();
    let mut output = String::new();
    let mut skipped = vec![false];
    let mut index = 0usize;
    while index < bytes.len() {
        match bytes[index] {
            b'{' => {
                let mut cursor = index + 1;
                let mut starred_destination = false;
                if cursor < bytes.len() && bytes[cursor] == b'\\' {
                    cursor += 1;
                    if cursor < bytes.len() && bytes[cursor] == b'*' {
                        starred_destination = true;
                        cursor += 1;
                        if cursor < bytes.len() && bytes[cursor] == b'\\' {
                            cursor += 1;
                        }
                    }
                }
                let start = cursor;
                while cursor < bytes.len() && bytes[cursor].is_ascii_alphabetic() {
                    cursor += 1;
                }
                let destination = std::str::from_utf8(&bytes[start..cursor]).unwrap_or_default();
                skipped.push(
                    *skipped.last().unwrap_or(&false)
                        || starred_destination
                        || destinations.contains(&destination),
                );
                index += 1;
            }
            b'}' => {
                if skipped.len() > 1 {
                    skipped.pop();
                }
                index += 1;
            }
            b'\\' if !*skipped.last().unwrap_or(&false) => {
                if index + 1 >= bytes.len() {
                    break;
                }
                let next = bytes[index + 1];
                if matches!(next, b'\\' | b'{' | b'}') {
                    output.push(next as char);
                    index += 2;
                    continue;
                }
                if next == b'\'' && index + 3 < bytes.len() {
                    if let Ok(value) = u8::from_str_radix(&rtf[index + 2..index + 4], 16) {
                        output.push_str(&encoding_rs::WINDOWS_1252.decode(&[value]).0);
                    }
                    index += 4;
                    continue;
                }
                let mut cursor = index + 1;
                while cursor < bytes.len() && bytes[cursor].is_ascii_alphabetic() {
                    cursor += 1;
                }
                let word = &rtf[index + 1..cursor];
                let mut sign = 1i32;
                if cursor < bytes.len() && bytes[cursor] == b'-' {
                    sign = -1;
                    cursor += 1;
                }
                let number_start = cursor;
                while cursor < bytes.len() && bytes[cursor].is_ascii_digit() {
                    cursor += 1;
                }
                let number = rtf[number_start..cursor]
                    .parse::<i32>()
                    .ok()
                    .map(|value| value * sign);
                if cursor < bytes.len() && bytes[cursor] == b' ' {
                    cursor += 1;
                }
                match word {
                    "par" | "line" => output.push_str("\n\n"),
                    "tab" => output.push('\t'),
                    "u" => {
                        if let Some(value) = number
                            .and_then(|value| char::from_u32((value.rem_euclid(65536)) as u32))
                        {
                            output.push(value);
                        }
                        if cursor < bytes.len() && bytes[cursor] == b'?' {
                            cursor += 1;
                        }
                    }
                    _ => {}
                }
                index = cursor;
            }
            _ if !*skipped.last().unwrap_or(&false) => {
                let remaining = &rtf[index..];
                let character = remaining.chars().next().unwrap_or_default();
                output.push(character);
                index += character.len_utf8();
            }
            _ => index += 1,
        }
    }
    normalize_transcript_plain_text(&output)
}

#[tauri::command]
pub fn read_transcript_document(path: String) -> Result<String, String> {
    let source = PathBuf::from(path);
    let extension = source
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.to_ascii_lowercase())
        .ok_or_else(|| "Le fichier de transcription n'a pas d'extension reconnue".to_string())?;
    if !matches!(extension.as_str(), "txt" | "md" | "rtf" | "docx" | "odt") {
        return Err("Formats acceptés : TXT, Markdown, RTF, DOCX et ODT".to_string());
    }
    let metadata = fs::metadata(&source).map_err(|err| err.to_string())?;
    if !metadata.is_file() || metadata.len() > MAX_TRANSCRIPT_DOCUMENT_BYTES {
        return Err("Le document de transcription est invalide ou dépasse 25 Mo".to_string());
    }
    let plain_text = match extension.as_str() {
        "txt" | "md" => normalize_transcript_plain_text(&decode_transcript_text(
            &fs::read(&source).map_err(|err| err.to_string())?,
        )),
        "rtf" => transcript_plain_text_from_rtf(&decode_transcript_text(
            &fs::read(&source).map_err(|err| err.to_string())?,
        )),
        "docx" | "odt" => {
            let file = fs::File::open(&source).map_err(|err| err.to_string())?;
            let mut archive = ZipArchive::new(file).map_err(|_| {
                format!(
                    "Le fichier {} est illisible",
                    extension.to_ascii_uppercase()
                )
            })?;
            let xml_path = if extension == "docx" {
                "word/document.xml"
            } else {
                "content.xml"
            };
            let mut xml_file = archive.by_name(xml_path).map_err(|_| {
                format!(
                    "Le contenu du fichier {} est introuvable",
                    extension.to_ascii_uppercase()
                )
            })?;
            if xml_file.size() > MAX_TRANSCRIPT_XML_BYTES {
                return Err("Le contenu du document dépasse 50 Mo".to_string());
            }
            let mut xml = String::new();
            xml_file
                .read_to_string(&mut xml)
                .map_err(|err| err.to_string())?;
            transcript_plain_text_from_xml(&xml, &extension)
        }
        _ => unreachable!(),
    };
    if plain_text.trim().is_empty() {
        return Err("Aucun texte exploitable n'a été trouvé dans ce document".to_string());
    }
    Ok(plain_text)
}

#[tauri::command]
pub fn write_transcript_rtf(target_path: String, content: String) -> Result<String, String> {
    let target = PathBuf::from(target_path);
    if !target
        .extension()
        .and_then(|value| value.to_str())
        .map(|value| value.eq_ignore_ascii_case("rtf"))
        .unwrap_or(false)
    {
        return Err("Le fichier de transcription doit se terminer par .rtf".to_string());
    }
    if !content.trim_start().starts_with("{\\rtf")
        || content.len() as u64 > MAX_TRANSCRIPT_DOCUMENT_BYTES
    {
        return Err("Le contenu RTF de la transcription est invalide".to_string());
    }
    let parent = target
        .parent()
        .ok_or_else(|| "Dossier d'enregistrement invalide".to_string())?;
    fs::create_dir_all(parent).map_err(|err| err.to_string())?;
    let file_name = target
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("transcription.rtf");
    let temporary = unique_sibling_path(parent, file_name, "tmp");
    let backup = unique_sibling_path(parent, file_name, "bak");
    let result = (|| -> Result<(), String> {
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|err| err.to_string())?;
        file.write_all(content.as_bytes())
            .map_err(|err| err.to_string())?;
        file.sync_all().map_err(|err| err.to_string())?;
        if target.exists() {
            fs::rename(&target, &backup).map_err(|err| err.to_string())?;
        }
        if let Err(error) = fs::rename(&temporary, &target) {
            if backup.exists() {
                let _ = fs::rename(&backup, &target);
            }
            return Err(error.to_string());
        }
        if backup.exists() {
            let _ = fs::remove_file(&backup);
        }
        Ok(())
    })();
    if temporary.exists() {
        let _ = fs::remove_file(&temporary);
    }
    if result.is_err() && backup.exists() && !target.exists() {
        let _ = fs::rename(&backup, &target);
    }
    result?;
    Ok(target.to_string_lossy().to_string())
}

pub(crate) fn transcription_media_asset_source(
    project_path: &str,
    asset_ref: &str,
) -> Result<(String, PathBuf), String> {
    let normalized_ref = normalize_scorm_asset_ref(asset_ref);
    let extension = Path::new(&normalized_ref)
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if normalized_ref.trim().is_empty()
        || !matches!(
            extension.as_str(),
            "mp3"
                | "wav"
                | "m4a"
                | "aac"
                | "flac"
                | "ogg"
                | "oga"
                | "opus"
                | "mp4"
                | "webm"
                | "mov"
                | "m4v"
        )
    {
        return Err("Le fichier sélectionné n'est pas un média audio pris en charge".to_string());
    }
    let project_root = resolve_project_path(project_path);
    let assets_root =
        fs::canonicalize(project_root.join("assets")).map_err(|err| err.to_string())?;
    let candidate = fs::canonicalize(assets_root.join(&normalized_ref))
        .map_err(|_| "Le fichier audio est introuvable".to_string())?;
    if !candidate.starts_with(&assets_root) || !candidate.is_file() {
        return Err("Référence audio invalide".to_string());
    }
    Ok((normalized_ref, candidate))
}

#[derive(Debug, Clone, Serialize)]
pub struct DetachedVideoOptimizationResult {
    #[serde(rename = "assetRef")]
    pub asset_ref: String,
    #[serde(rename = "originalAssetRef")]
    pub original_asset_ref: String,
    #[serde(rename = "profile")]
    pub profile: String,
}

#[tauri::command]
pub fn confirm_detached_video_optimization(
    task_id: String,
) -> Result<DetachedVideoOptimizationResult, String> {
    let task = {
        let tasks = video_optimization_tasks()
            .lock()
            .map_err(|_| "Gestionnaire d'optimisation indisponible".to_string())?;
        tasks
            .get(&task_id)
            .filter(|task| task.state == "awaiting-confirmation" && task.detached_asset)
            .cloned()
            .ok_or_else(|| "Aucun resultat de media n'attend de confirmation".to_string())?
    };
    if !task.output_path.is_file()
        || task
            .result_analysis
            .as_ref()
            .is_none_or(|result| result.size_bytes == 0)
    {
        return Err("Le resultat optimise n'est plus disponible".to_string());
    }
    let project_root = resolve_project_path(&task.project_path);
    let optimized_directory = project_root.join("assets").join("video").join("poi");
    fs::create_dir_all(&optimized_directory).map_err(|err| err.to_string())?;
    let optimized_ref = format!(
        "video/poi/{}-OPT-{}.mp4",
        sanitize_filename(&task.block_id),
        Utc::now().timestamp_millis()
    );
    let optimized_path = project_root.join("assets").join(&optimized_ref);
    fs::rename(&task.output_path, &optimized_path)
        .or_else(|_| {
            fs::copy(&task.output_path, &optimized_path)?;
            fs::remove_file(&task.output_path)
        })
        .map_err(|err| format!("Installation de la video optimisee impossible : {err}"))?;
    video_optimization_tasks()
        .lock()
        .map_err(|_| "Gestionnaire d'optimisation indisponible".to_string())?
        .remove(&task_id);
    Ok(DetachedVideoOptimizationResult {
        asset_ref: optimized_ref,
        original_asset_ref: task.source_ref,
        profile: task.profile,
    })
}

#[tauri::command]
pub fn read_import_report(project_path: String) -> Result<ImportReport, String> {
    let project_root = resolve_project_path(&project_path);
    let report_path = project_root.join("imports").join("rematching-report.json");
    let payload = fs::read_to_string(&report_path).map_err(|err| {
        format!(
            "Impossible de lire le rapport d'importation {} : {}",
            report_path.display(),
            err
        )
    })?;
    serde_json::from_str(&payload).map_err(|err| {
        format!(
            "Rapport d'importation invalide {} : {}",
            report_path.display(),
            err
        )
    })
}

#[tauri::command]
pub fn write_import_log(project_path: String, content: String) -> Result<String, String> {
    const MAX_IMPORT_LOG_BYTES: usize = 5 * 1024 * 1024;
    if content.len() > MAX_IMPORT_LOG_BYTES {
        return Err("Le journal d'importation est trop volumineux.".to_string());
    }
    let project_root = resolve_project_path(&project_path);
    if !project_root.is_dir() {
        return Err("Le dossier du projet importé est introuvable.".to_string());
    }
    let log_path = project_root.join("log-import.md");
    fs::write(&log_path, content).map_err(|err| {
        format!(
            "Impossible d'écrire le journal d'importation {} : {}",
            log_path.display(),
            err
        )
    })?;
    Ok(log_path.to_string_lossy().to_string())
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LessonDurationCurrentEstimate {
    pub schema_version: u8,
    pub signature: String,
    pub seconds: u64,
    pub report_content: String,
    pub report_path: String,
    pub calculated_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct LessonDurationCurrentMetadata {
    schema_version: u8,
    signature: String,
    seconds: u64,
    calculated_at: String,
}

#[tauri::command]
pub fn write_lesson_duration_log(
    project_path: String,
    lesson_title: String,
    content: String,
    replace_current: Option<bool>,
    signature: Option<String>,
    seconds: Option<u64>,
) -> Result<String, String> {
    const MAX_DURATION_LOG_BYTES: usize = 2 * 1024 * 1024;
    if content.len() > MAX_DURATION_LOG_BYTES {
        return Err("Le diagnostic de durée est trop volumineux.".to_string());
    }

    let project_root = resolve_project_path(&project_path);
    if !project_root.is_dir() {
        return Err("Le dossier du projet est introuvable.".to_string());
    }
    let metrics_root = project_root.join("metrics");
    fs::create_dir_all(&metrics_root).map_err(|err| {
        format!(
            "Impossible de créer le dossier des métriques {} : {}",
            metrics_root.display(),
            err
        )
    })?;

    let log_path = if replace_current.unwrap_or(false) {
        metrics_root.join("lesson-duration-current.txt")
    } else {
        let lesson_slug = sanitize_filename(
            &lesson_title
                .to_lowercase()
                .replace(char::is_whitespace, "-"),
        );
        let safe_lesson_slug = if lesson_slug.is_empty() {
            "lecon"
        } else {
            lesson_slug.as_str()
        };
        metrics_root.join(format!(
            "lesson-duration-{}-{}.txt",
            safe_lesson_slug,
            compact_timestamp()
        ))
    };
    fs::write(&log_path, content).map_err(|err| {
        format!(
            "Impossible d'écrire le diagnostic de durée {} : {}",
            log_path.display(),
            err
        )
    })?;

    if replace_current.unwrap_or(false) {
        if let (Some(signature), Some(seconds)) = (signature, seconds) {
            if signature.len() > 256 {
                return Err("L'empreinte du diagnostic de durée est invalide.".to_string());
            }
            let metadata = LessonDurationCurrentMetadata {
                schema_version: 1,
                signature,
                seconds,
                calculated_at: Utc::now().to_rfc3339(),
            };
            let metadata_content = serde_json::to_vec_pretty(&metadata).map_err(|err| {
                format!("Impossible de préparer les métadonnées de durée : {}", err)
            })?;
            let metadata_path = metrics_root.join("lesson-duration-current.json");
            fs::write(&metadata_path, metadata_content).map_err(|err| {
                format!(
                    "Impossible d'écrire les métadonnées de durée {} : {}",
                    metadata_path.display(),
                    err
                )
            })?;
        }
    }
    Ok(log_path.to_string_lossy().to_string())
}

#[tauri::command]
pub fn read_lesson_duration_current(
    project_path: String,
) -> Result<Option<LessonDurationCurrentEstimate>, String> {
    const MAX_DURATION_LOG_BYTES: u64 = 2 * 1024 * 1024;
    const MAX_DURATION_METADATA_BYTES: u64 = 16 * 1024;
    let project_root = resolve_project_path(&project_path);
    if !project_root.is_dir() {
        return Ok(None);
    }
    let metrics_root = project_root.join("metrics");
    let report_path = metrics_root.join("lesson-duration-current.txt");
    let metadata_path = metrics_root.join("lesson-duration-current.json");
    if !report_path.is_file() || !metadata_path.is_file() {
        return Ok(None);
    }
    let report_size = fs::metadata(&report_path)
        .map_err(|err| err.to_string())?
        .len();
    let metadata_size = fs::metadata(&metadata_path)
        .map_err(|err| err.to_string())?
        .len();
    if report_size > MAX_DURATION_LOG_BYTES || metadata_size > MAX_DURATION_METADATA_BYTES {
        return Err("Le diagnostic de durée enregistré est trop volumineux.".to_string());
    }
    let metadata: LessonDurationCurrentMetadata =
        serde_json::from_slice(&fs::read(&metadata_path).map_err(|err| err.to_string())?)
            .map_err(|err| format!("Les métadonnées de durée sont illisibles : {}", err))?;
    let report_content = fs::read_to_string(&report_path)
        .map_err(|err| format!("Le rapport de durée est illisible : {}", err))?;
    Ok(Some(LessonDurationCurrentEstimate {
        schema_version: metadata.schema_version,
        signature: metadata.signature,
        seconds: metadata.seconds,
        report_content,
        report_path: report_path.to_string_lossy().to_string(),
        calculated_at: metadata.calculated_at,
    }))
}

fn ensure_editable_collaboration_export(project_path: &str) -> Result<(), String> {
    if resolve_project_path(project_path)
        .join(".paideia-collaboration-readonly")
        .is_file()
    {
        return Err("Cette leçon collaborative est en lecture seule et ne peut pas être exportée sous une forme rééditable.".to_string());
    }
    Ok(())
}

#[tauri::command]
pub async fn export_paideia_archive(
    project_path: String,
    destination_root: String,
) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        ensure_editable_collaboration_export(&project_path)?;
        let project = load_project_from_path(&project_path)?;
        let root = resolve_project_path(&project_path);
        let destination_dir = PathBuf::from(destination_root).join("archives");
        fs::create_dir_all(&destination_dir).map_err(|err| err.to_string())?;
        let archive_slug = slug_from_title(&project.title.replace('\u{2500}', " "));
        let archive_path =
            destination_dir.join(format!("{}-{}.paideia", archive_slug, compact_timestamp()));
        zip_directory_to_file(&root, &archive_path)?;
        Ok(archive_path.to_string_lossy().to_string())
    })
    .await
    .map_err(|err| format!("Échec de la tâche d’archivage PAIDEIA : {err}"))?
}

#[tauri::command]
pub async fn export_paideia_archive_to(
    project_path: String,
    archive_path: String,
    include_resources: Option<bool>,
) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        ensure_editable_collaboration_export(&project_path)?;
        let root = resolve_project_path(&project_path);
        let output = PathBuf::from(archive_path);
        if let Some(parent) = output.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        let resources = if include_resources.unwrap_or(false) {
            collect_shared_resource_banks(&project_path)?
        } else {
            None
        };
        zip_directory_to_file_with_resources(&root, &output, resources.as_deref())?;
        Ok(output.to_string_lossy().to_string())
    })
    .await
    .map_err(|err| format!("Échec de la tâche d’archivage PAIDEIA : {err}"))?
}

const SHARED_RESOURCE_BANKS_FILE: &str = "paideia-shared-banks.json";
const SHARED_RESOURCE_BANKS_MAX_BYTES: u64 = 128 * 1024 * 1024;

#[derive(serde::Serialize, serde::Deserialize)]
struct SharedResourceBank {
    family: String,
    bank: serde_json::Value,
    image: Option<(String, String)>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    base_fingerprint: Option<String>,
}

fn shared_bank_image_field(family: crate::resource_bank_store::Family) -> &'static str {
    if matches!(family, crate::resource_bank_store::Family::Assistants) {
        "avatarRef"
    } else {
        "tileImageRef"
    }
}

fn detach_shared_bank(bank: &mut serde_json::Value, family: crate::resource_bank_store::Family) {
    if let Some(object) = bank.as_object_mut() {
        for field in [
            "projectPaths",
            "lessonIds",
            "collectionIds",
            "resourceModifiedAt",
            "contentLoaded",
            shared_bank_image_field(family),
        ] {
            object.remove(field);
        }
    }
}

fn prepare_shared_bank(
    root: &Path,
    key: &str,
    family: crate::resource_bank_store::Family,
    mut bank: serde_json::Value,
) -> Result<SharedResourceBank, String> {
    let image = bank[shared_bank_image_field(family)]
        .as_str()
        .filter(|r| !r.is_empty())
        .map(|reference| {
            let path = root
                .join(reference)
                .canonicalize()
                .map_err(|e| e.to_string())?;
            if !path.starts_with(root.canonicalize().map_err(|e| e.to_string())?) {
                return Err("Image de banque hors du dossier de ressources".to_string());
            }
            let name = path
                .file_name()
                .and_then(|name| name.to_str())
                .ok_or("Image de banque invalide")?;
            let bytes = fs::read(&path).map_err(|e| e.to_string())?;
            validate_user_image_file(name, &bytes)?;
            Ok((name.to_string(), STANDARD.encode(bytes)))
        })
        .transpose()?;
    detach_shared_bank(&mut bank, family);
    Ok(SharedResourceBank {
        family: key.to_string(),
        bank,
        image,
        base_fingerprint: None,
    })
}

fn shared_bank_fingerprint(bank: &serde_json::Value, image: Option<&[u8]>) -> String {
    let mut comparable = bank.clone();
    if let Some(fields) = comparable.as_object_mut() {
        fields.remove("revision");
    }
    let mut hash = Sha256::new();
    hash.update(comparable.to_string().as_bytes());
    if let Some(bytes) = image {
        hash.update(bytes);
    }
    format!("{:x}", hash.finalize())
}

fn prepared_bank_fingerprint(resource: &SharedResourceBank) -> Result<String, String> {
    let image = resource.image.as_ref().map(|(_, data)| STANDARD.decode(data))
        .transpose().map_err(|error| error.to_string())?;
    Ok(shared_bank_fingerprint(&resource.bank, image.as_deref()))
}

fn add_shared_bank_base(resource: &mut SharedResourceBank) -> Result<(), String> {
    use crate::resource_bank_store::{self as store, Family};
    let family = Family::parse(&resource.family)?;
    let Some(id) = resource.bank["id"].as_str() else { return Ok(()) };
    let root = individual_bank_root(family)?;
    // The embedded lesson snapshot may lag behind the local catalogue.
    // Only use its history when the archived content matches the current bank.
    let (Ok(current), Ok(previous)) = (store::load(&root, family, id), store::previous(&root, id))
        else { return Ok(()) };
    let (Ok(current), Ok(previous)) = (
        prepare_shared_bank(&root, &resource.family, family, current),
        prepare_shared_bank(&root, &resource.family, family, previous),
    ) else { return Ok(()) };
    let fingerprint = prepared_bank_fingerprint(resource)?;
    let base = prepared_bank_fingerprint(&previous)?;
    if fingerprint == prepared_bank_fingerprint(&current)? && fingerprint != base {
        resource.base_fingerprint = Some(base);
    }
    Ok(())
}

fn collect_shared_resource_banks(project_path: &str) -> Result<Option<Vec<u8>>, String> {
    use crate::resource_bank_store::{self as store, Family};
    let project = load_project_from_path(project_path)?;
    let mut question_ids = std::collections::HashSet::new();
    fn find_sources(value: &serde_json::Value, ids: &mut std::collections::HashSet<String>) {
        match value {
            serde_json::Value::Object(fields) => {
                if let Some(id) = fields
                    .get("sourceBankId")
                    .and_then(serde_json::Value::as_str)
                {
                    ids.insert(id.to_owned());
                }
                for child in fields.values() {
                    find_sources(child, ids);
                }
            }
            serde_json::Value::Array(children) => {
                for child in children {
                    find_sources(child, ids);
                }
            }
            _ => {}
        }
    }
    find_sources(
        &serde_json::to_value(&project.course).map_err(|e| e.to_string())?,
        &mut question_ids,
    );
    question_ids.extend(project.question_banks.iter().map(|bank| bank.id.clone()));
    let mut resources = Vec::new();
    // On re-export, keep the archived source of linked questions rather than
    // picking a different bank that happens to have the same ID locally.
    let previously_shared = shared_resource_banks_path(project_path);
    if previously_shared.is_file() && !question_ids.is_empty() {
        for resource in read_shared_resource_banks(&previously_shared)? {
            if resource.family == "questions"
                && resource.bank["id"].as_str().is_some_and(|id| question_ids.remove(id))
            {
                resources.push(resource);
            }
        }
    }
    let _lock = store::LOCK.lock().map_err(|e| e.to_string())?;
    let question_root = individual_bank_root(Family::Questions)?;
    let catalog = store::catalog(&question_root, Family::Questions)?;
    for descriptor in catalog["banks"].as_array().ok_or("Annuaire invalide")? {
        let id = descriptor["id"].as_str().ok_or("Identifiant absent")?;
        if question_ids.remove(id) {
            resources.push(prepare_shared_bank(
                &question_root,
                "questions",
                Family::Questions,
                store::load(&question_root, Family::Questions, id)?,
            )?);
        }
    }

    // Reference and glossary banks already have a complete snapshot in the lesson.
    // Use it so a same-ID bank in the current library cannot replace the shared content.
    let assets = resolve_project_path(project_path).join("assets");
    for bank in project.reference_banks {
        let snapshot = ReferenceBankResource {
            id: bank.source_resource_id.unwrap_or(bank.id),
            name: bank.name,
            tile_image_ref: bank.tile_image_ref,
            revision: bank.source_revision.unwrap_or(1),
            entries: bank.entries,
            project_paths: Vec::new(),
            collection_ids: Vec::new(),
        };
        resources.push(prepare_shared_bank(
            &assets,
            "references",
            Family::References,
            serde_json::to_value(snapshot).map_err(|e| e.to_string())?,
        )?);
    }
    for bank in project.glossary_assistants {
        resources.push(prepare_shared_bank(
            &assets,
            "assistants",
            Family::Assistants,
            serde_json::to_value(bank).map_err(|e| e.to_string())?,
        )?);
    }
    for bank in project.question_banks {
        if question_ids.remove(&bank.id) {
            resources.push(prepare_shared_bank(
                &assets,
                "questions",
                Family::Questions,
                serde_json::to_value(bank).map_err(|e| e.to_string())?,
            )?);
        }
    }
    if resources.is_empty() {
        return Ok(None);
    }
    for resource in &mut resources {
        if resource.base_fingerprint.is_none() {
            add_shared_bank_base(resource)?;
        }
    }
    let bytes = serde_json::to_vec(&resources).map_err(|e| e.to_string())?;
    if bytes.len() as u64 > SHARED_RESOURCE_BANKS_MAX_BYTES {
        return Err("Les banques associées dépassent la taille maximale de 128 Mio".into());
    }
    Ok(Some(bytes))
}

fn shared_resource_banks_path(project_path: &str) -> PathBuf {
    resolve_project_path(project_path).join(SHARED_RESOURCE_BANKS_FILE)
}

fn read_shared_resource_banks(path: &Path) -> Result<Vec<SharedResourceBank>, String> {
    let file = fs::File::open(path).map_err(|e| e.to_string())?;
    let mut bytes = Vec::new();
    file.take(SHARED_RESOURCE_BANKS_MAX_BYTES + 1)
        .read_to_end(&mut bytes)
        .map_err(|e| e.to_string())?;
    if bytes.len() as u64 > SHARED_RESOURCE_BANKS_MAX_BYTES {
        return Err("Les banques associées dépassent la taille maximale de 128 Mio".into());
    }
    serde_json::from_slice(&bytes).map_err(|e| e.to_string())
}

#[tauri::command]
pub fn has_paideia_shared_banks(project_path: String) -> bool {
    shared_resource_banks_path(&project_path).is_file()
}

#[tauri::command]
pub async fn inspect_paideia_shared_bank_updates(project_path: String) -> Result<Vec<serde_json::Value>, String> {
    tauri::async_runtime::spawn_blocking(move || {
        use crate::resource_bank_store::{self as store, Family};
        let _lock = store::LOCK.lock().map_err(|e| e.to_string())?;
        let mut updates = Vec::new();
        for resource in read_shared_resource_banks(&shared_resource_banks_path(&project_path))? {
            let Some(base) = resource.base_fingerprint.as_deref() else { continue };
            let family = Family::parse(&resource.family)?;
            let id = resource.bank["id"].as_str().ok_or("Identifiant absent")?;
            let root = individual_bank_root(family)?;
            let Ok(local) = store::load(&root, family, id) else { continue };
            let prepared = prepare_shared_bank(&root, &resource.family, family, local.clone())?;
            if prepared_bank_fingerprint(&prepared)? != base {
                continue;
            }
            let incoming = prepared_bank_fingerprint(&resource)?;
            if incoming == base {
                continue;
            }
            let field = if matches!(family, Family::Questions) { "questions" } else { "entries" };
            let items = |bank: &serde_json::Value| -> HashMap<String, serde_json::Value> {
                bank[field].as_array().into_iter().flatten()
                    .filter_map(|item| Some((item["id"].as_str()?.to_owned(), item.clone())))
                    .collect()
            };
            let before = items(&local);
            let after = items(&resource.bank);
            updates.push(serde_json::json!({
                "key": format!("{}:{id}", resource.family),
                "fingerprint": format!("{base}:{incoming}"),
                "name": resource.bank["name"],
                "added": after.keys().filter(|key| !before.contains_key(*key)).count(),
                "removed": before.keys().filter(|key| !after.contains_key(*key)).count(),
                "changed": before.iter().filter(|(key, item)| after.get(*key).is_some_and(|next| next != *item)).count(),
                "imageChanged": prepared.image.as_ref().map(|(_, data)| data) != resource.image.as_ref().map(|(_, data)| data),
                "linkedLessons": local["projectPaths"].as_array().map_or(0, Vec::len),
            }));
        }
        Ok(updates)
    }).await.map_err(|e| e.to_string())?
}

#[tauri::command]
pub async fn import_paideia_shared_banks(project_path: String, updates: Option<HashMap<String, String>>) -> Result<(), String> {
    tauri::async_runtime::spawn_blocking(move || {
        use crate::resource_bank_store::{self as store, Family};
        let resources = read_shared_resource_banks(&shared_resource_banks_path(&project_path))?;
        let updates = updates.unwrap_or_default();
        let mut validated = Vec::new();
        let mut source_ids = HashSet::new();
        for resource in resources {
            let key = format!("{}:{}", resource.family, resource.bank["id"].as_str().ok_or("Identifiant absent")?);
            let fingerprint = updates.contains_key(&key)
                .then(|| prepared_bank_fingerprint(&resource))
                .transpose()?;
            let SharedResourceBank {
                family,
                mut bank,
                image,
                base_fingerprint,
            } = resource;
            let family_key = family;
            let family = Family::parse(&family_key)?;
            let id = bank["id"].as_str().ok_or("Identifiant absent")?;
            if !source_ids.insert((family_key.clone(), id.to_owned())) {
                return Err("Banque en double dans l’archive.".into());
            }
            detach_shared_bank(&mut bank, family);
            crate::rich_text_sanitizer::sanitize_rich_text_value(&mut bank);
            let mut bank = match family {
                Family::Questions => {
                    let mut typed: QuestionBankResource =
                        serde_json::from_value(bank).map_err(|e| e.to_string())?;
                    normalize_question_bank_points(std::slice::from_mut(&mut typed));
                    serde_json::to_value(typed)
                }
                Family::References => serde_json::to_value(
                    serde_json::from_value::<ReferenceBankResource>(bank)
                        .map_err(|e| e.to_string())?,
                ),
                Family::Assistants => serde_json::to_value(
                    serde_json::from_value::<GlossaryAssistantResource>(bank)
                        .map_err(|e| e.to_string())?,
                ),
            }
            .map_err(|e| e.to_string())?;
            detach_shared_bank(&mut bank, family);
            let image = image
                .map(|(name, data)| {
                    let bytes = STANDARD.decode(data).map_err(|e| e.to_string())?;
                    validate_user_image_file(&name, &bytes)?;
                    let extension = supported_character_image_extension(&name)
                        .ok_or("Format d’image non supporté")?;
                    Ok::<_, String>((versioned_user_image_name("tile", &extension, &bytes), bytes))
                })
                .transpose()?;
            validated.push((family_key, family, bank, image, base_fingerprint, fingerprint));
        }

        let _lock = store::LOCK.lock().map_err(|e| e.to_string())?;
        let mut confirmed = HashSet::new();
        for (key, family, bank, _, base, incoming) in &validated {
            let id = bank["id"].as_str().ok_or("Identifiant absent")?;
            let selection = format!("{key}:{id}");
            if let Some(expected) = updates.get(&selection) {
                let root = individual_bank_root(*family)?;
                let local = store::load(&root, *family, id)?;
                let local = prepared_bank_fingerprint(&prepare_shared_bank(&root, key, *family, local)?)?;
                let incoming = incoming.as_deref().ok_or("Empreinte de la banque reçue absente")?;
                if base.as_ref() != Some(&local)
                    || format!("{local}:{incoming}") != *expected
                    || !confirmed.insert(selection)
                {
                    return Err("La banque locale a changé depuis la confirmation.".into());
                }
            }
        }
        if confirmed.len() != updates.len() {
            return Err("Choix de mise à jour incohérent.".into());
        }
        let mut project = load_project_from_path(&project_path)?;
        let mut ids = HashMap::new();
        for (key, family, bank, image, _, _) in validated {
            let id = bank["id"].as_str().ok_or("Identifiant absent")?.to_owned();
            let root = individual_bank_root(family)?;
            let update = confirmed.contains(&format!("{key}:{id}"));
            let retained = persist_shared_bank(&root, family, bank, image, update, Some(&project_path))?;
            ids.insert((key, id), retained);
        }
        rebind_shared_banks(&mut project, &ids)?;
        save_project_to_path(&project_path, &project)?;
        Ok(())
    })
    .await
    .map_err(|e| e.to_string())?
}

fn rebind_shared_banks(
    project: &mut PaideiaProject,
    ids: &HashMap<(String, String), String>,
) -> Result<(), String> {
    let mut references = HashMap::new();
    for bank in &mut project.reference_banks {
        let source = bank.source_resource_id.as_ref().unwrap_or(&bank.id);
        if let Some(retained) = ids.get(&("references".into(), source.clone())) {
            references.insert(bank.id.clone(), retained.clone());
            bank.id = retained.clone();
            bank.source_resource_id = Some(retained.clone());
        }
    }
    for bank in &mut project.glossary_assistants {
        if let Some(retained) = ids.get(&("assistants".into(), bank.id.clone())) {
            bank.id = retained.clone();
        }
    }
    let questions: HashMap<&str, &str> = ids.iter()
        .filter(|((family, _), _)| family == "questions")
        .map(|((_, old), new)| (old.as_str(), new.as_str())).collect();
    for bank in &mut project.question_banks {
        if let Some(retained) = questions.get(bank.id.as_str()) {
            bank.id = (*retained).to_owned();
        }
    }
    let attribute = regex::Regex::new(r#"(?i)(\sdata-paideia-reference-bank-id\s*=\s*)(?:"([^"]*)"|'([^']*)')"#)
        .map_err(|error| error.to_string())?;
    fn visit(
        value: &mut serde_json::Value,
        questions: &HashMap<&str, &str>,
        references: &HashMap<String, String>,
        attribute: &regex::Regex,
    ) {
        match value {
            serde_json::Value::Object(fields) => {
                if let Some(source) = fields.get_mut("sourceBankId") {
                    if let Some(retained) = source.as_str().and_then(|id| questions.get(id)) {
                        *source = serde_json::json!(retained);
                    }
                }
                for child in fields.values_mut() {
                    visit(child, questions, references, attribute);
                }
            }
            serde_json::Value::Array(items) => {
                for child in items {
                    visit(child, questions, references, attribute);
                }
            }
            serde_json::Value::String(html)
                if !references.is_empty() && html.contains("data-paideia-reference-bank-id") => {
                if let std::borrow::Cow::Owned(updated) = attribute.replace_all(html, |capture: &regex::Captures| {
                    let old = capture.get(2).or_else(|| capture.get(3)).unwrap().as_str();
                    references.get(old).filter(|new| new.as_str() != old)
                        .map_or_else(|| capture[0].to_owned(), |new| format!("{}\"{new}\"", &capture[1]))
                }) {
                    *html = updated;
                }
            }
            _ => {}
        }
    }
    let mut content = serde_json::to_value(&*project).map_err(|error| error.to_string())?;
    visit(&mut content, &questions, &references, &attribute);
    *project = serde_json::from_value(content).map_err(|error| error.to_string())?;
    Ok(())
}

fn persist_shared_bank(
    root: &Path,
    family: crate::resource_bank_store::Family,
    mut bank: serde_json::Value,
    image: Option<(String, Vec<u8>)>,
    update: bool,
    project_path: Option<&str>,
) -> Result<String, String> {
    use crate::resource_bank_store as store;
    let catalog = store::catalog(root, family)?;
    let source_id = bank["id"]
        .as_str()
        .filter(|id| !id.is_empty())
        .ok_or("Identifiant absent")?
        .to_owned();
    // Derive a stable copy identifier so reimporting a conflicting version
    // does not create a new copy on every import.
    let mut comparable = bank.clone();
    if let Some(fields) = comparable.as_object_mut() {
        fields.remove("revision");
    }
    let mut hash = Sha256::new();
    hash.update(serde_json::to_vec(&comparable).map_err(|e| e.to_string())?);
    if let Some((_, bytes)) = &image {
        hash.update(bytes);
    }
    let version_id = format!("partage-{:x}", hash.finalize());
    let mut id = source_id.clone();
    let mut duplicate = None;
    for existing in catalog["banks"].as_array().ok_or("Annuaire invalide")? {
        let Some(existing_id) = existing["id"].as_str() else {
            continue;
        };
        if existing_id != source_id && existing_id != version_id {
            continue;
        }
        let mut full = store::load(root, family, existing_id)?;
        let field = shared_bank_image_field(family);
        let same_image = match (full[field].as_str(), &image) {
            (None, None) => true,
            (Some(reference), Some((_, bytes))) => root
                .join(reference)
                .canonicalize()
                .ok()
                .filter(|path| root.canonicalize().is_ok_and(|base| path.starts_with(base)))
                .and_then(|path| fs::read(path).ok())
                .is_some_and(|existing| existing == *bytes),
            _ => false,
        };
        detach_shared_bank(&mut full, family);
        full["id"] = serde_json::json!(source_id);
        if let Some(fields) = full.as_object_mut() {
            fields.remove("revision");
        }
        if full == comparable && same_image {
            duplicate = Some(existing_id.to_owned());
            break;
        }
        if existing_id == source_id {
            id = version_id.clone();
        }
    }
    if update {
        id = source_id.clone();
    } else if let Some(existing_id) = duplicate.as_ref() {
        id = existing_id.clone();
    }
    if !update && duplicate.is_none() && catalog["banks"]
        .as_array()
        .is_some_and(|banks| banks.iter().any(|item| item["id"] == id))
    {
        id = uuid::Uuid::new_v4().to_string();
    }
    if update || duplicate.is_some() {
        let existing = store::load(root, family, &id)?;
        if !update {
            bank = existing;
        } else {
            for field in ["projectPaths", "lessonIds", "collectionIds"] {
                if let Some(value) = existing.get(field) {
                    bank[field] = value.clone();
                }
            }
            if matches!(family, crate::resource_bank_store::Family::References) {
                let revision = existing["revision"].as_u64().unwrap_or(1);
                bank["revision"] = serde_json::json!(revision.saturating_add(1));
            }
        }
    }
    if let Some(path) = project_path.filter(|_| !matches!(family, crate::resource_bank_store::Family::Questions)) {
        let mut paths = bank["projectPaths"].as_array().cloned().unwrap_or_default();
        if !paths.iter().any(|value| value.as_str().is_some_and(|value| value.eq_ignore_ascii_case(path))) {
            paths.push(serde_json::json!(path));
        }
        bank["projectPaths"] = serde_json::Value::Array(paths);
    }
    if !update && duplicate.is_some() {
        if project_path.is_some() && !matches!(family, crate::resource_bank_store::Family::Questions) {
            store::upsert(root, family, &[bank])?;
        }
        return Ok(id);
    }
    bank["id"] = serde_json::json!(id);
    if let Some((name, bytes)) = image {
        let directory = format!("banks/{:x}", Sha256::digest(id.as_bytes()));
        let target = root.join(&directory).join(&name);
        fs::create_dir_all(root.join(&directory)).map_err(|e| e.to_string())?;
        if !target
            .parent()
            .ok_or("Dossier de banque invalide")?
            .canonicalize()
            .map_err(|e| e.to_string())?
            .starts_with(root.canonicalize().map_err(|e| e.to_string())?)
        {
            return Err("Dossier de banque invalide".into());
        }
        match OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&target)
        {
            Ok(mut file) => file.write_all(&bytes).map_err(|e| e.to_string())?,
            Err(error)
                if error.kind() == std::io::ErrorKind::AlreadyExists
                    && fs::symlink_metadata(&target)
                        .is_ok_and(|meta| meta.file_type().is_file())
                    && fs::read(&target).is_ok_and(|existing| existing == bytes) => {}
            Err(error) => return Err(error.to_string()),
        }
        bank[shared_bank_image_field(family)] =
            serde_json::json!(format!("{directory}/{name}"));
    }
    store::upsert(root, family, &[bank])?;
    Ok(id)
}

#[tauri::command]
pub fn open_paideia_archive_bytes(
    archive_name: String,
    archive_bytes: Vec<u8>,
    destination_root: String,
) -> Result<String, String> {
    if archive_bytes.len() as u64 > PAIDEIA_ARCHIVE_MAX_COMPRESSED_BYTES {
        return Err("L’archive .paideia dépasse la taille maximale autorisée de 2 Go".to_string());
    }
    let projects_root = PathBuf::from(&destination_root).join("projects");
    fs::create_dir_all(&projects_root).map_err(|err| err.to_string())?;
    let archive_stem = sanitize_filename(
        Path::new(&archive_name)
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("paideia-project"),
    );
    let project_root = unique_project_folder(&projects_root, &archive_stem)?;
    let staging_root = unique_sibling_path(&projects_root, &archive_stem, "paideia-import");
    let import_result = (|| -> Result<(), String> {
        extract_paideia_archive_to(&archive_bytes, &staging_root)?;
        let mut project = load_project_from_path(&staging_root.to_string_lossy())?;
        let existing_titles = collect_project_titles(&projects_root, Some(&staging_root))?;
        let resolved_title = next_project_title(&project.title, &existing_titles);
        if resolved_title != project.title {
            project.title = resolved_title.clone();
            project.course.title = resolved_title.clone();
            project.slug =
                sanitize_filename(&resolved_title.to_ascii_lowercase().replace(' ', "-"));
            touch_project(&mut project);
            save_project_to_path(&staging_root.to_string_lossy(), &project)?;
        }
        if project_root.exists() {
            return Err("Le dossier de destination de la leçon existe déjà".to_string());
        }
        fs::rename(&staging_root, &project_root).map_err(|err| err.to_string())?;
        Ok(())
    })();
    if import_result.is_err() && staging_root.exists() {
        let _ = fs::remove_dir_all(&staging_root);
    }
    import_result?;
    Ok(project_root.to_string_lossy().to_string())
}

pub(crate) fn extract_paideia_archive_to(
    archive_bytes: &[u8],
    staging_root: &Path,
) -> Result<(), String> {
    if !archive_bytes.starts_with(b"PK\x03\x04") {
        return Err(format!(
            "PAIDEIA_SECURITY_ARCHIVE_REJECTED\n{}",
            "L’archive .paideia doit être un ZIP simple et non auto-extractible"
        ));
    }
    let mut archive = ZipArchive::new(Cursor::new(archive_bytes))
        .map_err(|_| "Archive .paideia invalide ou illisible".to_string())?;
    if archive.len() > PAIDEIA_ARCHIVE_MAX_ENTRIES {
        return Err(format!(
            "L’archive .paideia contient trop d’éléments (maximum {})",
            PAIDEIA_ARCHIVE_MAX_ENTRIES
        ));
    }

    let mut expanded_bytes = 0_u64;
    let mut paths = HashSet::new();
    let mut has_project_json = false;
    let mut manifest_bytes = None;
    let mut archived_files = HashMap::new();
    for index in 0..archive.len() {
        let entry = archive.by_index(index).map_err(|err| err.to_string())?;
        let enclosed = entry
            .enclosed_name()
            .ok_or_else(|| format!("Chemin dangereux refusé dans l’archive : {}", entry.name()))?
            .to_path_buf();
        if enclosed.as_os_str().is_empty() {
            continue;
        }
        if entry
            .unix_mode()
            .map(|mode| {
                let kind = mode & 0o170000;
                kind != 0 && kind != 0o100000 && kind != 0o040000
            })
            .unwrap_or(false)
        {
            return Err(format!(
                "Type de fichier non autorisé dans l’archive : {}",
                entry.name()
            ));
        }
        let normalized_path = enclosed
            .to_string_lossy()
            .replace('\\', "/")
            .to_ascii_lowercase();
        if !paths.insert(normalized_path) {
            return Err(format!("Chemin dupliqué dans l’archive : {}", entry.name()));
        }
        if !entry.is_dir() {
            let archive_entry_path = enclosed.to_string_lossy().replace('\\', "/");
            if archive_entry_path.eq_ignore_ascii_case(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST) {
                if entry.size() > PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST_MAX_BYTES {
                    return Err("Manifeste d’intégrité PAIDEIA trop volumineux".to_string());
                }
                let mut bytes = Vec::with_capacity(entry.size() as usize);
                entry
                    .take(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST_MAX_BYTES + 1)
                    .read_to_end(&mut bytes)
                    .map_err(|err| err.to_string())?;
                if bytes.len() as u64 > PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST_MAX_BYTES {
                    return Err("Manifeste d’intégrité PAIDEIA trop volumineux".to_string());
                }
                manifest_bytes = Some(bytes);
                continue;
            }
            let forbidden_extension = enclosed
                .extension()
                .and_then(|value| value.to_str())
                .map(|value| {
                    PAIDEIA_ARCHIVE_FORBIDDEN_EXTENSIONS
                        .contains(&value.to_ascii_lowercase().as_str())
                })
                .unwrap_or(false);
            if forbidden_extension {
                return Err(format!(
                    "PAIDEIA_SECURITY_ARCHIVE_REJECTED\nFichier exécutable interdit dans l’archive .paideia : {}",
                    entry.name()
                ));
            }
            if archive_entry_path.eq_ignore_ascii_case(SHARED_RESOURCE_BANKS_FILE)
                && entry.size() > SHARED_RESOURCE_BANKS_MAX_BYTES
            {
                return Err("Les banques associées dépassent la taille maximale de 128 Mio".into());
            }
            if entry.size() > PAIDEIA_ARCHIVE_MAX_ENTRY_BYTES {
                return Err(format!(
                    "Fichier trop volumineux dans l’archive : {}",
                    entry.name()
                ));
            }
            expanded_bytes = expanded_bytes
                .checked_add(entry.size())
                .ok_or_else(|| "Taille décompressée de l’archive invalide".to_string())?;
            if expanded_bytes > PAIDEIA_ARCHIVE_MAX_EXPANDED_BYTES {
                return Err("L’archive .paideia décompressée dépasse 8 Go".to_string());
            }
            if enclosed == Path::new("project.json") {
                has_project_json = true;
            }
            archived_files.insert(
                archive_entry_path.to_ascii_lowercase(),
                (archive_entry_path, entry.size()),
            );
        }
    }
    if !has_project_json {
        return Err("Le fichier .paideia ne contient pas project.json".to_string());
    }
    let manifest_bytes = manifest_bytes.ok_or_else(|| format!(
            "{PAIDEIA_ARCHIVE_INTEGRITY_REJECTED}\nL’archive .paideia ne contient pas de manifeste d’intégrité"
        ))?;
    let expected_integrity =
        validate_paideia_archive_integrity_manifest(&manifest_bytes, &archived_files, &mut archive)
            .map_err(|message| format!("{PAIDEIA_ARCHIVE_INTEGRITY_REJECTED}\n{message}"))?;

    fs::create_dir_all(staging_root).map_err(|err| err.to_string())?;
    let extraction_result = (|| -> Result<(), String> {
        let mut actual_total = 0_u64;
        for index in 0..archive.len() {
            let mut entry = archive.by_index(index).map_err(|err| err.to_string())?;
            let enclosed = entry
                .enclosed_name()
                .ok_or_else(|| "Archive .paideia invalide".to_string())?
                .to_path_buf();
            if enclosed.as_os_str().is_empty() {
                continue;
            }
            let archive_entry_path = enclosed.to_string_lossy().replace('\\', "/");
            if archive_entry_path.eq_ignore_ascii_case(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST) {
                continue;
            }
            let output_path = staging_root.join(&enclosed);
            if entry.is_dir() {
                fs::create_dir_all(&output_path).map_err(|err| err.to_string())?;
                continue;
            }
            if let Some(parent) = output_path.parent() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
            let expected_size = entry.size();
            let mut signature = [0_u8; 4];
            let signature_length = entry.read(&mut signature).map_err(|err| err.to_string())?;
            if signature_length >= 2 && signature[..2] == *b"MZ" {
                return Err(format!(
                    "PAIDEIA_SECURITY_ARCHIVE_REJECTED\nFichier exécutable interdit dans l’archive .paideia : {}",
                    enclosed.display()
                ));
            }
            let mut output = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&output_path)
                .map_err(|err| err.to_string())?;
            output
                .write_all(&signature[..signature_length])
                .map_err(|err| err.to_string())?;
            let mut hasher = Sha256::new();
            hasher.update(&signature[..signature_length]);
            let remaining_limit = expected_size
                .saturating_sub(signature_length as u64)
                .saturating_add(1);
            let mut limited_entry = entry.take(remaining_limit);
            let mut copied = 0_u64;
            let mut buffer = [0_u8; 64 * 1024];
            loop {
                let read = limited_entry
                    .read(&mut buffer)
                    .map_err(|err| err.to_string())?;
                if read == 0 {
                    break;
                }
                hasher.update(&buffer[..read]);
                output
                    .write_all(&buffer[..read])
                    .map_err(|err| err.to_string())?;
                copied = copied
                    .checked_add(read as u64)
                    .ok_or_else(|| "Taille décompressée de l’archive invalide".to_string())?;
            }
            let actual_size = (signature_length as u64)
                .checked_add(copied)
                .ok_or_else(|| "Taille décompressée de l’archive invalide".to_string())?;
            if actual_size != expected_size {
                return Err(format!(
                    "Taille incohérente dans l’archive : {}",
                    enclosed.display()
                ));
            }
            actual_total = actual_total
                .checked_add(actual_size)
                .ok_or_else(|| "Taille décompressée de l’archive invalide".to_string())?;
            if actual_total > PAIDEIA_ARCHIVE_MAX_EXPANDED_BYTES {
                return Err("L’archive .paideia décompressée dépasse 8 Go".to_string());
            }
            let integrity = expected_integrity
                .get(&archive_entry_path.to_ascii_lowercase())
                .ok_or_else(|| {
                    format!(
                        "{PAIDEIA_ARCHIVE_INTEGRITY_REJECTED}\nFichier absent du manifeste d’intégrité : {archive_entry_path}"
                    )
                })?;
            let actual_hash = sha256_digest_hex(hasher.finalize().as_slice());
            if integrity.size != actual_size || !integrity.sha256.eq_ignore_ascii_case(&actual_hash)
            {
                return Err(format!(
                    "{PAIDEIA_ARCHIVE_INTEGRITY_REJECTED}\nContrôle d’intégrité SHA-256 en échec pour : {archive_entry_path}"
                ));
            }
            output.sync_all().map_err(|err| err.to_string())?;
        }
        Ok(())
    })();
    if extraction_result.is_err() && staging_root.exists() {
        let _ = fs::remove_dir_all(staging_root);
    }
    extraction_result
}

fn validate_paideia_archive_integrity_manifest(
    manifest_bytes: &[u8],
    archived_files: &HashMap<String, (String, u64)>,
    archive: &mut ZipArchive<Cursor<&[u8]>>,
) -> Result<HashMap<String, PaideiaArchiveIntegrityEntry>, String> {
    let manifest = archive_integrity::parse(manifest_bytes)?;
    let mut actual = Vec::with_capacity(archived_files.len());
    let mut buffer = [0_u8; 64 * 1024];
    // Complete bounded verification before creating the extraction directory.
    for index in 0..archive.len() {
        let entry = archive.by_index(index).map_err(|err| err.to_string())?;
        let path = entry
            .enclosed_name()
            .ok_or("Chemin d’archive invalide")?
            .to_string_lossy()
            .replace('\\', "/");
        if entry.is_dir() || path.eq_ignore_ascii_case(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST) {
            continue;
        }
        let (_, expected_size) = archived_files
            .get(&path.to_ascii_lowercase())
            .ok_or("Fichier d’archive inattendu")?;
        let mut reader = entry.take(expected_size + 1);
        let mut hasher = Sha256::new();
        let mut size = 0_u64;
        loop {
            let read = reader.read(&mut buffer).map_err(|err| err.to_string())?;
            if read == 0 {
                break;
            }
            size += read as u64;
            hasher.update(&buffer[..read]);
        }
        if size != *expected_size {
            return Err("Taille d’archive incohérente".to_string());
        }
        actual.push(PaideiaArchiveIntegrityEntry {
            path,
            size,
            sha256: sha256_digest_hex(&hasher.finalize()),
        });
    }
    archive_integrity::verify(&manifest, &actual)?;
    Ok(actual
        .into_iter()
        .map(|entry| (entry.path.to_ascii_lowercase(), entry))
        .collect())
}

#[tauri::command]
pub fn open_paideia_archive_path(
    archive_path: String,
    destination_root: String,
) -> Result<String, String> {
    let path = PathBuf::from(&archive_path);
    let metadata = fs::metadata(&path).map_err(|err| err.to_string())?;
    if !metadata.is_file() || metadata.len() > PAIDEIA_ARCHIVE_MAX_COMPRESSED_BYTES {
        return Err("L’archive .paideia est invalide ou dépasse 2 Go".to_string());
    }
    let archive_name = path
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or("paideia-project.paideia")
        .to_string();
    let bytes = fs::read(path).map_err(|err| err.to_string())?;
    open_paideia_archive_bytes(archive_name, bytes, destination_root)
}

#[tauri::command]
pub async fn export_scorm_12(
    app: tauri::AppHandle,
    project_path: String,
    destination_root: String,
    app_language: String,
) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        export_scorm_12_blocking(app, project_path, destination_root, app_language)
    })
    .await
    .map_err(|err| format!("Échec de la tâche d’export SCORM : {err}"))?
}

fn export_scorm_12_blocking(
    app: tauri::AppHandle,
    project_path: String,
    destination_root: String,
    _app_language: String,
) -> Result<String, String> {
    ensure_editable_collaboration_export(&project_path)?;
    let project = load_project_from_path(&project_path)?;
    validate_scorm_quiz_lms_score_sources(&project)?;
    validate_scorm_find_elements_configuration(&project, &project_path)?;
    let destination_dir = PathBuf::from(destination_root);
    fs::create_dir_all(&destination_dir).map_err(|err| err.to_string())?;
    let archive_path = destination_dir.join(format!(
        "{}_{}.zip",
        slug_from_title(&project.title),
        Utc::now().format("%d%m%Y_%H%M")
    ));

    write_scorm_archive(Some(&app), &project_path, &project, &archive_path)?;
    Ok(archive_path.to_string_lossy().to_string())
}

#[tauri::command]
pub async fn export_scorm_12_to(
    app: tauri::AppHandle,
    project_path: String,
    archive_path: String,
    app_language: String,
) -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(move || {
        export_scorm_12_to_blocking(app, project_path, archive_path, app_language)
    })
    .await
    .map_err(|err| format!("Échec de la tâche d’export SCORM : {err}"))?
}

fn export_scorm_12_to_blocking(
    app: tauri::AppHandle,
    project_path: String,
    archive_path: String,
    _app_language: String,
) -> Result<String, String> {
    ensure_editable_collaboration_export(&project_path)?;
    let project = load_project_from_path(&project_path)?;
    validate_scorm_quiz_lms_score_sources(&project)?;
    validate_scorm_find_elements_configuration(&project, &project_path)?;
    let output = PathBuf::from(archive_path);
    if let Some(parent) = output.parent() {
        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
    }
    write_scorm_archive(Some(&app), &project_path, &project, &output)?;
    Ok(output.to_string_lossy().to_string())
}

fn validate_scorm_find_elements_configuration(
    project: &PaideiaProject,
    project_path: &str,
) -> Result<(), String> {
    let project_root = resolve_project_path(project_path);
    let mut invalid_activities = Vec::new();

    for module_item in &project.course.modules {
        for chapter in &module_item.chapters {
            for page in &chapter.pages {
                for block in &page.blocks {
                    if block.block_type != "find-elements" {
                        continue;
                    }

                    let image_ref = first_asset_with_extensions(
                        block,
                        &["gif", "jpg", "jpeg", "png", "svg", "webp"],
                    );
                    let has_image = image_ref
                        .as_ref()
                        .map(|asset| {
                            project_root
                                .join("assets")
                                .join(normalize_scorm_asset_ref(asset))
                                .is_file()
                        })
                        .unwrap_or(false);
                    let has_zone = block
                        .find_elements
                        .as_ref()
                        .map(|activity| !activity.zones.is_empty())
                        .unwrap_or(false);

                    if has_image && has_zone {
                        continue;
                    }

                    let activity_title = if block.title.trim().is_empty() {
                        "Chercher dans l'image"
                    } else {
                        block.title.as_str()
                    };
                    let missing = match (has_image, has_zone) {
                        (false, false) => "image absente et aucune zone de sélection configurée",
                        (false, true) => "image absente",
                        (true, false) => "aucune zone de sélection configurée",
                        (true, true) => unreachable!(),
                    };
                    invalid_activities.push(format!(
                        "{} / {} / {} ({})",
                        module_item.title, chapter.title, activity_title, missing
                    ));
                }
            }
        }
    }

    if invalid_activities.is_empty() {
        Ok(())
    } else {
        Err(format!(
            "Export SCORM 1.2 impossible : chaque activité « Chercher dans l'image » doit contenir une image et au moins une zone de sélection. Activité(s) à corriger : {}.",
            invalid_activities.join(" ; ")
        ))
    }
}

fn validate_scorm_quiz_lms_score_sources(project: &PaideiaProject) -> Result<(), String> {
    let mut quiz_sources = Vec::new();
    for module_item in &project.course.modules {
        for chapter in &module_item.chapters {
            let mut chapter_quiz_sources = Vec::new();
            for page in &chapter.pages {
                for block in &page.blocks {
                    if block.block_type == "quiz"
                        && block
                            .quiz
                            .as_ref()
                            .map(|quiz| quiz.settings.send_score_to_lms)
                            .unwrap_or(false)
                    {
                        quiz_sources.push(format!(
                            "{} / {} / {}",
                            module_item.title,
                            chapter.title,
                            if block.title.trim().is_empty() {
                                "Questionnaire"
                            } else {
                                block.title.as_str()
                            }
                        ));
                        chapter_quiz_sources.push(format!(
                            "{} / {} / {}",
                            module_item.title,
                            chapter.title,
                            if block.title.trim().is_empty() {
                                "Questionnaire"
                            } else {
                                block.title.as_str()
                            }
                        ));
                    }
                }
            }
            if chapter_quiz_sources.len() > 1 {
                return Err(format!(
                    "Export SCORM 1.2 impossible : un seul questionnaire peut envoyer le score au LMS dans le chapitre \"{}\". Questionnaires marquÃ©s : {}.",
                    chapter.title,
                    chapter_quiz_sources.join(" ; ")
                ));
            }
            if let Some(tracking) = chapter.scorm_tracking.as_ref() {
                let mode = tracking.mode.trim();
                let success = tracking.success_status.trim();
                let failure = tracking.failure_status.trim();
                let is_allowed_mode = matches!(
                    mode,
                    "" | "completion" | "quiz-blocking" | "quiz-certification" | "advanced"
                );
                let is_allowed_pair = matches!(
                    (success, failure),
                    ("completed", "incomplete")
                        | ("completed", "failed")
                        | ("passed", "incomplete")
                        | ("passed", "failed")
                );
                if !is_allowed_mode {
                    return Err(format!(
                        "Export SCORM 1.2 impossible : le mode SCORM / LMS du chapitre \"{}\" est invalide.",
                        chapter.title
                    ));
                }
                if !is_allowed_pair {
                    return Err(format!(
                        "Export SCORM 1.2 impossible : le couple de statuts SCORM / LMS du chapitre \"{}\" n'est pas pris en charge en SCORM 1.2.",
                        chapter.title
                    ));
                }
                if mode != "" && mode != "completion" && chapter_quiz_sources.is_empty() {
                    return Err(format!(
                        "Export SCORM 1.2 impossible : le chapitre \"{}\" utilise un mode quiz SCORM / LMS mais aucun questionnaire n'envoie le score au LMS dans ce chapitre.",
                        chapter.title
                    ));
                }
            }
        }
    }
    if quiz_sources.len() > 1 {
        return Err(format!(
            "Export SCORM 1.2 impossible : un seul questionnaire peut envoyer le score au LMS dans tout le projet. Questionnaires marquÃ©s : {}.",
            quiz_sources.join(" ; ")
        ));
    }
    Ok(())
}

fn chapter_has_lms_quiz_sender(chapter: &PaideiaChapter) -> bool {
    chapter.pages.iter().any(|page| {
        page.blocks.iter().any(|block| {
            block.block_type == "quiz"
                && block
                    .quiz
                    .as_ref()
                    .map(|quiz| quiz.settings.send_score_to_lms)
                    .unwrap_or(false)
        })
    })
}

fn normalized_chapter_scorm_tracking(chapter: &PaideiaChapter) -> (String, String, String) {
    let has_lms_sender = chapter_has_lms_quiz_sender(chapter);
    if let Some(tracking) = chapter.scorm_tracking.as_ref() {
        let mode = tracking.mode.trim();
        let success = tracking.success_status.trim();
        let failure = tracking.failure_status.trim();
        let is_allowed_mode = matches!(
            mode,
            "" | "completion" | "quiz-blocking" | "quiz-certification" | "advanced"
        );
        let is_allowed_pair = matches!(
            (success, failure),
            ("completed", "incomplete")
                | ("completed", "failed")
                | ("passed", "incomplete")
                | ("passed", "failed")
        );

        if is_allowed_mode && is_allowed_pair {
            return (
                if mode.is_empty() {
                    if has_lms_sender {
                        "quiz-certification".to_string()
                    } else {
                        "completion".to_string()
                    }
                } else {
                    mode.to_string()
                },
                success.to_string(),
                failure.to_string(),
            );
        }
    }

    if has_lms_sender {
        (
            "quiz-certification".to_string(),
            "passed".to_string(),
            "failed".to_string(),
        )
    } else {
        (
            "completion".to_string(),
            "completed".to_string(),
            "incomplete".to_string(),
        )
    }
}

