#[tauri::command]
pub fn reorder_chapter(
    project_path: String,
    module_id: String,
    chapter_id: String,
    target_index: usize,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let (current_index, next_index, before, after) = {
        let module = project
            .course
            .modules
            .iter_mut()
            .find(|module| module.id == module_id)
            .ok_or_else(|| "Target module not found".to_string())?;
        let current_index = unique_chapter_index(module, &chapter_id)?;
        let before = module.chapters.clone();
        let chapter = module.chapters.remove(current_index);
        let next_index = target_index.min(module.chapters.len());
        module.chapters.insert(next_index, chapter);
        let after = module.chapters.clone();
        (current_index, next_index, before, after)
    };

    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "chapter",
        &chapter_id,
        "chapter.reordered",
        "Chapitre déplacé",
        &format!("content/chapters/{}.json", chapter_id),
        serde_json::json!({
            "moduleId": module_id,
            "chapterId": chapter_id,
            "fromIndex": current_index,
            "toIndex": next_index
        }),
        serde_json::json!({ "before": before, "after": after }),
    )?;

    load_workspace_state_from_path(&project_path)
}

