fn find_html_duplicate_source(
    project_path: &str,
    project: &PaideiaProject,
    page_id: &str,
    source_block_id: &str,
) -> Result<PaideiaBlock, String> {
    let page = project
        .course
        .modules
        .iter()
        .flat_map(|module| module.chapters.iter())
        .flat_map(|chapter| chapter.pages.iter())
        .find(|page| page.id == page_id)
        .ok_or_else(|| "Target page not found".to_string())?;
    let source = page
        .blocks
        .iter()
        .find(|block| block.id == source_block_id && block.block_type == "html-custom")
        .ok_or_else(|| "Activité HTML source introuvable dans cette page.".to_string())?;
    if let Some(asset_root) = source.html_asset_root.as_deref() {
        let asset_root = validate_scorm_asset_ref(asset_root)?;
        let entry_file = source.html_entry_file.as_deref()
            .ok_or_else(|| "Le paquet HTML source n’a pas de point d’entrée.".to_string())?;
        let entry_file = validate_scorm_asset_ref(entry_file)?;
        if !asset_root.starts_with("html/") || !entry_file.starts_with(&format!("{asset_root}/")) {
            return Err("Le point d’entrée HTML est situé hors de son paquet.".into());
        }
        let assets_dir = resolve_project_path(project_path).join("assets");
        for asset_ref in source.asset_refs.iter().map(String::as_str).chain(std::iter::once(entry_file.as_str())) {
            let asset_ref = validate_scorm_asset_ref(asset_ref)?;
            let metadata = fs::metadata(assets_dir.join(&asset_ref))
                .map_err(|error| format!("Impossible de dupliquer le paquet HTML : {asset_ref} ({error})."))?;
            if !metadata.is_file() {
                return Err(format!("Le fichier du paquet HTML n’est pas un fichier : {asset_ref}."));
            }
        }
    }
    Ok(source.clone())
}

#[tauri::command]
pub fn create_block(
    project_path: String,
    page_id: String,
    target_index: Option<usize>,
    duplicate_source_block_id: Option<String>,
    block_type: String,
    title: String,
    summary: String,
    content_html: Option<String>,
    quote_author_html: Option<String>,
    quote_show_author: Option<bool>,
    media_layout: Option<String>,
    image_size: Option<String>,
    content_width: Option<String>,
    content_align: Option<String>,
    media_gap: Option<String>,
    vertical_align: Option<String>,
    image_rounded: Option<bool>,
    media_file_name: Option<String>,
    image_crop: Option<crate::models::ImageCrop>,
    image_accessibility: Option<crate::models::ImageAccessibility>,
    video_caption_color: Option<String>,
    video_caption_background_enabled: Option<bool>,
    video_caption_outline: Option<String>,
    video_subtitle_original_ref: Option<String>,
    video_allow_fullscreen: Option<bool>,
    audio_autoplay_next: Option<bool>,
    audio_allow_download: Option<bool>,
    image360_initial_yaw: Option<f64>,
    image360_initial_pitch: Option<f64>,
    image360_zoom_enabled: Option<bool>,
    image360_full_width: Option<bool>,
    image360_allow_fullscreen: Option<bool>,
    header_background_color: Option<String>,
    header_text_color: Option<String>,
    header_text_outline: Option<String>,
    header_text_outline_color: Option<String>,
    header_height: Option<String>,
    header_image_position_y: Option<f64>,
    button_background_color: Option<String>,
    button_text_color: Option<String>,
    panel_background_color: Option<String>,
    panel_border_color: Option<String>,
    panel_border_width: Option<String>,
    panel_border_style: Option<String>,
    panel_padding: Option<String>,
    panel_rounded: Option<bool>,
    panel_shadow: Option<bool>,
    note_icon: Option<String>,
    note_show_icon: Option<bool>,
    note_icon_color: Option<String>,
    note_icon_matches_border: Option<bool>,
    flip_card_front_background_color: Option<String>,
    flip_card_back_background_color: Option<String>,
    flip_card_front_border_color: Option<String>,
    flip_card_back_border_color: Option<String>,
    slides_activity_background_color: Option<String>,
    slides_activity_border_color: Option<String>,
    slides_activity_border_width: Option<String>,
    slides_activity_border_style: Option<String>,
    slides_activity_rounded: Option<bool>,
    slides_activity_shadow: Option<bool>,
    section_background_color: Option<String>,
    section_background_image_ref: Option<String>,
    section_background_opacity: Option<f64>,
    section_background_overlay_dark: Option<bool>,
    section_background_blur: Option<f64>,
    section_background_position_y: Option<f64>,
    section_background_rounded: Option<bool>,
    section_background_wide: Option<bool>,
    section_background_height: Option<String>,
    divider_color: Option<String>,
    divider_width: Option<String>,
    divider_style: Option<String>,
    marker_scheme: Option<String>,
    marker_type: Option<String>,
    marker_text_color: Option<String>,
    point_of_interest_markers: Option<Vec<crate::models::PointOfInterestMarker>>,
    image360_hotspots: Option<Vec<crate::models::Image360Hotspot>>,
    activity_items: Option<Vec<crate::models::ActivityItem>>,
    situational_dialogue_characters: Option<Vec<SituationalDialogueCharacter>>,
    attachment_files: Option<Vec<AttachmentFile>>,
    quiz: Option<QuizActivityData>,
    find_elements: Option<crate::models::FindElementsActivityData>,
    complete: Option<crate::models::CompleteActivityData>,
    card_sort: Option<crate::models::CardSortActivityData>,
    matching: Option<crate::models::MatchingActivityData>,
    marker_popup_width: Option<String>,
    marker_popup_height: Option<String>,
    padding_offset: Option<i32>,
    asset_refs: Option<Vec<String>>,
    subtitle_refs: Option<Vec<String>>,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let html_duplicate_source = match duplicate_source_block_id {
        Some(source_id) if block_type == "html-custom" => {
            Some(find_html_duplicate_source(&project_path, &project, &page_id, &source_id)?)
        }
        Some(_) => return Err("La duplication de paquet est réservée aux activités HTML.".into()),
        None => None,
    };
    let content_html = html_duplicate_source
        .as_ref()
        .map(|source| source.content_html.clone())
        .unwrap_or(content_html);
    let asset_refs = html_duplicate_source
        .as_ref()
        .map(|source| Some(source.asset_refs.clone()))
        .unwrap_or(asset_refs);
    let next_block_id = next_available_block_id(&project);
    let mut next_attachment_files = attachment_files.unwrap_or_default();
    if block_type == "attachment" && !next_attachment_files.is_empty() {
        let root = resolve_project_path(&project_path);
        let assets_dir = root.join("assets");
        let mut copied_files = Vec::with_capacity(next_attachment_files.len());
        for (index, mut file) in next_attachment_files.into_iter().enumerate() {
            let source_path = assets_dir.join(normalize_scorm_asset_ref(&file.asset_ref));
            if !source_path.exists() {
                return Err(format!(
                    "Fichier source introuvable pour la duplication : {}",
                    file.display_name
                ));
            }
            let next_ref =
                next_attachment_storage_ref(&next_block_id, &file.display_name, &copied_files);
            let destination_path = assets_dir.join(&next_ref);
            if let Some(parent) = destination_path.parent() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
            fs::copy(&source_path, &destination_path).map_err(|err| err.to_string())?;
            file.id = format!("attachment_{}_{}", compact_timestamp(), index + 1);
            file.stored_name = Path::new(&next_ref)
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or(&file.display_name)
                .to_string();
            file.asset_ref = next_ref;
            copied_files.push(file);
        }
        next_attachment_files = copied_files;
    }
    let mut next_activity_items = activity_items.unwrap_or_default();
    if block_type == "image-grid" {
        next_activity_items.truncate(4);
    }
    let block = PaideiaBlock {
        id: next_block_id.clone(),
        block_type: block_type.clone(),
        family: None,
        variant: None,
        title: title.clone(),
        summary: summary.clone(),
        content_html: content_html.clone(),
        quote_author_html,
        quote_show_author,
        html_asset_root: html_duplicate_source.as_ref().and_then(|source| source.html_asset_root.clone()),
        html_entry_file: html_duplicate_source.as_ref().and_then(|source| source.html_entry_file.clone()),
        html_package_name: html_duplicate_source.as_ref().and_then(|source| source.html_package_name.clone()),
        media_layout: media_layout.or_else(|| default_media_layout_for_type(&block_type)),
        image_size: image_size.or_else(|| default_image_size_for_type(&block_type)),
        content_width,
        content_align,
        media_gap,
        vertical_align,
        image_rounded,
        media_file_name,
        image_crop,
        image_accessibility,
        image_annotation_state_ref: None,
        image_annotation_source_asset_ref: None,
        video_caption_color,
        video_caption_background_enabled,
        video_caption_outline,
        video_subtitle_original_ref,
        video_original_asset_ref: None,
        video_optimized_asset_ref: None,
        video_optimization_profile: None,
        video_allow_fullscreen,
        audio_autoplay_next,
        audio_allow_download,
        image360_initial_yaw,
        image360_initial_pitch,
        image360_zoom_enabled,
        image360_full_width,
        image360_allow_fullscreen,
        header_background_color,
        header_text_color,
        header_text_outline,
        header_text_outline_color,
        header_height,
        header_image_position_y,
        button_background_color,
        button_text_color,
        panel_background_color,
        panel_border_color,
        panel_border_width,
        panel_border_style,
        panel_padding,
        panel_rounded,
        panel_shadow,
        note_icon: if block_type == "note" {
            Some(normalized_note_icon(note_icon.as_deref()).to_string())
        } else {
            note_icon
        },
        note_show_icon: if block_type == "note" {
            Some(note_show_icon.unwrap_or(true))
        } else {
            note_show_icon
        },
        note_icon_color,
        note_icon_matches_border: if block_type == "note" {
            Some(note_icon_matches_border.unwrap_or(true))
        } else {
            note_icon_matches_border
        },
        flip_card_front_background_color,
        flip_card_back_background_color,
        flip_card_front_border_color,
        flip_card_back_border_color,
        slides_activity_background_color,
        slides_activity_border_color,
        slides_activity_border_width,
        slides_activity_border_style,
        slides_activity_rounded,
        slides_activity_shadow,
        section_background_color,
        section_background_image_ref,
        section_background_opacity,
        section_background_overlay_dark,
        section_background_blur,
        section_background_position_y: section_background_position_y
            .map(|value| value.clamp(0.0, 100.0)),
        section_background_rounded,
        section_background_wide: if supports_activity_background(&block_type) {
            Some(section_background_wide.unwrap_or(true))
        } else {
            section_background_wide
        },
        section_background_height,
        divider_color,
        divider_width,
        divider_style,
        marker_scheme,
        marker_type,
        marker_text_color,
        point_of_interest_markers: if block_type == "point-of-interest" {
            point_of_interest_markers.unwrap_or_default()
        } else {
            Vec::new()
        },
        image360_hotspots: image360_hotspots.unwrap_or_default(),
        activity_items: next_activity_items,
        situational_dialogue_characters: situational_dialogue_characters.unwrap_or_default(),
        attachment_files: next_attachment_files,
        quiz,
        find_elements: if block_type == "find-elements" {
            find_elements
        } else {
            None
        },
        complete: if block_type == "complete" {
            complete
        } else {
            None
        },
        card_sort: if block_type == "card-sort" {
            card_sort
        } else {
            None
        },
        matching: if block_type == "matching" {
            matching
        } else {
            None
        },
        marker_popup_width: if block_type == "point-of-interest" {
            marker_popup_width
        } else {
            None
        },
        marker_popup_height: if block_type == "point-of-interest" {
            marker_popup_height
        } else {
            None
        },
        padding_offset,
        tracking_key: format!("{}-{}", block_type, next_block_id),
        source_format: None,
        source_block_type: None,
        source_raw_html: None,
        asset_refs: asset_refs.unwrap_or_default(),
        rich_inline_asset_refs: Vec::new(),
        subtitle_refs: subtitle_refs.unwrap_or_default(),
    };

    let page = project
        .course
        .modules
        .iter_mut()
        .flat_map(|module| module.chapters.iter_mut())
        .flat_map(|chapter| chapter.pages.iter_mut())
        .find(|page| page.id == page_id)
        .ok_or_else(|| "Target page not found".to_string())?;

    let insertion_index = target_index
        .unwrap_or(page.blocks.len())
        .min(page.blocks.len());
    page.blocks.insert(insertion_index, block.clone());
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "block",
        &next_block_id,
        "block.created",
        "ActivitÃ© crÃ©Ã©e",
        &format!("content/blocks/{}.json", next_block_id),
        serde_json::json!({
            "pageId": page_id,
            "type": block_type,
            "title": title,
            "summary": summary,
            "contentHtml": content_html,
            "targetIndex": insertion_index
        }),
        serde_json::json!({ "before": null, "after": block }),
    )?;

    load_workspace_state_from_path(&project_path)
}

fn collect_json_ids(value: &serde_json::Value, ids: &mut Vec<String>) {
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                if key == "id" {
                    if let Some(id) = child.as_str().filter(|id| !id.trim().is_empty()) {
                        ids.push(id.to_string());
                    }
                }
                collect_json_ids(child, ids);
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                collect_json_ids(item, ids);
            }
        }
        _ => {}
    }
}

fn replace_json_strings(value: &mut serde_json::Value, replacements: &HashMap<String, String>) {
    match value {
        serde_json::Value::String(text) => {
            if let Some(replacement) = replacements.get(text) {
                *text = replacement.clone();
            } else if text.contains("data-paideia-") {
                for (source, replacement) in replacements {
                    for attribute in [
                        "data-paideia-asset-ref",
                        "data-paideia-bookmark-id",
                        "data-paideia-reference-id",
                        "data-paideia-bookmark-target",
                        "data-paideia-font-id",
                    ] {
                        for quote in ['"', '\''] {
                            let source_attribute =
                                format!("{}={}{}{}", attribute, quote, source, quote);
                            if text.contains(&source_attribute) {
                                let replacement_attribute =
                                    format!("{}={}{}{}", attribute, quote, replacement, quote);
                                *text = text.replace(&source_attribute, &replacement_attribute);
                            }
                        }
                    }
                    if source.starts_with("rich-") {
                        *text = text.replace(
                            &format!("PaideiaRichFont-{source}"),
                            &format!("PaideiaRichFont-{replacement}"),
                        );
                    }
                }
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                replace_json_strings(item, replacements);
            }
        }
        serde_json::Value::Object(map) => {
            for child in map.values_mut() {
                replace_json_strings(child, replacements);
            }
        }
        _ => {}
    }
}

fn collect_json_asset_refs(value: &serde_json::Value, refs: &mut HashSet<String>) {
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                match (key.as_str(), child) {
                    (key, serde_json::Value::String(asset_ref)) if key.ends_with("Ref") => {
                        let trimmed = asset_ref.trim();
                        if !trimmed.is_empty() {
                            refs.insert(trimmed.to_string());
                        }
                    }
                    (key, serde_json::Value::Array(items)) if key.ends_with("Refs") => {
                        for item in items {
                            if let Some(asset_ref) =
                                item.as_str().filter(|value| !value.trim().is_empty())
                            {
                                refs.insert(asset_ref.trim().to_string());
                            }
                        }
                    }
                    _ => {}
                }
                collect_json_asset_refs(child, refs);
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                collect_json_asset_refs(item, refs);
            }
        }
        _ => {}
    }
}

fn is_external_or_default_asset_ref(asset_ref: &str) -> bool {
    let normalized = asset_ref.replace('\\', "/");
    normalized.starts_with("default-assets/")
        || normalized.starts_with("http://")
        || normalized.starts_with("https://")
        || normalized.starts_with("data:")
        || Path::new(asset_ref).is_absolute()
}

fn copy_pasted_activity_assets(
    source_project_path: &str,
    target_project_path: &str,
    block_id: &str,
    value: &serde_json::Value,
) -> Result<HashMap<String, String>, String> {
    let source_root = resolve_project_path(source_project_path);
    let target_root = resolve_project_path(target_project_path);
    if source_root == target_root {
        return Ok(HashMap::new());
    }

    let source_assets_dir = source_root.join("assets");
    let target_assets_dir = target_root.join("assets");
    let mut refs = HashSet::new();
    collect_json_asset_refs(value, &mut refs);

    let mut replacements = HashMap::new();
    let mut used_targets = HashSet::new();
    for asset_ref in refs {
        if is_external_or_default_asset_ref(&asset_ref) {
            continue;
        }
        let normalized_ref = normalize_scorm_asset_ref(&asset_ref);
        let source_path = source_assets_dir.join(&normalized_ref);
        if !source_path.exists() {
            continue;
        }
        let file_name = source_path
            .file_name()
            .and_then(|value| value.to_str())
            .map(sanitize_filename)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| format!("asset-{}", compact_timestamp()));
        let mut target_ref = format!("activity-paste/{}/{}", block_id, file_name);
        let mut suffix = 2;
        while used_targets.contains(&target_ref) || target_assets_dir.join(&target_ref).exists() {
            let stem = Path::new(&file_name)
                .file_stem()
                .and_then(|value| value.to_str())
                .unwrap_or("asset");
            let extension = Path::new(&file_name)
                .extension()
                .and_then(|value| value.to_str())
                .map(|value| format!(".{}", value))
                .unwrap_or_default();
            target_ref = format!(
                "activity-paste/{}/{}-{}{}",
                block_id, stem, suffix, extension
            );
            suffix += 1;
        }
        let target_path = target_assets_dir.join(&target_ref);
        if let Some(parent) = target_path.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::copy(&source_path, &target_path).map_err(|err| err.to_string())?;
        used_targets.insert(target_ref.clone());
        replacements.insert(asset_ref, target_ref.clone());
        replacements.insert(normalized_ref, target_ref);
    }
    Ok(replacements)
}

fn prepare_pasted_activity_block(
    source_project_path: &str,
    target_project_path: &str,
    project: &PaideiaProject,
    block: PaideiaBlock,
) -> Result<PaideiaBlock, String> {
    let next_block_id = next_available_block_id(project);
    let mut value = serde_json::to_value(&block).map_err(|err| err.to_string())?;
    let asset_replacements = copy_pasted_activity_assets(
        source_project_path,
        target_project_path,
        &next_block_id,
        &value,
    )?;
    replace_json_strings(&mut value, &asset_replacements);

    let mut ids = Vec::new();
    collect_json_ids(&value, &mut ids);
    collect_html_attribute_values(&value, "data-paideia-bookmark-id", &mut ids);
    collect_html_attribute_values(&value, "data-paideia-reference-id", &mut ids);
    let stamp = compact_timestamp();
    let mut id_replacements = HashMap::new();
    for (index, id) in ids.into_iter().enumerate() {
        id_replacements.entry(id).or_insert_with(|| {
            if index == 0 {
                next_block_id.clone()
            } else {
                format!("paste_{}_{}", stamp, index + 1)
            }
        });
    }
    id_replacements.insert(block.id.clone(), next_block_id.clone());
    replace_json_strings(&mut value, &id_replacements);

    let mut pasted =
        serde_json::from_value::<PaideiaBlock>(value).map_err(|err| err.to_string())?;
    pasted.id = next_block_id.clone();
    pasted.tracking_key = format!("{}-{}", pasted.block_type, next_block_id);
    pasted.family = None;
    pasted.variant = None;
    pasted.source_format = None;
    pasted.source_block_type = None;
    pasted.source_raw_html = None;
    Ok(pasted)
}

#[tauri::command]
pub fn paste_activity_block(
    source_project_path: String,
    source_project_id: String,
    target_project_path: String,
    target_project_id: String,
    target_page_id: String,
    target_index: usize,
    block: PaideiaBlock,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&target_project_path)?;
    if project.id != target_project_id {
        return Err("La leçon de destination ne correspond pas au projet attendu. Collage annulé."
            .to_string());
    }
    let source_project = load_project_from_path(&source_project_path)?;
    if source_project.id != source_project_id {
        return Err("La leçon source ne correspond pas au projet copié. Collage annulé."
            .to_string());
    }
    let pasted_block =
        prepare_pasted_activity_block(&source_project_path, &target_project_path, &project, block)?;
    let pasted_block_id = pasted_block.id.clone();

    let page = project
        .course
        .modules
        .iter_mut()
        .flat_map(|module| module.chapters.iter_mut())
        .flat_map(|chapter| chapter.pages.iter_mut())
        .find(|page| page.id == target_page_id)
        .ok_or_else(|| "Target page not found".to_string())?;

    let insertion_index = target_index.min(page.blocks.len());
    page.blocks.insert(insertion_index, pasted_block.clone());
    touch_project(&mut project);
    save_project_to_path(&target_project_path, &project)?;

    append_standard_event(
        &target_project_path,
        &project,
        "block",
        &pasted_block_id,
        "block.pasted",
        "Activité collée depuis le tampon PAIDEIA",
        &format!("content/blocks/{}.json", pasted_block_id),
        serde_json::json!({
            "pageId": target_page_id,
            "targetIndex": insertion_index,
            "sourceProjectPath": source_project_path
        }),
        serde_json::json!({ "before": null, "after": pasted_block }),
    )?;

    load_workspace_state_from_path(&target_project_path)
}

fn chapter_asset_refs(chapter: &PaideiaChapter) -> Result<Vec<String>, String> {
    let value = serde_json::to_value(chapter).map_err(|err| err.to_string())?;
    let mut refs = HashSet::new();
    collect_json_asset_refs(&value, &mut refs);
    let mut refs = refs
        .into_iter()
        .filter(|asset_ref| !is_external_or_default_asset_ref(asset_ref))
        .map(|asset_ref| normalize_scorm_asset_ref(&asset_ref))
        .filter(|asset_ref| !asset_ref.is_empty())
        .collect::<Vec<_>>();
    refs.sort();
    refs.dedup();
    Ok(refs)
}

#[tauri::command]
pub fn inspect_chapter_asset_duplicates(
    source_project_path: String,
    target_project_path: String,
    chapter: PaideiaChapter,
) -> Result<Vec<ChapterAssetDuplicate>, String> {
    let source_root = resolve_project_path(&source_project_path);
    let target_root = resolve_project_path(&target_project_path);
    if source_root == target_root {
        return Ok(Vec::new());
    }

    let source_assets_dir = source_root.join("assets");
    let mut duplicates = Vec::new();
    for asset_ref in chapter_asset_refs(&chapter)? {
        let source_path = resolve_project_asset_ref(&source_assets_dir, &asset_ref)?
            .ok_or_else(|| format!("Média source introuvable : {asset_ref}"))?;
        let metadata = fs::metadata(&source_path).map_err(|err| err.to_string())?;
        if !metadata.is_file() {
            continue;
        }
        let source_file_name = source_path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(&asset_ref)
            .to_string();
        let mut reader =
            BufReader::new(fs::File::open(&source_path).map_err(|err| err.to_string())?);
        if let Some(existing) = find_project_asset_duplicate_from_reader(
            &target_project_path,
            &source_file_name,
            metadata.len(),
            &mut reader,
        )? {
            duplicates.push(ChapterAssetDuplicate {
                source_asset_ref: asset_ref,
                source_file_name,
                existing_asset_ref: existing.asset_ref,
                existing_file_name: existing.file_name,
                size_bytes: existing.size_bytes,
            });
        }
    }
    Ok(duplicates)
}

fn validate_chapter_asset_reuse(
    source_assets_dir: &Path,
    target_assets_dir: &Path,
    source_asset_ref: &str,
    target_asset_ref: &str,
) -> Result<(), String> {
    let source_path = resolve_project_asset_ref(source_assets_dir, source_asset_ref)?
        .ok_or_else(|| format!("Média source introuvable : {source_asset_ref}"))?;
    let target_path = resolve_project_asset_ref(target_assets_dir, target_asset_ref)?
        .ok_or_else(|| format!("Média cible introuvable : {target_asset_ref}"))?;
    let source_metadata = fs::metadata(&source_path).map_err(|err| err.to_string())?;
    let target_metadata = fs::metadata(&target_path).map_err(|err| err.to_string())?;
    if source_metadata.len() != target_metadata.len() {
        return Err(
            "Le média existant sélectionné ne correspond plus au média source.".to_string(),
        );
    }
    let mut source_reader =
        BufReader::new(fs::File::open(source_path).map_err(|err| err.to_string())?);
    let mut target_reader =
        BufReader::new(fs::File::open(target_path).map_err(|err| err.to_string())?);
    if !readers_are_identical(&mut source_reader, &mut target_reader)? {
        return Err(
            "Le média existant sélectionné ne correspond plus au média source.".to_string(),
        );
    }
    Ok(())
}

fn copy_pasted_chapter_assets(
    source_project_path: &str,
    target_project_path: &str,
    chapter_id: &str,
    chapter: &PaideiaChapter,
    asset_reuse: &[ChapterAssetReuse],
) -> Result<(HashMap<String, String>, Vec<PathBuf>), String> {
    let source_root = resolve_project_path(source_project_path);
    let target_root = resolve_project_path(target_project_path);
    if source_root == target_root {
        return Ok((HashMap::new(), Vec::new()));
    }

    let source_assets_dir = source_root.join("assets");
    let target_assets_dir = target_root.join("assets");
    let refs = chapter_asset_refs(chapter)?;
    let available_refs = refs.iter().cloned().collect::<HashSet<_>>();
    let mut reuse_by_source = HashMap::new();
    for choice in asset_reuse {
        let source_ref = normalize_scorm_asset_ref(&choice.source_asset_ref);
        let target_ref = normalize_scorm_asset_ref(&choice.target_asset_ref);
        if !available_refs.contains(&source_ref) {
            return Err(format!(
                "Référence de média étrangère au chapitre : {source_ref}"
            ));
        }
        validate_chapter_asset_reuse(
            &source_assets_dir,
            &target_assets_dir,
            &source_ref,
            &target_ref,
        )?;
        reuse_by_source.insert(source_ref, target_ref);
    }

    // Resolve every source before writing anything so a missing or unsafe media
    // reference cannot leave a partially copied chapter asset set behind.
    let mut source_paths = HashMap::new();
    for asset_ref in &refs {
        if reuse_by_source.contains_key(asset_ref) {
            continue;
        }
        let source_path = resolve_project_asset_ref(&source_assets_dir, asset_ref)?
            .ok_or_else(|| format!("Média source introuvable : {asset_ref}"))?;
        source_paths.insert(asset_ref.clone(), source_path);
    }
    if !source_paths.is_empty() {
        fs::create_dir_all(target_assets_dir.join("chapter-paste").join(chapter_id))
            .map_err(|err| err.to_string())?;
    }

    let mut replacements = HashMap::new();
    let mut copied_paths = Vec::new();
    let mut used_targets = HashSet::new();
    for asset_ref in refs {
        if let Some(target_ref) = reuse_by_source.get(&asset_ref) {
            replacements.insert(asset_ref, target_ref.clone());
            continue;
        }
        let source_path = source_paths
            .get(&asset_ref)
            .ok_or_else(|| format!("Média source non préparé : {asset_ref}"))?;
        let file_name = source_path
            .file_name()
            .and_then(|value| value.to_str())
            .map(sanitize_filename)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| format!("asset-{}", compact_timestamp()));
        let mut target_ref = format!("chapter-paste/{chapter_id}/{file_name}");
        let mut suffix = 2;
        while used_targets.contains(&target_ref) || target_assets_dir.join(&target_ref).exists() {
            let stem = Path::new(&file_name)
                .file_stem()
                .and_then(|value| value.to_str())
                .unwrap_or("asset");
            let extension = Path::new(&file_name)
                .extension()
                .and_then(|value| value.to_str())
                .map(|value| format!(".{value}"))
                .unwrap_or_default();
            target_ref = format!("chapter-paste/{chapter_id}/{stem}-{suffix}{extension}");
            suffix += 1;
        }
        let target_path = target_assets_dir.join(&target_ref);
        if let Err(error) = fs::copy(&source_path, &target_path) {
            for copied_path in copied_paths.iter().rev() {
                let _ = fs::remove_file(copied_path);
            }
            return Err(error.to_string());
        }
        used_targets.insert(target_ref.clone());
        replacements.insert(asset_ref, target_ref);
        copied_paths.push(target_path);
    }
    Ok((replacements, copied_paths))
}

fn asset_directories_are_identical(left: &Path, right: &Path) -> Result<bool, String> {
    let mut left_files = Vec::new();
    let mut right_files = Vec::new();
    collect_asset_files(left, &mut left_files)?;
    collect_asset_files(right, &mut right_files)?;
    let relative_files = |root: &Path, files: Vec<PathBuf>| -> Result<Vec<PathBuf>, String> {
        let mut relative = files
            .into_iter()
            .map(|path| {
                path.strip_prefix(root)
                    .map(Path::to_path_buf)
                    .map_err(|error| error.to_string())
            })
            .collect::<Result<Vec<_>, _>>()?;
        relative.sort();
        Ok(relative)
    };
    let left_relative = relative_files(left, left_files)?;
    let right_relative = relative_files(right, right_files)?;
    if left_relative != right_relative {
        return Ok(false);
    }
    for relative in left_relative {
        let mut left_reader = BufReader::new(
            fs::File::open(left.join(&relative)).map_err(|error| error.to_string())?,
        );
        let mut right_reader = BufReader::new(
            fs::File::open(right.join(&relative)).map_err(|error| error.to_string())?,
        );
        if !readers_are_identical(&mut left_reader, &mut right_reader)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn copy_pasted_chapter_fonts(
    source_project_path: &str,
    target_project_path: &str,
    chapter_id: &str,
    chapter: &PaideiaChapter,
) -> Result<(HashMap<String, String>, Vec<PathBuf>), String> {
    let source_root = resolve_project_path(source_project_path);
    let target_root = resolve_project_path(target_project_path);
    if source_root == target_root {
        return Ok((HashMap::new(), Vec::new()));
    }
    let value = serde_json::to_value(chapter).map_err(|error| error.to_string())?;
    let mut font_ids = Vec::new();
    collect_html_attribute_values(&value, "data-paideia-font-id", &mut font_ids);
    let mut font_ids = font_ids
        .into_iter()
        .map(|id| sanitize_filename(id.trim()))
        .filter(|id| id.starts_with("rich-") && !id.is_empty())
        .collect::<Vec<_>>();
    font_ids.sort();
    font_ids.dedup();

    let source_fonts = source_root.join("assets/fonts");
    let target_fonts = target_root.join("assets/fonts");
    let mut replacements = HashMap::new();
    let mut copied_directories = Vec::new();
    for source_id in font_ids {
        let source_directory = source_fonts.join(&source_id);
        if !source_directory.is_dir() {
            return Err(format!("Police RichText source introuvable : {source_id}"));
        }
        let mut target_id = source_id.clone();
        let mut target_directory = target_fonts.join(&target_id);
        if target_directory.exists()
            && !asset_directories_are_identical(&source_directory, &target_directory)?
        {
            let stem = format!("{source_id}-chapter-{chapter_id}");
            target_id = stem.clone();
            let mut suffix = 2;
            while target_fonts.join(&target_id).exists() {
                target_id = format!("{stem}-{suffix}");
                suffix += 1;
            }
            target_directory = target_fonts.join(&target_id);
        }
        if !target_directory.exists() {
            if let Err(error) = copy_dir_contents(&source_directory, &target_directory) {
                let _ = fs::remove_dir_all(&target_directory);
                for copied in copied_directories.iter().rev() {
                    let _ = fs::remove_dir_all(copied);
                }
                return Err(error);
            }
            copied_directories.push(target_directory);
        }
        if target_id != source_id {
            replacements.insert(source_id, target_id);
        }
    }
    Ok((replacements, copied_directories))
}

fn remove_pasted_chapter_paths(paths: &[PathBuf]) {
    for path in paths.iter().rev() {
        if path.is_dir() {
            let _ = fs::remove_dir_all(path);
        } else {
            let _ = fs::remove_file(path);
        }
    }
}

fn next_numbered_id_in_set(prefix: &str, used_ids: &mut HashSet<String>) -> String {
    let next = next_numbered_id(prefix, used_ids.iter().map(String::as_str));
    used_ids.insert(next.clone());
    next
}

fn next_short_id_in_set(used_ids: &mut HashSet<String>) -> String {
    loop {
        let candidate = new_block_id_candidate();
        if used_ids.insert(candidate.clone()) {
            return candidate;
        }
    }
}

fn prepare_pasted_chapter(
    project: &PaideiaProject,
    chapter: &PaideiaChapter,
    asset_replacements: &HashMap<String, String>,
) -> Result<PaideiaChapter, String> {
    let target_value = serde_json::to_value(project).map_err(|err| err.to_string())?;
    let mut used_ids = Vec::new();
    collect_json_ids(&target_value, &mut used_ids);
    collect_html_attribute_values(&target_value, "data-paideia-bookmark-id", &mut used_ids);
    collect_html_attribute_values(&target_value, "data-paideia-reference-id", &mut used_ids);
    let mut used_ids = used_ids.into_iter().collect::<HashSet<_>>();
    let mut replacements = HashMap::new();
    replacements.insert(
        chapter.id.clone(),
        next_numbered_id_in_set("chapter", &mut used_ids),
    );
    for page in &chapter.pages {
        replacements
            .entry(page.id.clone())
            .or_insert_with(|| next_numbered_id_in_set("page", &mut used_ids));
        for block in &page.blocks {
            replacements
                .entry(block.id.clone())
                .or_insert_with(|| next_short_id_in_set(&mut used_ids));
        }
    }

    let mut value = serde_json::to_value(chapter).map_err(|err| err.to_string())?;
    replace_json_strings(&mut value, asset_replacements);
    let mut source_ids = Vec::new();
    collect_json_ids(&value, &mut source_ids);
    collect_html_attribute_values(&value, "data-paideia-bookmark-id", &mut source_ids);
    collect_html_attribute_values(&value, "data-paideia-reference-id", &mut source_ids);
    for source_id in source_ids {
        replacements
            .entry(source_id)
            .or_insert_with(|| next_short_id_in_set(&mut used_ids));
    }
    replace_json_strings(&mut value, &replacements);

    let mut pasted =
        serde_json::from_value::<PaideiaChapter>(value).map_err(|err| err.to_string())?;
    pasted.id = replacements
        .get(&chapter.id)
        .cloned()
        .ok_or_else(|| "Impossible de générer l’identifiant du chapitre.".to_string())?;
    for (source_page, pasted_page) in chapter.pages.iter().zip(pasted.pages.iter_mut()) {
        pasted_page.id = replacements
            .get(&source_page.id)
            .cloned()
            .ok_or_else(|| "Impossible de générer l’identifiant d’une page.".to_string())?;
        for (source_block, pasted_block) in
            source_page.blocks.iter().zip(pasted_page.blocks.iter_mut())
        {
            pasted_block.id = replacements
                .get(&source_block.id)
                .cloned()
                .ok_or_else(|| "Impossible de générer l’identifiant d’une activité.".to_string())?;
            pasted_block.tracking_key = format!("{}-{}", pasted_block.block_type, pasted_block.id);
            pasted_block.family = None;
            pasted_block.variant = None;
            pasted_block.source_format = None;
            pasted_block.source_block_type = None;
            pasted_block.source_raw_html = None;
        }
    }
    Ok(pasted)
}

#[tauri::command]
pub fn paste_chapter(
    source_project_path: String,
    source_project_id: String,
    target_project_path: String,
    target_project_id: String,
    target_module_id: String,
    target_index: usize,
    chapter: PaideiaChapter,
    asset_reuse: Vec<ChapterAssetReuse>,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&target_project_path)?;
    if project.id != target_project_id {
        return Err("La leçon de destination ne correspond pas au projet attendu. Collage annulé."
            .to_string());
    }
    let source_project = load_project_from_path(&source_project_path)?;
    if source_project.id != source_project_id {
        return Err("La leçon source ne correspond pas au projet copié. Collage annulé."
            .to_string());
    }
    if !project
        .course
        .modules
        .iter()
        .any(|module| module.id == target_module_id)
    {
        return Err("Target module not found".to_string());
    }
    let next_chapter_id = next_available_chapter_id(&project);
    let (mut asset_replacements, mut copied_paths) = copy_pasted_chapter_assets(
        &source_project_path,
        &target_project_path,
        &next_chapter_id,
        &chapter,
        &asset_reuse,
    )?;
    let (font_replacements, copied_font_directories) = match copy_pasted_chapter_fonts(
        &source_project_path,
        &target_project_path,
        &next_chapter_id,
        &chapter,
    ) {
        Ok(result) => result,
        Err(error) => {
            remove_pasted_chapter_paths(&copied_paths);
            return Err(error);
        }
    };
    asset_replacements.extend(font_replacements);
    copied_paths.extend(copied_font_directories);
    let mut pasted_chapter = match prepare_pasted_chapter(&project, &chapter, &asset_replacements) {
        Ok(chapter) => chapter,
        Err(error) => {
            remove_pasted_chapter_paths(&copied_paths);
            return Err(error);
        }
    };
    let pasted_chapter_id = pasted_chapter.id.clone();

    let insertion_index = {
        let module = project
            .course
            .modules
            .iter_mut()
            .find(|module| module.id == target_module_id)
            .ok_or_else(|| "Target module not found".to_string())?;
        let existing_titles = module
            .chapters
            .iter()
            .map(|chapter| chapter.title.clone())
            .collect::<HashSet<_>>();
        pasted_chapter.title = next_project_title(&pasted_chapter.title, &existing_titles);
        let insertion_index = target_index.min(module.chapters.len());
        module
            .chapters
            .insert(insertion_index, pasted_chapter.clone());
        insertion_index
    };

    touch_project(&mut project);
    if let Err(error) = save_project_to_path(&target_project_path, &project) {
        remove_pasted_chapter_paths(&copied_paths);
        return Err(error);
    }

    append_standard_event(
        &target_project_path,
        &project,
        "chapter",
        &pasted_chapter_id,
        "chapter.pasted",
        "Chapitre collé depuis le tampon PAIDEIA",
        &format!("content/chapters/{pasted_chapter_id}.json"),
        serde_json::json!({
            "moduleId": target_module_id,
            "targetIndex": insertion_index,
            "sourceProjectPath": source_project_path
        }),
        serde_json::json!({ "before": null, "after": pasted_chapter }),
    )?;

    load_workspace_state_from_path(&target_project_path)
}

#[tauri::command]
pub fn update_block(
    project_path: String,
    page_id: String,
    block_id: String,
    block_type: String,
    title: String,
    summary: String,
    content_html: Option<String>,
    quote_author_html: Option<String>,
    quote_show_author: Option<bool>,
    media_layout: Option<String>,
    image_size: Option<String>,
    content_width: Option<String>,
    content_align: Option<String>,
    media_gap: Option<String>,
    vertical_align: Option<String>,
    image_rounded: Option<bool>,
    media_file_name: Option<String>,
    image_crop: Option<crate::models::ImageCrop>,
    image_accessibility: Option<crate::models::ImageAccessibility>,
    image_annotation_state_ref: Option<String>,
    image_annotation_source_asset_ref: Option<String>,
    video_caption_color: Option<String>,
    video_caption_background_enabled: Option<bool>,
    video_caption_outline: Option<String>,
    video_subtitle_original_ref: Option<String>,
    video_allow_fullscreen: Option<bool>,
    audio_autoplay_next: Option<bool>,
    audio_allow_download: Option<bool>,
    image360_initial_yaw: Option<f64>,
    image360_initial_pitch: Option<f64>,
    image360_zoom_enabled: Option<bool>,
    image360_full_width: Option<bool>,
    image360_allow_fullscreen: Option<bool>,
    header_background_color: Option<String>,
    header_text_color: Option<String>,
    header_text_outline: Option<String>,
    header_text_outline_color: Option<String>,
    header_height: Option<String>,
    header_image_position_y: Option<f64>,
    button_background_color: Option<String>,
    button_text_color: Option<String>,
    panel_background_color: Option<String>,
    panel_border_color: Option<String>,
    panel_border_width: Option<String>,
    panel_border_style: Option<String>,
    panel_padding: Option<String>,
    panel_rounded: Option<bool>,
    panel_shadow: Option<bool>,
    note_icon: Option<String>,
    note_show_icon: Option<bool>,
    note_icon_color: Option<String>,
    note_icon_matches_border: Option<bool>,
    flip_card_front_background_color: Option<String>,
    flip_card_back_background_color: Option<String>,
    flip_card_front_border_color: Option<String>,
    flip_card_back_border_color: Option<String>,
    slides_activity_background_color: Option<String>,
    slides_activity_border_color: Option<String>,
    slides_activity_border_width: Option<String>,
    slides_activity_border_style: Option<String>,
    slides_activity_rounded: Option<bool>,
    slides_activity_shadow: Option<bool>,
    section_background_color: Option<String>,
    section_background_image_ref: Option<String>,
    section_background_opacity: Option<f64>,
    section_background_overlay_dark: Option<bool>,
    section_background_blur: Option<f64>,
    section_background_position_y: Option<f64>,
    section_background_rounded: Option<bool>,
    section_background_wide: Option<bool>,
    section_background_height: Option<String>,
    divider_color: Option<String>,
    divider_width: Option<String>,
    divider_style: Option<String>,
    marker_scheme: Option<String>,
    marker_type: Option<String>,
    marker_text_color: Option<String>,
    point_of_interest_markers: Option<Vec<crate::models::PointOfInterestMarker>>,
    image360_hotspots: Option<Vec<crate::models::Image360Hotspot>>,
    activity_items: Option<Vec<crate::models::ActivityItem>>,
    situational_dialogue_characters: Option<Vec<SituationalDialogueCharacter>>,
    attachment_files: Option<Vec<AttachmentFile>>,
    quiz: Option<QuizActivityData>,
    find_elements: Option<crate::models::FindElementsActivityData>,
    complete: Option<crate::models::CompleteActivityData>,
    card_sort: Option<crate::models::CardSortActivityData>,
    matching: Option<crate::models::MatchingActivityData>,
    marker_popup_width: Option<String>,
    marker_popup_height: Option<String>,
    padding_offset: Option<i32>,
    asset_refs: Option<Vec<String>>,
    subtitle_refs: Option<Vec<String>>,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let page = project
        .course
        .modules
        .iter_mut()
        .flat_map(|module| module.chapters.iter_mut())
        .flat_map(|chapter| chapter.pages.iter_mut())
        .find(|page| page.id == page_id)
        .ok_or_else(|| "Target page not found".to_string())?;

    let block = page
        .blocks
        .iter_mut()
        .find(|block| block.id == block_id)
        .ok_or_else(|| "Target block not found".to_string())?;

    let before = block.clone();
    block.block_type = block_type.clone();
    block.title = title.clone();
    block.summary = summary.clone();
    block.content_html = content_html.clone();
    if let Some(value) = quote_author_html {
        block.quote_author_html = optional_html(Some(value.as_str())).map(str::to_string);
    }
    block.quote_show_author = quote_show_author;
    block.media_layout = media_layout.or_else(|| block.media_layout.clone());
    block.image_size = image_size.or_else(|| block.image_size.clone());
    block.content_width = content_width.or_else(|| block.content_width.clone());
    block.content_align = content_align.or_else(|| block.content_align.clone());
    block.media_gap = media_gap.or_else(|| block.media_gap.clone());
    block.vertical_align = vertical_align.or_else(|| block.vertical_align.clone());
    block.image_rounded = image_rounded.or(block.image_rounded);
    block.media_file_name = media_file_name.or_else(|| block.media_file_name.clone());
    block.image_crop = image_crop.or_else(|| block.image_crop.clone());
    block.image_accessibility = image_accessibility;
    block.image_annotation_state_ref =
        image_annotation_state_ref.or_else(|| block.image_annotation_state_ref.clone());
    block.image_annotation_source_asset_ref = image_annotation_source_asset_ref
        .or_else(|| block.image_annotation_source_asset_ref.clone());
    block.video_caption_color = video_caption_color.or_else(|| block.video_caption_color.clone());
    block.video_caption_background_enabled =
        video_caption_background_enabled.or(block.video_caption_background_enabled);
    block.video_caption_outline =
        video_caption_outline.or_else(|| block.video_caption_outline.clone());
    block.video_allow_fullscreen = video_allow_fullscreen.or(block.video_allow_fullscreen);
    block.audio_autoplay_next = audio_autoplay_next.or(block.audio_autoplay_next);
    block.audio_allow_download = audio_allow_download.or(block.audio_allow_download);
    block.image360_initial_yaw = image360_initial_yaw.or(block.image360_initial_yaw);
    block.image360_initial_pitch = image360_initial_pitch.or(block.image360_initial_pitch);
    block.image360_zoom_enabled = image360_zoom_enabled.or(block.image360_zoom_enabled);
    block.image360_full_width = image360_full_width.or(block.image360_full_width);
    block.image360_allow_fullscreen = image360_allow_fullscreen.or(block.image360_allow_fullscreen);
    block.header_background_color =
        header_background_color.or_else(|| block.header_background_color.clone());
    block.header_text_color = header_text_color.or_else(|| block.header_text_color.clone());
    block.header_text_outline = header_text_outline.or_else(|| block.header_text_outline.clone());
    block.header_text_outline_color =
        header_text_outline_color.or_else(|| block.header_text_outline_color.clone());
    block.header_height = header_height.or_else(|| block.header_height.clone());
    block.header_image_position_y = header_image_position_y.or(block.header_image_position_y);
    block.button_background_color =
        button_background_color.or_else(|| block.button_background_color.clone());
    block.button_text_color = button_text_color.or_else(|| block.button_text_color.clone());
    block.panel_background_color =
        panel_background_color.or_else(|| block.panel_background_color.clone());
    block.panel_border_color = panel_border_color.or_else(|| block.panel_border_color.clone());
    block.panel_border_width = panel_border_width.or_else(|| block.panel_border_width.clone());
    block.panel_border_style = panel_border_style.or_else(|| block.panel_border_style.clone());
    block.panel_padding = panel_padding.or_else(|| block.panel_padding.clone());
    block.panel_rounded = panel_rounded.or(block.panel_rounded);
    block.panel_shadow = panel_shadow.or(block.panel_shadow);
    if block_type == "note" {
        block.note_icon = Some(
            normalized_note_icon(note_icon.as_deref().or(block.note_icon.as_deref())).to_string(),
        );
        block.note_show_icon = Some(note_show_icon.or(block.note_show_icon).unwrap_or(true));
        block.note_icon_color = note_icon_color.or_else(|| block.note_icon_color.clone());
        block.note_icon_matches_border = Some(
            note_icon_matches_border
                .or(block.note_icon_matches_border)
                .unwrap_or(true),
        );
    } else {
        block.note_icon = note_icon.or_else(|| block.note_icon.clone());
        block.note_show_icon = note_show_icon.or(block.note_show_icon);
        block.note_icon_color = note_icon_color.or_else(|| block.note_icon_color.clone());
        block.note_icon_matches_border =
            note_icon_matches_border.or(block.note_icon_matches_border);
    }
    block.flip_card_front_background_color =
        flip_card_front_background_color.or_else(|| block.flip_card_front_background_color.clone());
    block.flip_card_back_background_color =
        flip_card_back_background_color.or_else(|| block.flip_card_back_background_color.clone());
    block.flip_card_front_border_color =
        flip_card_front_border_color.or_else(|| block.flip_card_front_border_color.clone());
    block.flip_card_back_border_color =
        flip_card_back_border_color.or_else(|| block.flip_card_back_border_color.clone());
    block.slides_activity_background_color =
        slides_activity_background_color.or_else(|| block.slides_activity_background_color.clone());
    block.slides_activity_border_color =
        slides_activity_border_color.or_else(|| block.slides_activity_border_color.clone());
    block.slides_activity_border_width =
        slides_activity_border_width.or_else(|| block.slides_activity_border_width.clone());
    block.slides_activity_border_style =
        slides_activity_border_style.or_else(|| block.slides_activity_border_style.clone());
    block.slides_activity_rounded = slides_activity_rounded.or(block.slides_activity_rounded);
    block.slides_activity_shadow = slides_activity_shadow.or(block.slides_activity_shadow);
    apply_section_background_update(
        block,
        &block_type,
        section_background_color,
        section_background_image_ref,
        section_background_opacity,
        section_background_overlay_dark,
        section_background_blur,
        section_background_position_y,
        section_background_rounded,
        section_background_wide,
        section_background_height,
    );
    block.divider_color = divider_color.or_else(|| block.divider_color.clone());
    block.divider_width = divider_width.or_else(|| block.divider_width.clone());
    block.divider_style = divider_style.or_else(|| block.divider_style.clone());
    block.marker_scheme = marker_scheme.or_else(|| block.marker_scheme.clone());
    block.marker_type = marker_type.or_else(|| block.marker_type.clone());
    block.marker_text_color = marker_text_color.or_else(|| block.marker_text_color.clone());
    if block_type != "point-of-interest" {
        block.point_of_interest_markers.clear();
    } else if let Some(markers) = point_of_interest_markers {
        block.point_of_interest_markers = markers;
    }
    if let Some(hotspots) = image360_hotspots {
        block.image360_hotspots = hotspots;
    }
    if let Some(mut items) = activity_items {
        if block_type == "image-grid" {
            items.truncate(4);
        }
        block.activity_items = items;
    }
    if let Some(characters) = situational_dialogue_characters {
        block.situational_dialogue_characters = characters;
    }
    if let Some(files) = attachment_files {
        block.attachment_files = files;
    }
    if matches!(block_type.as_str(), "quiz" | "question-multiple" | "question-unique" | "question-true-false" | "question-random") {
        if let Some(value) = quiz {
            block.quiz = Some(value);
        }
    } else {
        block.quiz = None;
    }
    if block_type == "find-elements" {
        if let Some(value) = find_elements {
            block.find_elements = Some(value);
        }
    } else {
        block.find_elements = None;
    }
    if block_type == "complete" {
        block.complete = complete;
    } else {
        block.complete = None;
    }
    if block_type == "card-sort" {
        block.card_sort = card_sort;
    } else {
        block.card_sort = None;
    }
    if block_type == "matching" {
        block.matching = matching;
    } else {
        block.matching = None;
    }
    block.marker_popup_width = if block_type == "point-of-interest" {
        marker_popup_width.or_else(|| block.marker_popup_width.clone())
    } else {
        None
    };
    block.marker_popup_height = if block_type == "point-of-interest" {
        marker_popup_height.or_else(|| block.marker_popup_height.clone())
    } else {
        None
    };
    block.padding_offset = padding_offset.or(block.padding_offset);
    // The HTML package import owns these references. An editor form opened before
    // an import may still submit the previous package's refs on Save.
    if block_type != "html-custom" {
        if let Some(refs) = asset_refs {
            if block_type == "media"
                && block
                    .video_optimized_asset_ref
                    .as_ref()
                    .is_some_and(|optimized_ref| !refs.contains(optimized_ref))
            {
                block.video_original_asset_ref = None;
                block.video_optimized_asset_ref = None;
                block.video_optimization_profile = None;
            }
            block.asset_refs = refs;
        }
    }
    if let Some(refs) = subtitle_refs {
        block.subtitle_refs = refs;
        block.video_subtitle_original_ref = video_subtitle_original_ref;
    } else if video_subtitle_original_ref.is_some() {
        block.video_subtitle_original_ref = video_subtitle_original_ref;
    }
    block.tracking_key = format!("{}-{}", block_type, block.id);
    block.source_format = None;
    block.source_block_type = None;
    block.source_raw_html = None;
    let after = block.clone();

    touch_project(&mut project);
    let project = save_project_for_workspace(&project_path, &project)?;
    prune_orphaned_project_assets(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "block",
        &block_id,
        "block.updated",
        "ActivitÃ© modifiÃ©e",
        &format!("content/blocks/{}.json", block_id),
        serde_json::json!({ "pageId": page_id, "contentHtml": content_html }),
        serde_json::json!({ "before": before, "after": after }),
    )?;

    workspace_state_from_saved_project(&project_path, project)
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DesignerBlockChange {
    #[serde(rename = "pageId")]
    pub page_id: String,
    #[serde(rename = "blockId")]
    pub block_id: String,
    pub property: String,
    pub value: String,
    #[serde(default)]
    pub unset: bool,
}

fn designer_rich_html_key(key: &str) -> bool {
    key.ends_with("Html") && !matches!(key, "sourceRawHtml" | "transcriptHtml")
}

fn validate_designer_rich_text_block_change(
    current: &serde_json::Value,
    candidate: &serde_json::Value,
    key: Option<&str>,
) -> Result<(), String> {
    if key.is_some_and(designer_rich_html_key) {
        if matches!(
            candidate,
            serde_json::Value::String(_) | serde_json::Value::Null
        ) {
            return Ok(());
        }
        return Err("A Rich Text field must remain a string or null".to_string());
    }
    match (current, candidate) {
        (serde_json::Value::Object(left), serde_json::Value::Object(right)) => {
            if left.len() != right.len() || left.keys().any(|item| !right.contains_key(item)) {
                return Err(
                    "The activity structure cannot be changed by a font command".to_string()
                );
            }
            for (child_key, left_value) in left {
                validate_designer_rich_text_block_change(
                    left_value,
                    right
                        .get(child_key)
                        .ok_or_else(|| "Missing activity field".to_string())?,
                    Some(child_key),
                )?;
            }
            Ok(())
        }
        (serde_json::Value::Array(left), serde_json::Value::Array(right)) => {
            if left.len() != right.len() {
                return Err(
                    "The activity structure cannot be changed by a font command".to_string()
                );
            }
            for (left_value, right_value) in left.iter().zip(right) {
                validate_designer_rich_text_block_change(left_value, right_value, None)?;
            }
            Ok(())
        }
        _ if current == candidate => Ok(()),
        _ => Err("Only Rich Text fields may be changed by a font command".to_string()),
    }
}

#[tauri::command]
pub fn apply_designer_block_changes(
    project_path: String,
    changes: Vec<DesignerBlockChange>,
    action_id: String,
    original_command: String,
    undo: bool,
) -> Result<PaideiaWorkspaceState, String> {
    if changes.is_empty() {
        return Err("No designer changes to apply".to_string());
    }

    let mut seen_targets = HashSet::new();
    for change in &changes {
        if !matches!(
            change.property.as_str(),
            "sectionBackgroundHeight"
                | "courseTextColor"
                | "videoCaptionColor"
                | "videoCaptionBackgroundEnabled"
                | "videoCaptionOutline"
                | "videoAllowFullscreen"
                | "textActivityContentHtml"
                | "activityRichTextBlockJson"
                | "paddingOffset"
                | "sectionBackgroundColor"
                | "sectionBackgroundImageRef"
                | "sectionBackgroundOpacity"
                | "sectionBackgroundOverlayDark"
                | "sectionBackgroundBlur"
                | "sectionBackgroundRounded"
                | "sectionBackgroundWide"
                | "panelRounded"
                | "panelBackgroundColor"
                | "panelBorderColor"
                | "panelBorderWidth"
                | "panelBorderStyle"
                | "panelShadow"
                | "activityAccentColor"
                | "matchingLabelBackgroundColor"
                | "matchingLabelRounded"
                | "findElementsImageRounded"
                | "findElementsImageShadow"
                | "slidesActivityBackgroundColor"
                | "slidesActivityRounded"
                | "slidesActivityShadow"
                | "cardSortCardRounded"
                | "dividerColor"
                | "dividerWidth"
                | "dividerStyle"
                | "markerScheme"
                | "markerType"
                | "markerTextColor"
                | "headerBackgroundColor"
                | "headerTextColor"
                | "headerTextOutline"
                | "headerTextOutlineColor"
                | "contentAlign"
                | "continueButtonBackgroundColor"
                | "continueButtonTextColor"
                | "continueButtonLabel"
        ) {
            return Err(format!(
                "Unsupported designer property: {}",
                change.property
            ));
        }
        if change.unset && change.property == "continueButtonLabel" {
            return Err("The Continue button label cannot be unset".to_string());
        }
        if change.unset {
            if !seen_targets.insert((
                change.page_id.clone(),
                change.block_id.clone(),
                change.property.clone(),
            )) {
                return Err(format!("Duplicate designer target: {}", change.block_id));
            }
            continue;
        }
        if change.property == "sectionBackgroundHeight"
            && !matches!(change.value.as_str(), "minimum" | "medium" | "large")
        {
            return Err(format!("Unsupported activity height: {}", change.value));
        }
        if change.property == "courseTextColor"
            && !regex::Regex::new(r"^#[0-9A-Fa-f]{6}$")
                .unwrap()
                .is_match(&change.value)
        {
            return Err(format!("Unsupported lesson text color: {}", change.value));
        }
        if change.property == "videoCaptionColor"
            && !regex::Regex::new(r"^#[0-9A-Fa-f]{6}$")
                .unwrap()
                .is_match(&change.value)
        {
            return Err(format!("Unsupported caption color: {}", change.value));
        }
        if change.property == "videoCaptionBackgroundEnabled"
            && !matches!(change.value.as_str(), "true" | "false")
        {
            return Err(format!(
                "Unsupported caption background value: {}",
                change.value
            ));
        }
        if change.property == "videoCaptionOutline"
            && !matches!(change.value.as_str(), "none" | "thin" | "thick")
        {
            return Err(format!("Unsupported caption outline: {}", change.value));
        }
        if change.property == "videoAllowFullscreen"
            && !matches!(change.value.as_str(), "true" | "false")
        {
            return Err(format!("Unsupported fullscreen value: {}", change.value));
        }
        if change.property == "paddingOffset" {
            let offset = change
                .value
                .parse::<i32>()
                .map_err(|_| format!("Unsupported activity spacing value: {}", change.value))?;
            if !(-240..=90).contains(&offset) {
                return Err(format!(
                    "Unsupported activity spacing value: {}",
                    change.value
                ));
            }
        }
        if change.property == "textActivityContentHtml" && change.value.len() > 2_000_000 {
            return Err("Text activity content is too large".to_string());
        }
        if change.property == "activityRichTextBlockJson"
            && (change.unset || change.value.len() > 8_000_000)
        {
            return Err("Unsupported Rich Text activity payload".to_string());
        }
        if change.property == "sectionBackgroundColor"
            && !change.value.is_empty()
            && !regex::Regex::new(r"^#[0-9A-Fa-f]{6}$")
                .unwrap()
                .is_match(&change.value)
        {
            return Err(format!(
                "Unsupported activity background color: {}",
                change.value
            ));
        }
        if change.property == "sectionBackgroundImageRef" {
            let invalid_ref = Path::new(&change.value).is_absolute()
                || Path::new(&change.value).components().any(|part| {
                    matches!(
                        part,
                        Component::ParentDir | Component::RootDir | Component::Prefix(_)
                    )
                })
                || (!change.value.is_empty()
                    && !change.value.replace('\\', "/").starts_with("images/"));
            if invalid_ref {
                return Err("Unsupported activity background image reference".to_string());
            }
        }
        if change.property == "sectionBackgroundOpacity" {
            let opacity = change
                .value
                .parse::<f64>()
                .map_err(|_| "Unsupported activity background opacity".to_string())?;
            if !(0.0..=1.0).contains(&opacity) {
                return Err("Unsupported activity background opacity".to_string());
            }
        }
        if change.property == "sectionBackgroundBlur" {
            let blur = change
                .value
                .parse::<f64>()
                .map_err(|_| "Unsupported activity background blur".to_string())?;
            if !(0.0..=30.0).contains(&blur) {
                return Err("Unsupported activity background blur".to_string());
            }
        }
        if matches!(
            change.property.as_str(),
            "sectionBackgroundOverlayDark"
                | "sectionBackgroundRounded"
                | "sectionBackgroundWide"
                | "panelRounded"
                | "panelShadow"
                | "matchingLabelRounded"
                | "findElementsImageRounded"
                | "findElementsImageShadow"
                | "slidesActivityRounded"
                | "slidesActivityShadow"
                | "cardSortCardRounded"
        ) && !matches!(change.value.as_str(), "true" | "false")
        {
            return Err("Unsupported activity background boolean value".to_string());
        }
        if matches!(
            change.property.as_str(),
            "continueButtonBackgroundColor" | "continueButtonTextColor" | "panelBackgroundColor" | "panelBorderColor" | "activityAccentColor" | "dividerColor" | "markerTextColor" | "headerBackgroundColor" | "headerTextColor" | "matchingLabelBackgroundColor" | "slidesActivityBackgroundColor"
        ) && !change.unset
            && !regex::Regex::new(r"^#[0-9A-Fa-f]{6}$")
            .unwrap()
            .is_match(&change.value)
        {
            return Err(format!(
                "Unsupported Continue button color: {}",
                change.value
            ));
        }
        if change.property == "panelBorderWidth" && !change.unset
            && !matches!(change.value.as_str(), "1px" | "2px" | "4px" | "6px")
        {
            return Err(format!("Unsupported activity border width: {}", change.value));
        }
        if change.property == "panelBorderStyle" && !change.unset
            && !matches!(change.value.as_str(), "none" | "solid" | "dashed" | "dotted")
        {
            return Err(format!("Unsupported activity border style: {}", change.value));
        }
        if change.property == "dividerWidth" && !change.unset
            && !matches!(change.value.as_str(), "1px" | "2px" | "4px" | "6px")
        {
            return Err(format!("Unsupported divider width: {}", change.value));
        }
        if change.property == "dividerStyle" && !change.unset
            && !matches!(change.value.as_str(), "none" | "solid" | "dashed" | "dotted")
        {
            return Err(format!("Unsupported divider style: {}", change.value));
        }
        if change.property == "markerScheme" && !change.unset
            && !matches!(change.value.as_str(), "arabic" | "roman" | "alpha")
        {
            return Err(format!("Unsupported marker scheme: {}", change.value));
        }
        if change.property == "markerType" && !change.unset
            && !matches!(change.value.as_str(), "none" | "outline" | "filled")
        {
            return Err(format!("Unsupported marker type: {}", change.value));
        }
        if change.property == "contentAlign" && !change.unset
            && !matches!(change.value.as_str(), "left" | "center" | "right")
        {
            return Err(format!("Unsupported header text position: {}", change.value));
        }
        if change.property == "headerTextOutline" && !change.unset
            && !matches!(change.value.as_str(), "none" | "thin" | "medium" | "thick")
        {
            return Err(format!("Unsupported header text outline: {}", change.value));
        }
        if change.property == "headerTextOutlineColor" && !change.unset
            && !matches!(change.value.as_str(), "light" | "dark")
        {
            return Err(format!("Unsupported header outline color: {}", change.value));
        }
        if change.property == "continueButtonLabel"
            && (change.value.trim().is_empty()
                || change.value.chars().count() > 120
                || change.value.chars().any(char::is_control))
        {
            return Err("Unsupported Continue button label".to_string());
        }
        if !seen_targets.insert((
            change.page_id.clone(),
            change.block_id.clone(),
            change.property.clone(),
        )) {
            return Err(format!("Duplicate designer target: {}", change.block_id));
        }
    }

    let mut project = load_project_from_path(&project_path)?;
    let mut before = Vec::with_capacity(changes.len());

    // Validate the whole transaction before mutating a single block.
    for change in &changes {
        if change.property == "courseTextColor" {
            before.push(serde_json::json!({
                "pageId": change.page_id,
                "blockId": change.block_id,
                "property": change.property,
                "value": project.course_appearance.as_ref()
                    .filter(|appearance| appearance.text_color_mode == "custom")
                    .map(|appearance| appearance.text_color.clone())
                    .unwrap_or_else(|| "#222222".to_string()),
                "unset": project.course_appearance.as_ref()
                    .map(|appearance| appearance.text_color_mode != "custom")
                    .unwrap_or(true)
            }));
            continue;
        }
        let block = project
            .course
            .modules
            .iter()
            .flat_map(|module| module.chapters.iter())
            .flat_map(|chapter| chapter.pages.iter())
            .find(|page| page.id == change.page_id)
            .and_then(|page| page.blocks.iter().find(|block| block.id == change.block_id))
            .ok_or_else(|| format!("Designer target block not found: {}", change.block_id))?;

        if matches!(
            change.property.as_str(),
            "videoCaptionColor"
                | "videoCaptionBackgroundEnabled"
                | "videoCaptionOutline"
                | "videoAllowFullscreen"
        ) && block.block_type != "media"
        {
            return Err(format!(
                "Designer target is not a video activity: {}",
                change.block_id
            ));
        }
        if change.property == "textActivityContentHtml" && block.block_type != "rich-text" {
            return Err(format!(
                "Designer target is not a text activity: {}",
                change.block_id
            ));
        }
        if change.property == "activityRichTextBlockJson" {
            let current_value = serde_json::to_value(block)
                .map_err(|error| format!("Cannot inspect designer target: {}", error))?;
            let candidate_value: serde_json::Value = serde_json::from_str(&change.value)
                .map_err(|error| format!("Invalid Rich Text activity payload: {}", error))?;
            validate_designer_rich_text_block_change(&current_value, &candidate_value, None)?;
            serde_json::from_value::<PaideiaBlock>(candidate_value)
                .map_err(|error| format!("Invalid Rich Text activity: {}", error))?;
        }
        if change.property == "panelRounded"
            && block.block_type != "situational-dialogue"
            && !supports_activity_frame_appearance(&block.block_type, &change.property)
        {
            return Err(format!(
                "Designer panel target is not a situational dialogue: {}",
                change.block_id
            ));
        }
        if matches!(
            change.property.as_str(),
            "panelBackgroundColor" | "panelBorderColor" | "panelBorderWidth" | "panelBorderStyle" | "panelShadow" | "activityAccentColor"
        ) && !supports_activity_frame_appearance(&block.block_type, &change.property)
        {
            return Err(format!(
                "Designer target does not expose this activity appearance property: {}",
                change.block_id
            ));
        }
        if matches!(
            change.property.as_str(),
            "continueButtonBackgroundColor" | "continueButtonTextColor" | "continueButtonLabel"
        ) && block.block_type != "continue" && !(block.block_type == "course-exit" && change.property != "continueButtonLabel")
        {
            return Err(format!(
                "Designer target is not a Continue activity: {}",
                change.block_id
            ));
        }
        if matches!(change.property.as_str(), "dividerColor" | "dividerWidth" | "dividerStyle")
            && !matches!(block.block_type.as_str(), "divider" | "section-marker")
        {
            return Err(format!("Designer target is not a divider: {}", change.block_id));
        }
        if matches!(change.property.as_str(), "markerScheme" | "markerType" | "markerTextColor")
            && block.block_type != "section-marker"
        {
            return Err(format!("Designer target is not a section marker: {}", change.block_id));
        }
        if matches!(change.property.as_str(), "headerBackgroundColor" | "headerTextColor" | "headerTextOutline" | "headerTextOutlineColor" | "contentAlign")
            && block.block_type != "header"
        {
            return Err(format!("Designer target is not a header: {}", change.block_id));
        }
        let expected_special_type = match change.property.as_str() {
            "matchingLabelBackgroundColor" | "matchingLabelRounded" => Some("matching"),
            "findElementsImageRounded" | "findElementsImageShadow" => Some("find-elements"),
            "slidesActivityBackgroundColor" | "slidesActivityRounded" | "slidesActivityShadow" => Some("slides"),
            "cardSortCardRounded" => Some("card-sort"),
            _ => None,
        };
        if let Some(expected_type) = expected_special_type {
            if block.block_type != expected_type {
                return Err(format!("Designer target does not expose this specialized appearance property: {}", change.block_id));
            }
            let data_missing = match expected_type {
                "matching" => block.matching.is_none(),
                "find-elements" => block.find_elements.is_none(),
                "card-sort" => block.card_sort.is_none(),
                _ => false,
            };
            if data_missing {
                return Err(format!("Designer target appearance data is missing: {}", change.block_id));
            }
        }
        if change.property == "sectionBackgroundHeight"
            && block.block_type == "situational-dialogue"
        {
            return Err(format!(
                "Designer target does not expose a background height: {}",
                change.block_id
            ));
        }
        if block.block_type == "image"
            && matches!(
                change.property.as_str(),
                "sectionBackgroundImageRef"
                    | "sectionBackgroundOpacity"
                    | "sectionBackgroundOverlayDark"
                    | "sectionBackgroundBlur"
            )
        {
            return Err(format!(
                "Designer target does not expose a background image: {}",
                change.block_id
            ));
        }
        if matches!(
            change.property.as_str(),
            "sectionBackgroundHeight"
                | "sectionBackgroundColor"
                | "sectionBackgroundImageRef"
                | "sectionBackgroundOpacity"
                | "sectionBackgroundOverlayDark"
                | "sectionBackgroundBlur"
                | "sectionBackgroundRounded"
                | "sectionBackgroundWide"
                | "panelRounded"
        ) && !supports_activity_background(&block.block_type)
            && !(block.block_type == "header" && matches!(change.property.as_str(), "sectionBackgroundOpacity" | "sectionBackgroundOverlayDark" | "sectionBackgroundBlur"))
        {
            return Err(format!(
                "Designer target does not support an activity background: {}",
                change.block_id
            ));
        }

        before.push(serde_json::json!({
            "pageId": change.page_id,
            "blockId": change.block_id,
            "property": change.property,
            "value": match change.property.as_str() {
                "sectionBackgroundHeight" => block.section_background_height.clone().unwrap_or_else(|| "medium".to_string()),
                "videoCaptionColor" => block
                    .video_caption_color
                    .clone()
                    .unwrap_or_else(|| "#FFFFFF".to_string()),
                "videoCaptionBackgroundEnabled" => block.video_caption_background_enabled.unwrap_or(true).to_string(),
                "videoCaptionOutline" => block.video_caption_outline.clone().unwrap_or_else(|| "none".to_string()),
                "videoAllowFullscreen" => block.video_allow_fullscreen.unwrap_or(true).to_string(),
                "textActivityContentHtml" => block.content_html.clone().unwrap_or_default(),
                "activityRichTextBlockJson" => serde_json::to_string(block).map_err(|error| error.to_string())?,
                "paddingOffset" => block.padding_offset.unwrap_or(0).to_string(),
                "sectionBackgroundColor" => block.section_background_color.clone().unwrap_or_default(),
                "sectionBackgroundImageRef" => block.section_background_image_ref.clone().unwrap_or_default(),
                "sectionBackgroundOpacity" => block.section_background_opacity.unwrap_or(1.0).to_string(),
                "sectionBackgroundOverlayDark" => block.section_background_overlay_dark.unwrap_or(true).to_string(),
                "sectionBackgroundBlur" => block.section_background_blur.unwrap_or(0.0).to_string(),
                "sectionBackgroundRounded" => block.section_background_rounded.unwrap_or(true).to_string(),
                "sectionBackgroundWide" => block.section_background_wide.unwrap_or(false).to_string(),
                "panelRounded" => block.panel_rounded.unwrap_or(true).to_string(),
                "panelBackgroundColor" => block.panel_background_color.clone().unwrap_or_default(),
                "panelBorderColor" => block.panel_border_color.clone().unwrap_or_default(),
                "panelBorderWidth" => block.panel_border_width.clone().unwrap_or_default(),
                "panelBorderStyle" => block.panel_border_style.clone().unwrap_or_default(),
                "panelShadow" => block.panel_shadow.unwrap_or(false).to_string(),
                "activityAccentColor" => match block.block_type.as_str() {
                    "audio" | "quote" => block.button_text_color.clone().unwrap_or_default(),
                    "links-resources" => block.button_background_color.clone().unwrap_or_default(),
                    _ => block.panel_border_color.clone().unwrap_or_default(),
                },
                "matchingLabelBackgroundColor" => block.matching.as_ref().map(|data| data.label_appearance.background_color.clone()).unwrap_or_else(|| "#FFFFFF".to_string()),
                "matchingLabelRounded" => block.matching.as_ref().map(|data| data.label_appearance.rounded).unwrap_or(true).to_string(),
                "findElementsImageRounded" => block.find_elements.as_ref().map(|data| data.image_appearance.rounded).unwrap_or(true).to_string(),
                "findElementsImageShadow" => block.find_elements.as_ref().map(|data| data.image_appearance.shadow).unwrap_or(false).to_string(),
                "slidesActivityBackgroundColor" => block.slides_activity_background_color.clone().unwrap_or_else(|| "#ffffff".to_string()),
                "slidesActivityRounded" => block.slides_activity_rounded.unwrap_or(true).to_string(),
                "slidesActivityShadow" => block.slides_activity_shadow.unwrap_or(true).to_string(),
                "cardSortCardRounded" => block.card_sort.as_ref().map(|data| data.card_appearance.rounded).unwrap_or(true).to_string(),
                "dividerColor" => block.divider_color.clone().unwrap_or_else(|| "#123a7a".to_string()),
                "dividerWidth" => block.divider_width.clone().unwrap_or_else(|| "2px".to_string()),
                "dividerStyle" => block.divider_style.clone().unwrap_or_else(|| "solid".to_string()),
                "markerScheme" => block.marker_scheme.clone().unwrap_or_else(|| "arabic".to_string()),
                "markerType" => block.marker_type.clone().unwrap_or_else(|| "outline".to_string()),
                "markerTextColor" => block.marker_text_color.clone().or_else(|| block.divider_color.clone()).unwrap_or_else(|| "#123a7a".to_string()),
                "headerBackgroundColor" => block.header_background_color.clone().unwrap_or_else(|| "#d7eef0".to_string()),
                "headerTextColor" => block.header_text_color.clone().unwrap_or_else(|| "#102752".to_string()),
                "headerTextOutline" => block.header_text_outline.clone().unwrap_or_else(|| "none".to_string()),
                "headerTextOutlineColor" => block.header_text_outline_color.clone().unwrap_or_else(|| "light".to_string()),
                "contentAlign" => block.content_align.clone().unwrap_or_else(|| "left".to_string()),
                "continueButtonBackgroundColor" => block.button_background_color.clone().unwrap_or_else(|| "#123a7a".to_string()),
                "continueButtonTextColor" => block.button_text_color.clone().unwrap_or_else(|| "#ffffff".to_string()),
                "continueButtonLabel" => block.summary.clone(),
                _ => unreachable!()
            },
            "unset": match change.property.as_str() {
                "sectionBackgroundHeight" => block.section_background_height.is_none(),
                "videoCaptionColor" => block.video_caption_color.is_none(),
                "videoCaptionBackgroundEnabled" => block.video_caption_background_enabled.is_none(),
                "videoCaptionOutline" => block.video_caption_outline.is_none(),
                "videoAllowFullscreen" => block.video_allow_fullscreen.is_none(),
                "textActivityContentHtml" => block.content_html.is_none(),
                "activityRichTextBlockJson" => false,
                "paddingOffset" => block.padding_offset.is_none(),
                "sectionBackgroundColor" => block.section_background_color.is_none(),
                "sectionBackgroundImageRef" => block.section_background_image_ref.is_none(),
                "sectionBackgroundOpacity" => block.section_background_opacity.is_none(),
                "sectionBackgroundOverlayDark" => block.section_background_overlay_dark.is_none(),
                "sectionBackgroundBlur" => block.section_background_blur.is_none(),
                "sectionBackgroundRounded" => block.section_background_rounded.is_none(),
                "sectionBackgroundWide" => block.section_background_wide.is_none(),
                "panelRounded" => block.panel_rounded.is_none(),
                "panelBackgroundColor" => block.panel_background_color.is_none(),
                "panelBorderColor" => block.panel_border_color.is_none(),
                "panelBorderWidth" => block.panel_border_width.is_none(),
                "panelBorderStyle" => block.panel_border_style.is_none(),
                "panelShadow" => block.panel_shadow.is_none(),
                "activityAccentColor" => match block.block_type.as_str() {
                    "audio" | "quote" => block.button_text_color.is_none(),
                    "links-resources" => block.button_background_color.is_none(),
                    _ => block.panel_border_color.is_none(),
                },
                "matchingLabelBackgroundColor" | "matchingLabelRounded" | "findElementsImageRounded" | "findElementsImageShadow" | "cardSortCardRounded" => false,
                "slidesActivityBackgroundColor" => block.slides_activity_background_color.is_none(),
                "slidesActivityRounded" => block.slides_activity_rounded.is_none(),
                "slidesActivityShadow" => block.slides_activity_shadow.is_none(),
                "dividerColor" => block.divider_color.is_none(),
                "dividerWidth" => block.divider_width.is_none(),
                "dividerStyle" => block.divider_style.is_none(),
                "markerScheme" => block.marker_scheme.is_none(),
                "markerType" => block.marker_type.is_none(),
                "markerTextColor" => block.marker_text_color.is_none(),
                "headerBackgroundColor" => block.header_background_color.is_none(),
                "headerTextColor" => block.header_text_color.is_none(),
                "headerTextOutline" => block.header_text_outline.is_none(),
                "headerTextOutlineColor" => block.header_text_outline_color.is_none(),
                "contentAlign" => block.content_align.is_none(),
                "continueButtonBackgroundColor" => block.button_background_color.is_none(),
                "continueButtonTextColor" => block.button_text_color.is_none(),
                "continueButtonLabel" => false,
                _ => unreachable!()
            }
        }));
    }

    for change in &changes {
        if change.property == "courseTextColor" {
            let mut appearance = project
                .course_appearance
                .clone()
                .unwrap_or(CourseAppearance {
                    rounded_corners: true,
                    shadows: true,
                    text_color_mode: "default".to_string(),
                    text_color: "#222222".to_string(),
                    background_color: "#FFFFFF".to_string(),
                });
            if change.unset {
                appearance.text_color_mode = "default".to_string();
            } else {
                appearance.text_color_mode = "custom".to_string();
                appearance.text_color = change.value.clone();
            }
            project.course_appearance = Some(appearance);
            continue;
        }
        let block = project
            .course
            .modules
            .iter_mut()
            .flat_map(|module| module.chapters.iter_mut())
            .flat_map(|chapter| chapter.pages.iter_mut())
            .find(|page| page.id == change.page_id)
            .and_then(|page| {
                page.blocks
                    .iter_mut()
                    .find(|block| block.id == change.block_id)
            })
            .ok_or_else(|| format!("Designer target block disappeared: {}", change.block_id))?;

        match change.property.as_str() {
            "sectionBackgroundHeight" => {
                block.section_background_height = (!change.unset).then(|| change.value.clone())
            }
            "videoCaptionColor" => {
                block.video_caption_color = (!change.unset).then(|| change.value.clone())
            }
            "videoCaptionBackgroundEnabled" => {
                block.video_caption_background_enabled =
                    (!change.unset).then_some(change.value == "true")
            }
            "videoCaptionOutline" => {
                block.video_caption_outline = (!change.unset).then(|| change.value.clone())
            }
            "videoAllowFullscreen" => {
                block.video_allow_fullscreen = (!change.unset).then_some(change.value == "true")
            }
            "textActivityContentHtml" => {
                block.content_html = (!change.unset).then(|| change.value.clone())
            }
            "activityRichTextBlockJson" => {
                *block = serde_json::from_str(&change.value)
                    .map_err(|error| format!("Invalid Rich Text activity payload: {}", error))?
            }
            "paddingOffset" => {
                block.padding_offset = if change.unset {
                    None
                } else {
                    Some(change.value.parse::<i32>().map_err(|_| {
                        format!("Unsupported activity spacing value: {}", change.value)
                    })?)
                }
            }
            "sectionBackgroundColor" => {
                block.section_background_color = (!change.unset).then(|| change.value.clone())
            }
            "sectionBackgroundImageRef" => {
                block.section_background_image_ref = (!change.unset).then(|| change.value.clone())
            }
            "sectionBackgroundOpacity" => {
                block.section_background_opacity = if change.unset {
                    None
                } else {
                    Some(
                        change
                            .value
                            .parse::<f64>()
                            .map_err(|_| "Unsupported activity background opacity".to_string())?,
                    )
                }
            }
            "sectionBackgroundOverlayDark" => {
                block.section_background_overlay_dark =
                    (!change.unset).then_some(change.value == "true")
            }
            "sectionBackgroundBlur" => {
                block.section_background_blur = if change.unset {
                    None
                } else {
                    Some(
                        change
                            .value
                            .parse::<f64>()
                            .map_err(|_| "Unsupported activity background blur".to_string())?,
                    )
                }
            }
            "sectionBackgroundRounded" => {
                block.section_background_rounded = (!change.unset).then_some(change.value == "true")
            }
            "sectionBackgroundWide" => {
                block.section_background_wide = (!change.unset).then_some(change.value == "true")
            }
            "panelRounded" => {
                block.panel_rounded = (!change.unset).then_some(change.value == "true")
            }
            "panelBackgroundColor" => {
                block.panel_background_color = (!change.unset).then(|| change.value.clone())
            }
            "panelBorderColor" => {
                block.panel_border_color = (!change.unset).then(|| change.value.clone())
            }
            "panelBorderWidth" => {
                block.panel_border_width = (!change.unset).then(|| change.value.clone())
            }
            "panelBorderStyle" => {
                block.panel_border_style = (!change.unset).then(|| change.value.clone())
            }
            "panelShadow" => {
                block.panel_shadow = (!change.unset).then_some(change.value == "true")
            }
            "activityAccentColor" => match block.block_type.as_str() {
                "audio" | "quote" => block.button_text_color = (!change.unset).then(|| change.value.clone()),
                "links-resources" => block.button_background_color = (!change.unset).then(|| change.value.clone()),
                _ => block.panel_border_color = (!change.unset).then(|| change.value.clone()),
            },
            "matchingLabelBackgroundColor" => block.matching.as_mut().ok_or_else(|| "Matching appearance data is missing".to_string())?.label_appearance.background_color = change.value.clone(),
            "matchingLabelRounded" => block.matching.as_mut().ok_or_else(|| "Matching appearance data is missing".to_string())?.label_appearance.rounded = change.value == "true",
            "findElementsImageRounded" => block.find_elements.as_mut().ok_or_else(|| "Find-elements appearance data is missing".to_string())?.image_appearance.rounded = change.value == "true",
            "findElementsImageShadow" => block.find_elements.as_mut().ok_or_else(|| "Find-elements appearance data is missing".to_string())?.image_appearance.shadow = change.value == "true",
            "slidesActivityBackgroundColor" => block.slides_activity_background_color = (!change.unset).then(|| change.value.clone()),
            "slidesActivityRounded" => block.slides_activity_rounded = (!change.unset).then_some(change.value == "true"),
            "slidesActivityShadow" => block.slides_activity_shadow = (!change.unset).then_some(change.value == "true"),
            "cardSortCardRounded" => block.card_sort.as_mut().ok_or_else(|| "Card-sort appearance data is missing".to_string())?.card_appearance.rounded = change.value == "true",
            "dividerColor" => block.divider_color = (!change.unset).then(|| change.value.clone()),
            "dividerWidth" => block.divider_width = (!change.unset).then(|| change.value.clone()),
            "dividerStyle" => block.divider_style = (!change.unset).then(|| change.value.clone()),
            "markerScheme" => block.marker_scheme = (!change.unset).then(|| change.value.clone()),
            "markerType" => block.marker_type = (!change.unset).then(|| change.value.clone()),
            "markerTextColor" => block.marker_text_color = (!change.unset).then(|| change.value.clone()),
            "headerBackgroundColor" => block.header_background_color = (!change.unset).then(|| change.value.clone()),
            "headerTextColor" => block.header_text_color = (!change.unset).then(|| change.value.clone()),
            "headerTextOutline" => block.header_text_outline = (!change.unset).then(|| change.value.clone()),
            "headerTextOutlineColor" => block.header_text_outline_color = (!change.unset).then(|| change.value.clone()),
            "contentAlign" => block.content_align = (!change.unset).then(|| change.value.clone()),
            "continueButtonBackgroundColor" => {
                block.button_background_color = (!change.unset).then(|| change.value.clone())
            }
            "continueButtonTextColor" => {
                block.button_text_color = (!change.unset).then(|| change.value.clone())
            }
            "continueButtonLabel" => block.summary = change.value.trim().to_string(),
            _ => unreachable!(),
        }
    }

    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "project",
        &project.id,
        if undo {
            "designer.bulk-action.undone"
        } else {
            "designer.bulk-action.applied"
        },
        if undo {
            "Action concepteur annulée"
        } else {
            "Action concepteur appliquée"
        },
        "project.json",
        serde_json::json!({
            "changeCount": changes.len(),
            "property": "designer-bulk",
            "actionId": action_id,
            "originalCommand": original_command,
            "undo": undo
        }),
        serde_json::json!({ "before": before, "after": changes }),
    )?;

    load_workspace_state_from_path(&project_path)
}

#[tauri::command]
pub fn delete_block(
    project_path: String,
    page_id: String,
    block_id: String,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let page = project
        .course
        .modules
        .iter_mut()
        .flat_map(|module| module.chapters.iter_mut())
        .flat_map(|chapter| chapter.pages.iter_mut())
        .find(|page| page.id == page_id)
        .ok_or_else(|| "Target page not found".to_string())?;

    let block_index = page
        .blocks
        .iter()
        .position(|block| block.id == block_id)
        .ok_or_else(|| "Target block not found".to_string())?;

    let before = page.blocks.clone();
    let removed_block = page.blocks.remove(block_index);
    let after = page.blocks.clone();
    let payload_page_id = page_id.clone();
    let payload_block_id = block_id.clone();

    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    prune_orphaned_project_assets(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "block",
        &block_id,
        "block.deleted",
        "ActivitÃ© supprimÃ©e",
        &format!("content/blocks/{}.json", block_id),
        serde_json::json!({ "pageId": payload_page_id, "blockId": payload_block_id }),
        serde_json::json!({
            "before": before,
            "removed": removed_block,
            "after": after
        }),
    )?;

    load_workspace_state_from_path(&project_path)
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DesignerBlockDeletionTarget {
    pub page_id: String,
    pub block_id: String,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DeleteDesignerBlocksResult {
    pub workspace_state: PaideiaWorkspaceState,
    pub snapshot_id: String,
}

#[tauri::command]
pub fn delete_designer_blocks(
    project_path: String,
    expected_project_id: String,
    expected_project_updated_at: String,
    expected_activity_type: Option<String>,
    expected_activity_types: Option<Vec<String>>,
    excluded_activity_types: Option<Vec<String>>,
    expected_chapter_ids: Option<Vec<String>>,
    targets: Vec<DesignerBlockDeletionTarget>,
    snapshot_label: String,
    version_tag: String,
    original_command: String,
) -> Result<DeleteDesignerBlocksResult, String> {
    const MAX_PROJECT_SNAPSHOTS: usize = 50;
    if targets.is_empty() {
        return Err("Aucune activité à supprimer".to_string());
    }
    if snapshot_label.trim().is_empty() {
        return Err("Le point de restauration doit avoir un libellé".to_string());
    }

    let mut project = load_project_from_path(&project_path)?;
    if project.id != expected_project_id || project.updated_at != expected_project_updated_at {
        return Err("La leçon a changé depuis l’examen de la suppression. Recommencez l’analyse.".to_string());
    }

    let requested: HashSet<(String, String)> = targets
        .iter()
        .map(|target| (target.page_id.clone(), target.block_id.clone()))
        .collect();
    if requested.len() != targets.len() {
        return Err("La liste des activités à supprimer contient des doublons".to_string());
    }
    let existing: HashSet<(String, String)> = project.course.modules.iter()
        .flat_map(|module| module.chapters.iter())
        .flat_map(|chapter| chapter.pages.iter())
        .flat_map(|page| page.blocks.iter().map(move |block| (page.id.clone(), block.id.clone())))
        .collect();
    if !requested.iter().all(|target| existing.contains(target)) {
        return Err("Le périmètre de suppression ne correspond plus à la leçon. Recommencez l’analyse.".to_string());
    }
    if let Some(chapter_ids) = expected_chapter_ids.as_ref() {
        if chapter_ids.is_empty() {
            return Err("La liste des chapitres ciblés est vide".to_string());
        }
        let unique_chapter_ids: HashSet<&String> = chapter_ids.iter().collect();
        if unique_chapter_ids.len() != chapter_ids.len() {
            return Err("La liste des chapitres ciblés contient des doublons".to_string());
        }
        let existing_chapter_ids: HashSet<&String> = project.course.modules.iter()
            .flat_map(|module| module.chapters.iter())
            .map(|chapter| &chapter.id)
            .collect();
        if !unique_chapter_ids.iter().all(|id| existing_chapter_ids.contains(*id)) {
            return Err("Un chapitre ciblé n’existe plus. Aucune activité n’a été supprimée.".to_string());
        }
    }
    let included_activity_types = expected_activity_types
        .filter(|items| !items.is_empty())
        .or_else(|| expected_activity_type.map(|item| vec![item]));
    let excluded_activity_types = excluded_activity_types.unwrap_or_default();
    if included_activity_types.as_ref().is_some_and(|included| included.iter().any(|item| excluded_activity_types.contains(item))) {
        return Err("Un type d’activité ne peut pas être inclus et exclu de la même suppression".to_string());
    }
    let expected: HashSet<(String, String)> = project.course.modules.iter()
        .flat_map(|module| module.chapters.iter())
        .filter(|chapter| expected_chapter_ids.as_ref().map_or(true, |ids| ids.contains(&chapter.id)))
        .flat_map(|chapter| chapter.pages.iter())
        .flat_map(|page| page.blocks.iter()
            .filter(|block| included_activity_types.as_ref().map_or(true, |activity_types| activity_types.contains(&block.block_type)))
            .filter(|block| !excluded_activity_types.contains(&block.block_type))
            .map(move |block| (page.id.clone(), block.id.clone())))
        .collect();
    if requested != expected {
        return Err("Le périmètre exact de la suppression n’est plus identique à l’aperçu. Aucune activité n’a été supprimée.".to_string());
    }

    crate::asset_integrity::clear_confirmed_missing_media(
        &resolve_project_path(&project_path), &mut project,
    )?;

    // The recovery point is durable before the first destructive write.
    let snapshot_id = format!("snapshot-{}", compact_timestamp());
    let snapshot = SnapshotRecord {
        id: snapshot_id.clone(),
        label: snapshot_label.clone(),
        version_tag,
        created_at: now_iso(),
        created_by: "local-user".into(),
        manifest_path: format!("snapshots/{}/manifest.json", snapshot_id),
    };
    let before_asset_refs = project_asset_refs(&project_path, &project);
    save_snapshot(&project_path, &snapshot, &project)?;

    let before_count = existing.len();
    for module in &mut project.course.modules {
        for chapter in &mut module.chapters {
            for page in &mut chapter.pages {
                page.blocks.retain(|block| !requested.contains(&(page.id.clone(), block.id.clone())));
            }
        }
    }
    let remaining_count: usize = project.course.modules.iter()
        .flat_map(|module| module.chapters.iter())
        .flat_map(|chapter| chapter.pages.iter())
        .map(|page| page.blocks.len())
        .sum();
    if before_count.saturating_sub(remaining_count) != requested.len() {
        return Err("La suppression a été interrompue avant l’écriture : le périmètre n’est plus exact".to_string());
    }

    let after_asset_refs = project_asset_refs(&project_path, &project);
    let detached_asset_refs = before_asset_refs
        .difference(&after_asset_refs)
        .cloned()
        .collect::<HashSet<_>>();
    let protected_asset_count = match backup_snapshot_assets(
        &project_path,
        &snapshot_id,
        &detached_asset_refs,
        false,
    ) {
        Ok(count) => count,
        Err(error) => {
            let _ = fs::remove_dir_all(
                resolve_project_path(&project_path)
                    .join("snapshots")
                    .join(&snapshot_id),
            );
            let _ = prune_snapshot_asset_store(&project_path);
            return Err(error);
        }
    };
    prune_snapshots(&project_path, MAX_PROJECT_SNAPSHOTS)?;
    prune_snapshot_asset_store(&project_path)?;
    append_standard_event(
        &project_path,
        &project,
        "snapshot",
        &snapshot_id,
        "snapshot.created",
        "Snapshot créé avant suppression Arion",
        &snapshot.manifest_path,
        serde_json::json!({
            "label": snapshot_label,
            "versionTag": snapshot.version_tag,
            "source": "arion-destructive-action",
            "protectedAssetCount": protected_asset_count
        }),
        serde_json::json!({ "before": null, "after": snapshot }),
    )?;

    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    prune_orphaned_project_assets(&project_path, &project)?;
    append_standard_event(
        &project_path,
        &project,
        "project",
        &project.id,
        "designer.activities.deleted",
        "Activités supprimées par Arion",
        "project.json",
        serde_json::json!({
            "activityCount": requested.len(),
            "chapterIds": expected_chapter_ids,
            "snapshotId": snapshot_id,
            "originalCommand": original_command
        }),
        serde_json::json!({ "deletedTargets": requested }),
    )?;

    Ok(DeleteDesignerBlocksResult {
        workspace_state: load_workspace_state_from_path(&project_path)?,
        snapshot_id,
    })
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct RenameProjectResult {
    project_path: String,
    title: String,
    updated_at: String,
    course_cover_title_html: String,
}

fn renamed_course_cover_title_html(html: &str, title: &str) -> String {
    // Keep the existing paragraph/span styles and line breaks. Distribute the
    // new words over the existing text runs; never rewrite lesson activities.
    let tags = Regex::new(r#"(?s)<(?:"[^"]*"|'[^']*'|[^'">])*>"#).expect("cover title tags");
    let mut runs = Vec::new();
    let mut end = 0;
    for tag in tags.find_iter(html) {
        let text = &html[end..tag.start()];
        let count = scorm_plain_text_from_html(text).split_whitespace().count();
        if count > 0 { runs.push((end, tag.start(), count)); }
        end = tag.end();
    }
    let count = scorm_plain_text_from_html(&html[end..]).split_whitespace().count();
    if count > 0 { runs.push((end, html.len(), count)); }
    if runs.is_empty() { return format!("<p>{}</p>", escape_html(title)); }
    let words: Vec<_> = title.split_whitespace().collect();
    let mut result = String::new();
    let mut cursor = 0;
    let mut word = 0;
    for (index, &(start, end, count)) in runs.iter().enumerate() {
        result.push_str(&html[cursor..start]);
        let next = if index + 1 == runs.len() { words.len() } else { (word + count).min(words.len()) };
        if next > word {
            if html[start..end].starts_with(char::is_whitespace) { result.push(' '); }
            result.push_str(&escape_html(&words[word..next].join(" ")));
            if next < words.len() || html[start..end].ends_with(char::is_whitespace) { result.push(' '); }
        }
        word = next;
        cursor = end;
    }
    result.push_str(&html[cursor..]);
    result
}

#[tauri::command]
pub async fn rename_project_title(project_path: String, title: String) -> Result<RenameProjectResult, String> {
    tauri::async_runtime::spawn_blocking(move || rename_project_title_impl(&project_path, &title))
        .await.map_err(|error| format!("Échec du renommage : {error}"))?
}

fn rename_project_title_impl(project_path: &str, title: &str) -> Result<RenameProjectResult, String> {
    let root = resolve_project_path(project_path);
    crate::project_compatibility::check_path(&root)?;
    if root.join(".paideia-collaboration-readonly").is_file()
        || root.join(".paideia-collaboration-revoked").is_file()
    {
        return Err("Cette leçon ne peut pas être renommée en lecture seule ou après révocation de son accès.".into());
    }
    // Patch only these two documents. A rename must not migrate activities,
    // rebuild granular content, sanitize rich text or prune media.
    let meta_bytes = fs::read(root.join("project.json")).map_err(|error| error.to_string())?;
    let course_bytes = fs::read(root.join("content/course.json")).map_err(|error| error.to_string())?;
    let mut meta: serde_json::Value = serde_json::from_slice(&meta_bytes).map_err(|error| error.to_string())?;
    let mut course: serde_json::Value = serde_json::from_slice(&course_bytes).map_err(|error| error.to_string())?;
    if !meta.is_object() || !course.is_object() {
        return Err("Métadonnées de leçon invalides.".into());
    }
    let title = normalize_project_title(title);
    let previous_title = meta["title"].as_str().unwrap_or_default().to_string();
    let previous_cover = meta["courseCoverTitleHtml"].as_str().unwrap_or_default();
    let course_cover_title_html = renamed_course_cover_title_html(previous_cover, &title);
    if previous_title == title && previous_cover == course_cover_title_html {
        return Ok(RenameProjectResult { project_path: root.to_string_lossy().into(), title,
            updated_at: meta["updatedAt"].as_str().unwrap_or_default().into(), course_cover_title_html });
    }
    let updated_at = now_iso();
    meta["title"] = serde_json::json!(title);
    meta["updatedAt"] = serde_json::json!(updated_at);
    meta["courseCoverTitleHtml"] = serde_json::json!(course_cover_title_html);
    course["title"] = serde_json::json!(title);
    let next_meta = serde_json::to_vec_pretty(&meta).map_err(|error| error.to_string())?;
    let next_course = serde_json::to_vec_pretty(&course).map_err(|error| error.to_string())?;
    let next_root = if previous_title == title || root.join(".paideia-collaboration/link.json").is_file() {
        root.clone()
    } else {
        let parent = root.parent().ok_or("Dossier parent de la leçon introuvable.")?;
        let folder = root.file_name().and_then(|value| value.to_str()).unwrap_or_default();
        let suffix = extract_timestamp_suffix(folder).unwrap_or_else(compact_timestamp);
        unique_project_folder_with_suffix(parent, &slug_from_title(&title), &suffix)?
    };
    if next_root != root {
        fs::rename(&root, &next_root).map_err(|error| format!("Renommage du dossier impossible : {error}"))?;
    }
    let write_result = (|| -> Result<(), String> {
        fs::write(next_root.join("project.json"), &next_meta).map_err(|error| error.to_string())?;
        fs::write(next_root.join("content/course.json"), &next_course).map_err(|error| error.to_string())?;
        append_event_record(&next_root.to_string_lossy(), &EventRecord {
            id: format!("evt_{}", compact_timestamp()),
            project_id: meta["id"].as_str().unwrap_or_default().into(),
            aggregate_type: "project".into(), aggregate_id: meta["id"].as_str().unwrap_or_default().into(),
            event_type: "project.metadata.updated".into(), actor_user_id: "local-user".into(),
            actor_role: "author".into(), timestamp: updated_at.clone(), machine: "local".into(),
            label: "Leçon renommée".into(), target_path: "project.json".into(),
            payload: serde_json::json!({ "title": title }),
            diff: serde_json::json!({ "before": { "title": previous_title }, "after": { "title": title } }),
        })?;
        Ok(())
    })();
    if let Err(error) = write_result {
        let mut recovery_errors = Vec::new();
        for (path, bytes) in [("project.json", &meta_bytes), ("content/course.json", &course_bytes)] {
            if let Err(recovery_error) = fs::write(next_root.join(path), bytes) {
                recovery_errors.push(recovery_error.to_string());
            }
        }
        if next_root != root {
            if let Err(recovery_error) = fs::rename(&next_root, &root) {
                recovery_errors.push(recovery_error.to_string());
            }
        }
        return Err(if recovery_errors.is_empty() { error } else {
            format!("{error} ; restauration du renommage incomplète : {}", recovery_errors.join(" ; "))
        });
    }
    Ok(RenameProjectResult { project_path: next_root.to_string_lossy().into(), title, updated_at, course_cover_title_html })
}

#[tauri::command]
pub fn update_project_keywords(
    project_path: String,
    keywords: Vec<String>,
) -> Result<PaideiaWorkspaceState, String> {
    let root = resolve_project_path(&project_path);
    let mut normalized = Vec::new();
    for keyword in keywords {
        let keyword = keyword.trim();
        if keyword.is_empty() || keyword.chars().count() > 100 {
            continue;
        }
        if !normalized.iter().any(|existing: &String| existing.to_lowercase() == keyword.to_lowercase()) {
            normalized.push(keyword.to_string());
        }
    }
    if root.is_file() && root.extension().and_then(|value| value.to_str()).is_some_and(|value| value.eq_ignore_ascii_case("paideia")) {
        let metadata = fs::metadata(&root).map_err(|error| error.to_string())?;
        if metadata.len() > PAIDEIA_ARCHIVE_MAX_COMPRESSED_BYTES {
            return Err("L’archive .paideia dépasse la taille maximale autorisée.".into());
        }
        let staging = std::env::temp_dir().join(format!("paideia-keywords-{}", uuid::Uuid::new_v4()));
        let result = (|| -> Result<PaideiaWorkspaceState, String> {
            let bytes = fs::read(&root).map_err(|error| error.to_string())?;
            extract_paideia_archive_to(&bytes, &staging)?;
            let stage_path = staging.to_string_lossy().into_owned();
            let mut project = load_project_from_path(&stage_path)?;
            if project.keywords != normalized {
                project.keywords = normalized;
                touch_project(&mut project);
                save_project_meta_to_path(&stage_path, &project)?;
                let state = load_workspace_state_from_path(&stage_path)?;
                zip_directory_to_file(&staging, &root)?;
                Ok(state)
            } else {
                load_workspace_state_from_path(&stage_path)
            }
        })();
        let _ = fs::remove_dir_all(&staging);
        return result;
    }
    if !root.is_dir() || root.join(".paideia-collaboration-readonly").exists() {
        return Err("Cette leçon ne peut pas être modifiée ici.".into());
    }
    let mut project = load_project_from_path(&project_path)?;
    if project.keywords != normalized {
        project.keywords = normalized;
        touch_project(&mut project);
        save_project_meta_to_path(&project_path, &project)?;
    }
    load_workspace_state_from_path(&project_path)
}

#[tauri::command]
pub fn update_project_metadata(
    project_path: String,
    title: String,
    author: String,
    course_image_ref: Option<String>,
    course_cover_title_html: Option<String>,
    course_intro_html: Option<String>,
    title_style: Option<CourseTitleStyle>,
    custom_font: Option<LessonCustomFont>,
    course_cover_style: Option<CourseCoverStyle>,
    activity_spacing_px: Option<u32>,
    hide_chapter_title_banner: Option<bool>,
    course_appearance: Option<CourseAppearance>,
) -> Result<ProjectMutationResult, String> {
    let mut project = load_project_from_path(&project_path)?;
    let title = normalize_project_title(&title);
    let current_root = resolve_project_path(&project_path);
    let before = serde_json::json!({
        "title": project.title,
        "courseImageRef": project.course_image_ref,
        "courseCoverTitleHtml": project.course_cover_title_html,
        "courseIntroHtml": project.course_intro_html,
        "createdBy": project.created_by,
        "titleStyle": project.title_style,
        "customFont": project.custom_font,
        "courseCoverStyle": project.course_cover_style,
        "activitySpacingPx": project.activity_spacing_px,
        "hideChapterTitleBanner": project.hide_chapter_title_banner,
        "courseAppearance": project.course_appearance,
    });
    let title_changed = project.title.trim() != title.trim();

    project.title = title.clone();
    project.course.title = title.clone();
    project.course_image_ref = course_image_ref.clone().and_then(|value| {
        let trimmed = value.trim().to_string();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed)
        }
    });
    if let Some(course_cover_title_html) = course_cover_title_html.clone() {
        project.course_cover_title_html = course_cover_title_html;
    }
    if let Some(course_intro_html) = course_intro_html.clone() {
        project.course_intro_html = course_intro_html;
    }
    project.created_by = author.clone();
    project.title_style = title_style.clone();
    project.custom_font = custom_font.clone().or_else(|| project.custom_font.clone());
    project.course_cover_style = course_cover_style.clone().map(normalize_course_cover_style);
    if let Some(activity_spacing_px) = activity_spacing_px {
        project.activity_spacing_px = Some(activity_spacing_px.clamp(15, 60));
    }
    if let Some(hide_chapter_title_banner) = hide_chapter_title_banner {
        project.hide_chapter_title_banner = hide_chapter_title_banner;
    }
    if let Some(course_appearance) = course_appearance.clone() {
        project.course_appearance = Some(course_appearance);
    }
    touch_project(&mut project);

    let mut next_project_path = current_root.clone();
    let is_collaborative = current_root
        .join(".paideia-collaboration/link.json")
        .is_file();
    if title_changed && !is_collaborative {
        let parent = current_root
            .parent()
            .ok_or_else(|| "Impossible de trouver le dossier parent du projet".to_string())?
            .to_path_buf();
        let folder_name = current_root
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("paideia-project");
        let timestamp_suffix =
            extract_timestamp_suffix(folder_name).unwrap_or_else(compact_timestamp);
        let renamed_slug = slug_from_title(&title);
        next_project_path =
            unique_project_folder_with_suffix(&parent, &renamed_slug, &timestamp_suffix)?;
    }

    save_project_to_path(&project_path, &project)?;
    if title_changed && !is_collaborative {
        fs::rename(&current_root, &next_project_path).map_err(|err| err.to_string())?;
    }
    prune_orphaned_project_assets(&next_project_path.to_string_lossy(), &project)?;

    append_standard_event(
        &next_project_path.to_string_lossy(),
        &project,
        "project",
        &project.id,
        "project.metadata.updated",
        "MÃ©tadonnÃ©es projet modifiÃ©es",
        "project.json",
        serde_json::json!({ "title": title, "author": author, "courseImageRef": course_image_ref, "courseCoverTitleHtml": course_cover_title_html, "courseIntroHtml": course_intro_html, "titleStyle": title_style, "customFont": custom_font, "courseCoverStyle": course_cover_style, "activitySpacingPx": activity_spacing_px, "hideChapterTitleBanner": hide_chapter_title_banner, "courseAppearance": course_appearance }),
        serde_json::json!({
            "before": before,
            "after": {
                "title": project.title,
                "courseImageRef": project.course_image_ref,
                "courseCoverTitleHtml": project.course_cover_title_html,
                "courseIntroHtml": project.course_intro_html,
                "createdBy": project.created_by,
                "titleStyle": project.title_style,
                "customFont": project.custom_font,
                "courseCoverStyle": project.course_cover_style,
                "activitySpacingPx": project.activity_spacing_px,
                "hideChapterTitleBanner": project.hide_chapter_title_banner,
                "courseAppearance": project.course_appearance,
            }
        }),
    )?;

    Ok(ProjectMutationResult {
        project_path: next_project_path.to_string_lossy().to_string(),
        workspace_state: load_workspace_state_from_path(&next_project_path.to_string_lossy())?,
    })
}

fn normalize_course_cover_style(style: CourseCoverStyle) -> CourseCoverStyle {
    let title_position = normalize_course_cover_title_position(style.title_position.as_deref());
    CourseCoverStyle {
        height_px: match style.height_px {
            value if value <= 350 => 300,
            value if value <= 450 => 400,
            _ => 500,
        },
        background_position_y: style.background_position_y.clamp(0.0, 100.0),
        background_color: safe_css_color(&style.background_color, "#123a7a"),
        title_color: safe_css_color(&style.title_color, "#ffffff"),
        title_position: Some(title_position.clone()),
        title_align: Some(course_cover_title_align_for_position(&title_position)),
        overlay_enabled: style.overlay_enabled,
        overlay_color: Some(match style.overlay_color.as_deref().map(str::trim) {
            Some(color) if color.eq_ignore_ascii_case("transparent") => "transparent".to_string(),
            Some(color) => safe_css_color(color, "#123a7a"),
            None => "#123a7a".to_string(),
        }),
        overlay_opacity: Some(style.overlay_opacity.unwrap_or(0.92).clamp(0.0, 1.0)),
        overlay_position: Some(normalize_course_cover_overlay_position(
            style.overlay_position.as_deref(),
        )),
        overlay_spread: Some(normalize_course_cover_overlay_spread(
            style.overlay_spread.as_deref(),
        )),
        button_position: Some(course_cover_button_position_for_title_position(
            &title_position,
        )),
        title_outline: Some(normalize_course_cover_title_outline(
            style.title_outline.as_deref(),
        )),
        title_outline_color: Some(normalize_course_cover_title_outline_color(
            style.title_outline_color.as_deref(),
        )),
    }
}

#[tauri::command]
pub fn update_project_language(
    project_path: String,
    language: String,
    localized_course: PaideiaCourse,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let normalized_language = language
        .trim()
        .split(['-', '_'])
        .next()
        .unwrap_or("fr")
        .to_ascii_lowercase();
    if normalized_language.len() < 2 || normalized_language.len() > 3 {
        return Err("Langue de projet invalide".to_string());
    }
    if localized_course.id != project.course.id {
        return Err("Le cours localisé ne correspond pas au projet ouvert".to_string());
    }

    let before_locale = project.default_locale.clone();
    project.default_locale = normalized_language.clone();
    project.locales = vec![normalized_language.clone()];
    project.course = localized_course;
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;

    append_standard_event(
        &project_path,
        &project,
        "project",
        &project.id,
        "project.language.updated",
        "Langue du projet modifiée",
        "project.json",
        serde_json::json!({ "language": normalized_language }),
        serde_json::json!({
            "before": { "defaultLocale": before_locale },
            "after": { "defaultLocale": project.default_locale }
        }),
    )?;

    load_workspace_state_from_path(&project_path)
}

fn normalize_course_cover_title_position(value: Option<&str>) -> String {
    match value {
        Some("center") | Some("center-bottom") | Some("right-bottom") => value.unwrap().to_string(),
        _ => "left-bottom".to_string(),
    }
}

fn course_cover_title_align_for_position(position: &str) -> String {
    match position {
        "center" | "center-bottom" => "center".to_string(),
        "right-bottom" => "right".to_string(),
        _ => "left".to_string(),
    }
}

fn normalize_course_cover_overlay_position(value: Option<&str>) -> String {
    match value {
        Some("center") | Some("right") | Some("full") => value.unwrap().to_string(),
        _ => "left".to_string(),
    }
}

fn normalize_course_cover_overlay_spread(value: Option<&str>) -> String {
    match value {
        Some("compact") | Some("wide") => value.unwrap().to_string(),
        _ => "normal".to_string(),
    }
}

fn normalize_course_cover_title_outline(value: Option<&str>) -> String {
    match value {
        Some("thin") | Some("medium") | Some("thick") => value.unwrap().to_string(),
        _ => "none".to_string(),
    }
}

fn normalize_course_cover_title_outline_color(value: Option<&str>) -> String {
    if value == Some("light") {
        "light".to_string()
    } else {
        "dark".to_string()
    }
}

fn course_cover_button_position_for_title_position(position: &str) -> String {
    match position {
        "center" | "center-bottom" => "center-bottom".to_string(),
        "right-bottom" => "right-bottom".to_string(),
        _ => "under-title".to_string(),
    }
}

fn safe_css_color(value: &str, fallback: &str) -> String {
    let trimmed = value.trim();
    let is_hex = trimmed.len() == 7
        && trimmed.starts_with('#')
        && trimmed.chars().skip(1).all(|item| item.is_ascii_hexdigit());
    if is_hex {
        trimmed.to_string()
    } else {
        fallback.to_string()
    }
}

fn css_hex_to_rgb_triplet(value: &str) -> String {
    let color = safe_css_color(value, "#123a7a");
    let red = u8::from_str_radix(&color[1..3], 16).unwrap_or(18);
    let green = u8::from_str_radix(&color[3..5], 16).unwrap_or(58);
    let blue = u8::from_str_radix(&color[5..7], 16).unwrap_or(122);
    format!("{}, {}, {}", red, green, blue)
}

fn contrasting_caption_outline(value: &str) -> &'static str {
    let color = safe_css_color(value, "#ffffff");
    let red = u8::from_str_radix(&color[1..3], 16).unwrap_or(255) as f64;
    let green = u8::from_str_radix(&color[3..5], 16).unwrap_or(255) as f64;
    let blue = u8::from_str_radix(&color[5..7], 16).unwrap_or(255) as f64;
    let luminance = (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255.0;
    if luminance > 0.52 {
        "#000000"
    } else {
        "#ffffff"
    }
}

#[derive(Debug, Serialize)]
pub struct ConvertedFontFace {
    family: String,
    file_name: String,
    bytes: Vec<u8>,
    weight: u16,
    style: String,
}

fn supported_font_archive_entry(name: &str) -> bool {
    let normalized = name.replace('\\', "/");
    !normalized
        .split('/')
        .any(|part| part == "__MACOSX" || part.starts_with("._"))
        && supported_font_path(Path::new(name))
}

fn uploaded_font_entries(
    file_name: &str,
    file_bytes: Vec<u8>,
) -> Result<Vec<(String, Vec<u8>)>, String> {
    const MAX_TOTAL: usize = 50 * 1024 * 1024;
    if file_bytes.len() > MAX_TOTAL {
        return Err("Le fichier de police dépasse 50 Mo".to_string());
    }
    let extension = Path::new(file_name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    if extension == "7z" {
        return uploaded_7z_font_entries(file_bytes);
    }
    if extension != "zip" {
        if !["woff", "woff2", "ttf", "otf"].contains(&extension.as_str()) {
            return Err("Formats acceptés : TTF, OTF, WOFF, WOFF2, ZIP ou 7Z".to_string());
        }
        return Ok(vec![(sanitize_filename(file_name), file_bytes)]);
    }
    let mut archive =
        ZipArchive::new(Cursor::new(file_bytes)).map_err(|_| "Archive ZIP invalide".to_string())?;
    let mut entries = Vec::new();
    let mut total = 0usize;
    for index in 0..archive.len() {
        let mut entry = archive.by_index(index).map_err(|err| err.to_string())?;
        if entry.is_dir() {
            continue;
        }
        let enclosed = entry
            .enclosed_name()
            .ok_or_else(|| "Chemin interdit dans l'archive ZIP".to_string())?;
        let name = enclosed
            .file_name()
            .and_then(|value| value.to_str())
            .ok_or_else(|| "Nom de police invalide".to_string())?;
        if !supported_font_archive_entry(&enclosed.to_string_lossy()) {
            continue;
        }
        if entries.len() >= 32 || entry.size() > 20 * 1024 * 1024 {
            return Err("Archive de polices trop volumineuse".to_string());
        }
        total = total.saturating_add(entry.size() as usize);
        if total > MAX_TOTAL {
            return Err("Le contenu décompressé dépasse 50 Mo".to_string());
        }
        let mut bytes = Vec::with_capacity(entry.size() as usize);
        entry
            .read_to_end(&mut bytes)
            .map_err(|err| err.to_string())?;
        entries.push((sanitize_filename(name), bytes));
    }
    if entries.is_empty() {
        return Err("Le ZIP ne contient aucune police compatible".to_string());
    }
    Ok(entries)
}

fn uploaded_7z_font_entries(file_bytes: Vec<u8>) -> Result<Vec<(String, Vec<u8>)>, String> {
    const MAX_TOTAL: usize = 50 * 1024 * 1024;
    let mut entries: Vec<(String, Vec<u8>)> = Vec::new();
    let mut total = 0usize;
    let mut limit_error: Option<String> = None;
    sevenz_rust2::decompress_with_extract_fn(
        Cursor::new(file_bytes),
        std::env::temp_dir().join("paideia-font-7z-scan"),
        |entry, reader, _dest| {
            if entry.is_directory {
                return Ok(true);
            }
            let Some(name) = Path::new(&entry.name)
                .file_name()
                .and_then(|value| value.to_str())
            else {
                std::io::copy(reader, &mut std::io::sink())?;
                return Ok(true);
            };
            if !supported_font_archive_entry(&entry.name) {
                // Solid 7Z streams must consume ignored entries so their CRC and the next entry remain aligned.
                std::io::copy(reader, &mut std::io::sink())?;
                return Ok(true);
            }
            if entries.len() >= 32 || entry.size > 20 * 1024 * 1024 {
                limit_error = Some("Archive de polices trop volumineuse".to_string());
                return Ok(false);
            }
            total = total.saturating_add(entry.size as usize);
            if total > MAX_TOTAL {
                limit_error = Some("Le contenu decompresse depasse 50 Mo".to_string());
                return Ok(false);
            }
            let mut bytes = Vec::with_capacity(entry.size as usize);
            reader.read_to_end(&mut bytes)?;
            entries.push((sanitize_filename(name), bytes));
            Ok(true)
        },
    )
    .map_err(|err| {
        let message = err.to_string();
        if message.contains("Password") || message.contains("password") {
            "Les archives 7Z chiffrees ne sont pas prises en charge".to_string()
        } else {
            format!("Archive 7Z invalide : {}", message)
        }
    })?;
    if let Some(error) = limit_error {
        return Err(error);
    }
    if entries.is_empty() {
        return Err("Le 7Z ne contient aucune police compatible".to_string());
    }
    Ok(entries)
}

fn parsed_font_name(face: &ttf_parser::Face<'_>, id: u16) -> Option<String> {
    face.names()
        .into_iter()
        .find(|name| name.name_id == id && name.is_unicode())
        .and_then(|name| name.to_string())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn decode_uploaded_web_font(file_name: &str, bytes: &[u8], woff2: bool) -> Result<Vec<u8>, String> {
    let format = if woff2 { "WOFF2" } else { "WOFF" };
    // The decoder has panic paths for truncated streams; an invalid upload must not unwind the command.
    std::panic::catch_unwind(|| {
        if woff2 {
            wuff::decompress_woff2(bytes)
        } else {
            wuff::decompress_woff1(bytes)
        }
    })
    .map_err(|_| {
        format!(
            "{} : décodage {} impossible (données tronquées ou invalides)",
            file_name, format
        )
    })?
    .map_err(|error| format!("{} : décodage {} impossible : {}", file_name, format, error))
}

fn supported_font_path(path: &Path) -> bool {
    path.extension()
        .and_then(|value| value.to_str())
        .map(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "ttf" | "otf" | "woff" | "woff2"
            )
        })
        .unwrap_or(false)
}

fn font_css_format(asset_ref: &str) -> &'static str {
    match Path::new(asset_ref)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("")
        .to_ascii_lowercase()
        .as_str()
    {
        "woff2" => "woff2",
        "woff" => "woff",
        "otf" => "opentype",
        _ => "truetype",
    }
}

fn convert_font_face(file_name: String, bytes: Vec<u8>) -> Result<ConvertedFontFace, String> {
    let signature = bytes.get(0..4).unwrap_or_default();
    let sfnt = match signature {
        b"wOFF" => decode_uploaded_web_font(&file_name, &bytes, false)?,
        b"wOF2" => decode_uploaded_web_font(&file_name, &bytes, true)?,
        b"OTTO" | b"\x00\x01\x00\x00" | b"true" => bytes.clone(),
        _ => return Err(format!("{} n'est pas une police valide", file_name)),
    };
    let face = ttf_parser::Face::parse(&sfnt, 0)
        .map_err(|_| format!("Métadonnées invalides dans {}", file_name))?;
    let family = parsed_font_name(&face, ttf_parser::name_id::TYPOGRAPHIC_FAMILY)
        .or_else(|| parsed_font_name(&face, ttf_parser::name_id::FAMILY))
        .unwrap_or_else(|| "Police personnalisée".to_string());
    let weight = face.weight().to_number().clamp(100, 900);
    let style = if face.is_italic() { "italic" } else { "normal" }.to_string();
    let (output, extension) = if signature == b"wOF2" {
        (bytes, "woff2")
    } else if signature == b"wOFF" {
        (bytes, "woff")
    } else if sfnt.starts_with(b"OTTO") {
        // The TrueType encoder cannot encode CFF outlines. Keep the validated native font.
        (bytes, "otf")
    } else {
        (
            ttf2woff2::encode(&sfnt, ttf2woff2::BrotliQuality::default()).map_err(|error| {
                format!("Conversion WOFF2 impossible pour {} : {}", file_name, error)
            })?,
            "woff2",
        )
    };
    let stem = Path::new(&file_name)
        .file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("font");
    Ok(ConvertedFontFace {
        family,
        file_name: format!("{}.{}", sanitize_filename(stem), extension),
        bytes: output,
        weight,
        style,
    })
}

#[tauri::command]
pub fn prepare_uploaded_font(file_name: String, file_bytes: Vec<u8>) -> Result<Vec<ConvertedFontFace>, String> {
    convert_uploaded_font(&file_name, file_bytes).map(|(_, faces)| faces)
}

fn convert_uploaded_font(
    file_name: &str,
    file_bytes: Vec<u8>,
) -> Result<(String, Vec<ConvertedFontFace>), String> {
    let mut faces = uploaded_font_entries(file_name, file_bytes)?
        .into_iter()
        .map(|(name, bytes)| convert_font_face(name, bytes))
        .collect::<Result<Vec<_>, _>>()?;
    let family = faces
        .first()
        .map(|face| face.family.clone())
        .unwrap_or_default();
    if faces
        .iter()
        .any(|face| !face.family.eq_ignore_ascii_case(&family))
    {
        return Err("Tous les fichiers du ZIP doivent appartenir à la même famille".to_string());
    }
    faces.sort_by_key(|face| (face.weight, face.style.clone()));
    faces.dedup_by(|left, right| left.weight == right.weight && left.style == right.style);
    Ok((family, faces))
}

fn store_project_font(
    project_path: &str,
    project: &mut PaideiaProject,
    family: String,
    converted: Vec<ConvertedFontFace>,
    source: &str,
) -> Result<(), String> {
    let id = sanitize_filename(&family.to_ascii_lowercase().replace(' ', "-"));
    let family_dir = resolve_project_path(project_path)
        .join("assets")
        .join("fonts")
        .join(&id);
    fs::create_dir_all(&family_dir).map_err(|err| err.to_string())?;
    let mut faces = Vec::new();
    for item in converted {
        let safe_name = sanitize_filename(&item.file_name);
        fs::write(family_dir.join(&safe_name), item.bytes).map_err(|err| err.to_string())?;
        faces.push(LessonFontFace {
            file_name: safe_name.clone(),
            asset_ref: format!("fonts/{}/{}", id, safe_name),
            weight: item.weight,
            style: item.style,
        });
    }
    let regular = faces
        .iter()
        .find(|face| face.weight == 400 && face.style == "normal")
        .or_else(|| faces.first())
        .ok_or_else(|| "Aucune face valide".to_string())?;
    project.custom_font = Some(LessonCustomFont {
        id,
        font_family: family,
        file_name: regular.file_name.clone(),
        asset_ref: regular.asset_ref.clone(),
        license_ref: None,
        source: source.to_string(),
        faces,
    });
    Ok(())
}

