#[tauri::command]
pub fn upload_project_font(
    project_path: String,
    file_name: String,
    file_bytes: Vec<u8>,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    preserve_imported_project_font(&project_path, &mut project)?;
    let (family, converted) = convert_uploaded_font(&file_name, file_bytes)?;
    let source_id = sanitize_filename(&family.to_ascii_lowercase().replace(' ', "-"));
    store_rich_text_font(&project_path, family, &source_id, "project", converted)?;
    let id = rich_text_storage_id("project", &source_id);
    let font = scan_project_rich_text_fonts(&project_path)?.into_iter().find(|font| font.id == id)
        .ok_or_else(|| "Police importée introuvable".to_string())?;
    project.imported_fonts.retain(|existing| existing.id != id);
    project.imported_fonts.push(font);
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    prune_orphaned_project_assets(&project_path, &project)?;
    append_standard_event(
        &project_path,
        &project,
        "project",
        &project.id,
        "project.font.imported",
        "Police personnalisée importée",
        "assets/fonts",
        serde_json::json!({ "sourceFile": file_name }),
        serde_json::json!({ "importedFonts": project.imported_fonts }),
    )?;
    load_workspace_state_from_path(&project_path)
}

