fn install_bundled_font(
    project_path: &str,
    project: &mut PaideiaProject,
    font_id: &str,
) -> Result<(), String> {
    let (family, entries) = bundled_font_entries(font_id)?;
    let converted = entries
        .into_iter()
        .map(|(name, bytes)| convert_font_face(name.to_string(), bytes.to_vec()))
        .collect::<Result<Vec<_>, _>>()?;
    store_project_font(
        project_path,
        project,
        family.to_string(),
        converted,
        "bundled",
    )?;
    if let (Some(font), Some((license_name, license_bytes))) =
        (project.custom_font.as_mut(), bundled_font_license(font_id))
    {
        let safe_license_name = sanitize_filename(license_name);
        let family_dir = resolve_project_path(project_path)
            .join("assets")
            .join("fonts")
            .join(&font.id);
        fs::create_dir_all(&family_dir).map_err(|err| err.to_string())?;
        fs::write(family_dir.join(&safe_license_name), license_bytes)
            .map_err(|err| err.to_string())?;
        font.license_ref = Some(format!("fonts/{}/{}", font.id, safe_license_name));
    }
    Ok(())
}

fn copy_user_font_to_project(
    project_path: &str,
    project: &mut PaideiaProject,
    family: String,
    source_faces: Vec<LessonFontFace>,
    source: &str,
) -> Result<(), String> {
    let id = sanitize_filename(&family.to_ascii_lowercase().replace(' ', "-"));
    let family_dir = resolve_project_path(project_path)
        .join("assets")
        .join("fonts")
        .join(&id);
    fs::create_dir_all(&family_dir).map_err(|err| err.to_string())?;
    let mut faces = Vec::new();
    for face in source_faces {
        let bytes = fs::read(&face.asset_ref).map_err(|err| err.to_string())?;
        let file_name = sanitize_filename(&face.file_name);
        fs::write(family_dir.join(&file_name), bytes).map_err(|err| err.to_string())?;
        faces.push(LessonFontFace {
            file_name: file_name.clone(),
            asset_ref: format!("fonts/{}/{}", id, file_name),
            weight: face.weight,
            style: face.style,
        });
    }
    faces.sort_by_key(|face| (face.weight, face.style.clone()));
    let regular = faces
        .iter()
        .find(|face| face.weight == 400 && face.style == "normal")
        .or_else(|| faces.first())
        .ok_or_else(|| "Police sans fichier exploitable".to_string())?;
    project.custom_font = Some(LessonCustomFont {
        id,
        font_family: family,
        file_name: regular.file_name.clone(),
        asset_ref: regular.asset_ref.clone(),
        license_ref: None,
        source: source.to_string(),
        faces,
    });
    Ok(())
}

fn user_font_library_root(library_root: Option<&str>) -> Result<PathBuf, String> {
    let base_root = match library_root
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(value) => normalize_absolute_path(&PathBuf::from(value))?,
        None => default_user_projects_root()?,
    };
    Ok(base_root.join("fonts"))
}

fn scan_user_fonts(library_root: Option<&str>) -> Result<Vec<LessonCustomFont>, String> {
    let root = user_font_library_root(library_root)?;
    fs::create_dir_all(&root).map_err(|err| err.to_string())?;
    let mut families: HashMap<String, (String, Vec<LessonFontFace>)> = HashMap::new();
    for entry in fs::read_dir(&root)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
    {
        if !entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false) {
            continue;
        }
        let id = entry.file_name().to_string_lossy().to_string();
        for file in fs::read_dir(entry.path())
            .map_err(|err| err.to_string())?
            .filter_map(Result::ok)
        {
            let path = file.path();
            if !supported_font_path(&path)
            {
                continue;
            }
            let bytes = fs::read(&path).map_err(|err| err.to_string())?;
            let converted = match convert_font_face(file.file_name().to_string_lossy().to_string(), bytes) {
                Ok(converted) => converted,
                Err(error) => {
                    eprintln!("Police ignorée dans le catalogue utilisateur : {}", error);
                    continue;
                }
            };
            let family_entry = families
                .entry(id.clone())
                .or_insert_with(|| (converted.family.clone(), Vec::new()));
            family_entry.1.push(LessonFontFace {
                file_name: file.file_name().to_string_lossy().to_string(),
                asset_ref: path.to_string_lossy().to_string(),
                weight: converted.weight,
                style: converted.style,
            });
        }
    }
    let mut result = families
        .into_iter()
        .filter_map(|(id, (family, mut faces))| {
            faces.sort_by_key(|face| (face.weight, face.style.clone()));
            let regular = faces
                .iter()
                .find(|face| face.weight == 400 && face.style == "normal")
                .or_else(|| faces.first())?;
            Some(LessonCustomFont {
                id,
                font_family: family,
                file_name: regular.file_name.clone(),
                asset_ref: regular.asset_ref.clone(),
                license_ref: None,
                source: "user".to_string(),
                faces,
            })
        })
        .collect::<Vec<_>>();
    result.sort_by(|left, right| {
        left.font_family
            .to_lowercase()
            .cmp(&right.font_family.to_lowercase())
    });
    Ok(result)
}

fn rich_text_font_source(id: &str) -> String {
    if id.starts_with("rich-bundled-") {
        "bundled".to_string()
    } else if id.starts_with("rich-user-") {
        "user".to_string()
    } else {
        "project".to_string()
    }
}

fn rich_text_storage_id(source: &str, source_id: &str) -> String {
    sanitize_filename(&format!("rich-{}-{}", source, source_id))
}

fn scan_project_rich_text_fonts(project_path: &str) -> Result<Vec<LessonCustomFont>, String> {
    let fonts_root = resolve_project_path(project_path)
        .join("assets")
        .join("fonts");
    if !fonts_root.exists() {
        return Ok(Vec::new());
    }
    let mut result = Vec::new();
    for entry in fs::read_dir(&fonts_root)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
    {
        if !entry.file_type().map(|kind| kind.is_dir()).unwrap_or(false) {
            continue;
        }
        let id = entry.file_name().to_string_lossy().to_string();
        if !id.starts_with("rich-") {
            continue;
        }
        let mut family: Option<String> = None;
        let mut faces = Vec::new();
        let mut license_ref = None;
        for file in fs::read_dir(entry.path())
            .map_err(|err| err.to_string())?
            .filter_map(Result::ok)
        {
            let path = file.path();
            let file_name = file.file_name().to_string_lossy().to_string();
            let extension = path
                .extension()
                .and_then(|value| value.to_str())
                .unwrap_or("")
                .to_ascii_lowercase();
            if supported_font_path(&path) {
                let bytes = fs::read(&path).map_err(|err| err.to_string())?;
                let converted = convert_font_face(file_name.clone(), bytes)?;
                family.get_or_insert(converted.family.clone());
                faces.push(LessonFontFace {
                    file_name: file_name.clone(),
                    asset_ref: format!("fonts/{}/{}", id, file_name),
                    weight: converted.weight,
                    style: converted.style,
                });
            } else if matches!(extension.as_str(), "txt" | "md" | "license" | "ofl") {
                license_ref = Some(format!("fonts/{}/{}", id, file_name));
            }
        }
        faces.sort_by_key(|face| (face.weight, face.style.clone()));
        let Some(regular) = faces
            .iter()
            .find(|face| face.weight == 400 && face.style == "normal")
            .or_else(|| faces.first())
        else {
            continue;
        };
        result.push(LessonCustomFont {
            id: id.clone(),
            font_family: family.unwrap_or_else(|| id.clone()),
            file_name: regular.file_name.clone(),
            asset_ref: regular.asset_ref.clone(),
            license_ref,
            source: rich_text_font_source(&id),
            faces,
        });
    }
    result.sort_by(|left, right| {
        left.font_family
            .to_lowercase()
            .cmp(&right.font_family.to_lowercase())
    });
    Ok(result)
}

fn used_rich_text_font_ids(project: &PaideiaProject) -> HashSet<String> {
    let value = serde_json::to_value(project).unwrap_or(serde_json::Value::Null);
    let mut ids = Vec::new();
    collect_html_attribute_values(&value, "data-paideia-font-id", &mut ids);
    ids.into_iter()
        .map(|id| sanitize_filename(id.trim()))
        .filter(|id| id.starts_with("rich-") && !id.is_empty())
        .collect()
}

fn used_project_rich_text_fonts(
    project_path: &str,
    project: &PaideiaProject,
) -> Result<Vec<LessonCustomFont>, String> {
    let used_ids = used_rich_text_font_ids(project);
    Ok(scan_project_rich_text_fonts(project_path)?
        .into_iter()
        .filter(|font| used_ids.contains(&font.id))
        .collect())
}

fn store_rich_text_font(
    project_path: &str,
    family: String,
    source_id: &str,
    source: &str,
    converted: Vec<ConvertedFontFace>,
) -> Result<(), String> {
    let id = rich_text_storage_id(source, source_id);
    let family_dir = resolve_project_path(project_path)
        .join("assets")
        .join("fonts")
        .join(&id);
    fs::create_dir_all(&family_dir).map_err(|err| err.to_string())?;
    for item in converted {
        let safe_name = sanitize_filename(&item.file_name);
        fs::write(family_dir.join(&safe_name), item.bytes).map_err(|err| err.to_string())?;
    }
    if fs::read_dir(&family_dir)
        .map_err(|err| err.to_string())?
        .next()
        .is_none()
    {
        return Err(format!("Police {} sans fichier exploitable", family));
    }
    Ok(())
}

fn copy_project_font_to_rich_text_storage(
    project_path: &str,
    source_font: &LessonCustomFont,
) -> Result<(), String> {
    let source_id = source_font.id.clone();
    let id = rich_text_storage_id("project", &source_id);
    let destination = resolve_project_path(project_path)
        .join("assets")
        .join("fonts")
        .join(&id);
    fs::create_dir_all(&destination).map_err(|err| err.to_string())?;
    let project_assets = resolve_project_path(project_path).join("assets");
    let faces = if source_font.faces.is_empty() {
        vec![LessonFontFace {
            file_name: source_font.file_name.clone(),
            asset_ref: source_font.asset_ref.clone(),
            weight: 400,
            style: "normal".to_string(),
        }]
    } else {
        source_font.faces.clone()
    };
    for face in faces {
        let source_path = project_assets.join(normalize_scorm_asset_ref(&face.asset_ref));
        let safe_name = sanitize_filename(&face.file_name);
        fs::copy(source_path, destination.join(safe_name)).map_err(|err| err.to_string())?;
    }
    if let Some(license_ref) = source_font
        .license_ref
        .as_ref()
        .filter(|value| !value.trim().is_empty())
    {
        let source_path = project_assets.join(normalize_scorm_asset_ref(license_ref));
        if source_path.exists() {
            let file_name = source_path
                .file_name()
                .and_then(|value| value.to_str())
                .map(sanitize_filename)
                .unwrap_or_else(|| "LICENSE.txt".to_string());
            fs::copy(source_path, destination.join(file_name)).map_err(|err| err.to_string())?;
        }
    }
    Ok(())
}

#[tauri::command]
pub fn list_user_fonts(library_root: Option<String>) -> Result<Vec<LessonCustomFont>, String> {
    scan_user_fonts(library_root.as_deref())
}

#[tauri::command]
pub fn upload_user_font(
    file_name: String,
    file_bytes: Vec<u8>,
    library_root: Option<String>,
) -> Result<Vec<LessonCustomFont>, String> {
    let (family, converted) = convert_uploaded_font(&file_name, file_bytes)?;
    let id = sanitize_filename(&family.to_ascii_lowercase().replace(' ', "-"));
    let directory = user_font_library_root(library_root.as_deref())?.join(&id);
    fs::create_dir_all(&directory).map_err(|err| err.to_string())?;
    for face in converted {
        fs::write(
            directory.join(sanitize_filename(&face.file_name)),
            face.bytes,
        )
        .map_err(|err| err.to_string())?;
    }
    scan_user_fonts(library_root.as_deref())
}

#[tauri::command]
pub fn delete_user_font(
    font_id: String,
    library_root: Option<String>,
) -> Result<Vec<LessonCustomFont>, String> {
    let safe_id = sanitize_filename(&font_id);
    if safe_id.is_empty() {
        return Err("Police utilisateur invalide".to_string());
    }
    let directory = user_font_library_root(library_root.as_deref())?.join(&safe_id);
    if !directory.exists() {
        return Err("Police utilisateur introuvable".to_string());
    }
    fs::remove_dir_all(&directory).map_err(|err| err.to_string())?;
    scan_user_fonts(library_root.as_deref())
}

#[tauri::command]
pub fn select_user_project_font(
    project_path: String,
    font_id: String,
    library_root: Option<String>,
) -> Result<PaideiaWorkspaceState, String> {
    let descriptor = scan_user_fonts(library_root.as_deref())?
        .into_iter()
        .find(|font| font.id == font_id)
        .ok_or_else(|| "Police utilisateur introuvable".to_string())?;
    let mut project = load_project_from_path(&project_path)?;
    preserve_imported_project_font(&project_path, &mut project)?;
    copy_user_font_to_project(
        &project_path,
        &mut project,
        descriptor.font_family,
        descriptor.faces,
        "user",
    )?;
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    prune_orphaned_project_assets(&project_path, &project)?;
    load_workspace_state_from_path(&project_path)
}

#[tauri::command]
pub fn list_project_rich_text_fonts(project_path: String) -> Result<Vec<LessonCustomFont>, String> {
    scan_project_rich_text_fonts(&project_path)
}

#[tauri::command]
pub fn link_bundled_rich_text_font(
    project_path: String,
    font_id: String,
) -> Result<Vec<LessonCustomFont>, String> {
    let linked_id = rich_text_storage_id("bundled", &font_id);
    if scan_project_rich_text_fonts(&project_path)?
        .iter()
        .any(|font| font.id == linked_id)
    {
        return scan_project_rich_text_fonts(&project_path);
    }
    let (family, entries) = bundled_rich_text_font_entries(&font_id)?;
    let converted = entries
        .into_iter()
        .map(|(name, bytes)| convert_font_face(name.to_string(), bytes.to_vec()))
        .collect::<Result<Vec<_>, _>>()?;
    store_rich_text_font(
        &project_path,
        family.to_string(),
        &font_id,
        "bundled",
        converted,
    )?;
    if let Some((license_name, license_bytes)) = bundled_rich_text_font_license(&font_id) {
        let directory = resolve_project_path(&project_path)
            .join("assets")
            .join("fonts")
            .join(&linked_id);
        fs::write(
            directory.join(sanitize_filename(license_name)),
            license_bytes,
        )
        .map_err(|err| err.to_string())?;
    }
    scan_project_rich_text_fonts(&project_path)
}

#[tauri::command]
pub fn link_user_rich_text_font(
    project_path: String,
    font_id: String,
    library_root: Option<String>,
) -> Result<Vec<LessonCustomFont>, String> {
    let linked_id = rich_text_storage_id("user", &font_id);
    if scan_project_rich_text_fonts(&project_path)?
        .iter()
        .any(|font| font.id == linked_id)
    {
        return scan_project_rich_text_fonts(&project_path);
    }
    let descriptor = scan_user_fonts(library_root.as_deref())?
        .into_iter()
        .find(|font| font.id == font_id)
        .ok_or_else(|| "Police utilisateur introuvable".to_string())?;
    let family = descriptor.font_family.clone();
    let mut converted = Vec::new();
    for face in descriptor.faces {
        converted.push(ConvertedFontFace {
            family: family.clone(),
            file_name: face.file_name,
            bytes: fs::read(&face.asset_ref).map_err(|err| err.to_string())?,
            weight: face.weight,
            style: face.style,
        });
    }
    store_rich_text_font(&project_path, family, &font_id, "user", converted)?;
    scan_project_rich_text_fonts(&project_path)
}

#[tauri::command]
pub fn link_project_rich_text_font(project_path: String) -> Result<Vec<LessonCustomFont>, String> {
    let project = load_project_from_path(&project_path)?;
    let source_font = project
        .custom_font
        .as_ref()
        .ok_or_else(|| "Aucune police de projet disponible".to_string())?;
    let linked_id = if source_font.id.starts_with("rich-") { source_font.id.clone() } else { rich_text_storage_id("project", &source_font.id) };
    if scan_project_rich_text_fonts(&project_path)?
        .iter()
        .any(|font| font.id == linked_id)
    {
        return scan_project_rich_text_fonts(&project_path);
    }
    copy_project_font_to_rich_text_storage(&project_path, source_font)?;
    scan_project_rich_text_fonts(&project_path)
}

fn preserve_imported_project_font(project_path: &str, project: &mut PaideiaProject) -> Result<(), String> {
    let Some(font) = project.custom_font.clone().filter(|font| font.source == "project") else { return Ok(()); };
    if project.imported_fonts.iter().any(|existing| existing.id == font.id
        || existing.id == rich_text_storage_id("project", &font.id)) { return Ok(()); }
    copy_project_font_to_rich_text_storage(project_path, &font)?;
    let id = rich_text_storage_id("project", &font.id);
    let stored = scan_project_rich_text_fonts(project_path)?.into_iter().find(|entry| entry.id == id)
        .ok_or_else(|| "Police de projet introuvable après conservation".to_string())?;
    project.imported_fonts.push(stored);
    Ok(())
}

#[tauri::command]
pub fn select_imported_project_font(project_path: String, font_id: String) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    preserve_imported_project_font(&project_path, &mut project)?;
    let font = project.imported_fonts.iter().find(|font| font.id == font_id).cloned()
        .ok_or_else(|| "Police absente du catalogue du projet".to_string())?;
    let before = project.custom_font.clone();
    project.custom_font = Some(font);
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    append_standard_event(&project_path, &project, "project", &project.id, "project.font.selected", "Police importée sélectionnée", "assets/fonts", serde_json::json!({ "fontId": font_id }), serde_json::json!({ "before": before, "after": project.custom_font }))?;
    load_workspace_state_from_path(&project_path)
}

fn reset_removed_font_in_rich_text(project: &mut PaideiaProject, font_id: &str) -> Result<(), String> {
    let family = format!("PaideiaRichFont-{}", font_id);
    let tags = regex::Regex::new(r"<[^>]+>").map_err(|error| error.to_string())?;
    let styles = regex::Regex::new(r#"(?i)(\bstyle\s*=\s*)(?:"([^"]*)"|'([^']*)')"#).map_err(|error| error.to_string())?;
    let attribute = regex::Regex::new(&format!(r#"\s+data-paideia-font-id\s*=\s*(?:"{}"|'{}')"#, regex::escape(font_id), regex::escape(font_id)))
        .map_err(|error| error.to_string())?;
    fn visit(value: &mut serde_json::Value, family: &str, tags: &regex::Regex, styles: &regex::Regex, attribute: &regex::Regex) {
        match value {
            serde_json::Value::String(text) if text == family => *text = "__default__".to_string(),
            serde_json::Value::String(text) if text.contains('<') && (text.contains(family) || attribute.is_match(text)) => {
                *text = tags.replace_all(text, |tag: &regex::Captures| {
                    let cleaned = attribute.replace_all(&tag[0], "");
                    styles.replace_all(&cleaned, |style: &regex::Captures| {
                        let quote = if style.get(2).is_some() { "\"" } else { "'" };
                        let content = style.get(2).or_else(|| style.get(3)).unwrap().as_str();
                        let encoded_content = content.replace("&quot;", "\u{e000}");
                        let declarations = encoded_content.split(';').map(|declaration| {
                            if let Some((name, value)) = declaration.split_once(':') {
                                if name.trim().eq_ignore_ascii_case("font-family") && value.split(',').any(|font| font.trim().replace("\u{e000}", "").trim_matches(['\"', '\'']).trim() == family) {
                                    return format!("{}:var(--lesson-custom-font, Inter, Arial, sans-serif)", name);
                                }
                            }
                            declaration.to_string()
                        }).collect::<Vec<_>>().join(";").replace("\u{e000}", "&quot;");
                        format!("{}{}{}{}", &style[1], quote, declarations, quote)
                    }).into_owned()
                }).into_owned();
            }
            serde_json::Value::Array(values) => values.iter_mut().for_each(|value| visit(value, family, tags, styles, attribute)),
            serde_json::Value::Object(values) => values.values_mut().for_each(|value| visit(value, family, tags, styles, attribute)),
            _ => {}
        }
    }
    let mut value = serde_json::to_value(&*project).map_err(|error| error.to_string())?;
    visit(&mut value, &family, &tags, &styles, &attribute);
    *project = serde_json::from_value(value).map_err(|error| error.to_string())?;
    Ok(())
}

#[tauri::command]
pub fn delete_imported_project_font(project_path: String, font_id: String) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let linked_id = if font_id.starts_with("rich-") { font_id.clone() } else { rich_text_storage_id("project", &font_id) };
    preserve_imported_project_font(&project_path, &mut project)?;
    if !project.imported_fonts.iter().any(|font| font.id == font_id || font.id == linked_id) {
        return Err("Police absente du catalogue du projet".to_string());
    }
    reset_removed_font_in_rich_text(&mut project, &linked_id)?;
    project.imported_fonts.retain(|font| font.id != font_id && font.id != linked_id);
    if project.custom_font.as_ref().is_some_and(|font| font.id == font_id || font.id == linked_id) {
        install_bundled_font(&project_path, &mut project, "inter")?;
    }
    touch_project(&mut project);
    save_project_to_path(&project_path, &project)?;
    let fonts_root = resolve_project_path(&project_path).join("assets/fonts");
    let deleted_directory = fonts_root.join(sanitize_filename(&linked_id));
    if deleted_directory.exists() {
        let canonical_root = fs::canonicalize(&fonts_root).map_err(|error| error.to_string())?;
        let canonical_deleted = fs::canonicalize(&deleted_directory).map_err(|error| error.to_string())?;
        if !canonical_deleted.starts_with(&canonical_root) || canonical_deleted == canonical_root {
            return Err("Dossier de police hors du projet".into());
        }
        fs::remove_dir_all(&canonical_deleted).map_err(|error| error.to_string())?;
    }
    prune_orphaned_project_assets(&project_path, &project)?;
    append_standard_event(&project_path, &project, "project", &project.id, "project.font.deleted", "Police de projet supprimée", "assets/fonts", serde_json::json!({ "fontId": font_id }), serde_json::json!({ "defaultFont": project.custom_font }))?;
    load_workspace_state_from_path(&project_path)
}

