#[tauri::command]
pub fn upload_situational_dialogue_character_asset(
    project_path: String,
    block_id: String,
    character_name: String,
    pose_id: String,
    file_name: String,
    file_bytes: Vec<u8>,
) -> Result<String, String> {
    validate_user_image_file(&file_name, &file_bytes)?;
    let root = resolve_project_path(&project_path);
    let assets_dir = root.join("assets");
    fs::create_dir_all(&assets_dir).map_err(|err| err.to_string())?;

    let character_slug = sanitize_filename(&character_name)
        .trim_matches('-')
        .trim_matches('_')
        .to_string();
    let character_slug = if character_slug.is_empty() {
        "character".to_string()
    } else {
        character_slug
    };
    let pose_slug = sanitize_filename(&pose_id)
        .trim_matches('-')
        .trim_matches('_')
        .to_string();
    let pose_slug = if pose_slug.is_empty() {
        "pose".to_string()
    } else {
        pose_slug
    };
    let extension = Path::new(&file_name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("png")
        .to_ascii_lowercase();
    let safe_extension = if matches!(extension.as_str(), "gif" | "jpg" | "jpeg" | "png" | "webp") {
        extension
    } else {
        "png".to_string()
    };
    let stored_ref = format!(
        "situational-dialogue/{}/characters/{}/{}.{}",
        sanitize_filename(&block_id),
        character_slug,
        pose_slug,
        safe_extension
    );
    let asset_path = assets_dir.join(&stored_ref);
    if let Some(parent) = asset_path.parent() {
        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
    }
    fs::write(&asset_path, file_bytes).map_err(|err| err.to_string())?;

    Ok(stored_ref)
}

const HTML_PACKAGE_MAX_FILES: usize = 500;
const HTML_PACKAGE_MAX_BYTES: u64 = 250 * 1024 * 1024;
const HTML_PACKAGE_MAX_FILE_BYTES: u64 = 100 * 1024 * 1024;

#[derive(Debug)]
struct ImportedHtmlPackage {
    content_html: String,
    asset_root: Option<String>,
    entry_file: Option<String>,
    package_name: Option<String>,
    asset_refs: Vec<String>,
    staged_directory: Option<PathBuf>,
}

#[tauri::command]
pub fn import_html_activity_package(
    project_path: String,
    page_id: String,
    block_id: String,
    file_name: String,
    file_bytes: Vec<u8>,
) -> Result<PaideiaWorkspaceState, String> {
    let mut project = load_project_from_path(&project_path)?;
    let root = resolve_project_path(&project_path);
    let assets_dir = root.join("assets");
    fs::create_dir_all(&assets_dir).map_err(|err| err.to_string())?;

    let extension = Path::new(&file_name)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    let imported = match extension.as_str() {
        "html" | "htm" => ImportedHtmlPackage {
            content_html: decode_html_bytes(&file_bytes)?,
            asset_root: None,
            entry_file: None,
            package_name: Some(file_name.clone()),
            asset_refs: Vec::new(),
            staged_directory: None,
        },
        "zip" => stage_html_zip_package(&assets_dir, &block_id, &file_name, &file_bytes)?,
        _ => return Err("Format refusÃ©. Importez un fichier .html, .htm ou .zip.".to_string()),
    };

    let page = project
        .course
        .modules
        .iter_mut()
        .flat_map(|module| module.chapters.iter_mut())
        .flat_map(|chapter| chapter.pages.iter_mut())
        .find(|page| page.id == page_id)
        .ok_or_else(|| "Target page not found".to_string())?;
    let block = page
        .blocks
        .iter_mut()
        .find(|block| block.id == block_id)
        .ok_or_else(|| "Target block not found".to_string())?;
    if block.block_type != "html-custom" {
        cleanup_staged_html_package(imported.staged_directory.as_deref());
        return Err(
            "L'import HTML est rÃ©servÃ© Ã  une activitÃ© HTML personnalisÃ©e.".to_string(),
        );
    }

    let before = block.clone();
    let previous_asset_root = block.html_asset_root.clone();
    block.content_html = Some(imported.content_html.clone());
    block.html_asset_root = imported.asset_root.clone();
    block.html_entry_file = imported.entry_file.clone();
    block.html_package_name = imported.package_name.clone();
    block.asset_refs = imported.asset_refs.clone();
    let after = block.clone();

    touch_project(&mut project);
    if let Err(error) = save_project_to_path(&project_path, &project) {
        cleanup_staged_html_package(imported.staged_directory.as_deref());
        return Err(error);
    }

    if let Some(previous_root) = previous_asset_root {
        remove_previous_html_package(
            &project_path,
            &project,
            &assets_dir,
            &previous_root,
            imported.asset_root.as_deref(),
        );
    }

    let event_target_path = imported
        .entry_file
        .as_deref()
        .map(|value| format!("assets/{}", value))
        .unwrap_or_else(|| format!("content/blocks/{}.json", block_id));
    append_standard_event(
        &project_path,
        &project,
        "block",
        &block_id,
        "block.html_package_imported",
        "Ressources HTML importÃ©es",
        &event_target_path,
        serde_json::json!({
            "fileName": file_name,
            "entryFile": imported.entry_file,
            "assetRoot": imported.asset_root,
            "assetCount": imported.asset_refs.len()
        }),
        serde_json::json!({ "before": before, "after": after }),
    )?;

    load_workspace_state_from_path(&project_path)
}

fn decode_html_bytes(bytes: &[u8]) -> Result<String, String> {
    let bytes = bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes);
    String::from_utf8(bytes.to_vec())
        .map_err(|_| "Le fichier HTML doit Ãªtre encodÃ© en UTF-8.".to_string())
}

fn stage_html_zip_package(
    assets_dir: &Path,
    block_id: &str,
    file_name: &str,
    file_bytes: &[u8],
) -> Result<ImportedHtmlPackage, String> {
    let mut archive = ZipArchive::new(Cursor::new(file_bytes))
        .map_err(|err| format!("ZIP HTML invalide : {err}"))?;
    if archive.len() > HTML_PACKAGE_MAX_FILES {
        return Err(format!(
            "Le paquet HTML contient trop de fichiers (maximum {}).",
            HTML_PACKAGE_MAX_FILES
        ));
    }

    let package_stem = Path::new(file_name)
        .file_stem()
        .and_then(|value| value.to_str())
        .map(sanitize_filename)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "html-package".to_string());
    let unique_suffix = Utc::now().timestamp_millis();
    let folder_name = format!(
        "{}-{}-{}",
        package_stem,
        sanitize_filename(block_id),
        unique_suffix
    );
    let html_root = assets_dir.join("html");
    fs::create_dir_all(&html_root).map_err(|err| err.to_string())?;
    let staging_dir = html_root.join(format!(".staging-{folder_name}"));
    let final_dir = html_root.join(&folder_name);
    if staging_dir.exists() {
        fs::remove_dir_all(&staging_dir).map_err(|err| err.to_string())?;
    }
    fs::create_dir_all(&staging_dir).map_err(|err| err.to_string())?;

    let result = (|| {
        let mut extracted_paths = Vec::<String>::new();
        let mut html_entries = Vec::<String>::new();
        let mut total_bytes = 0_u64;

        for index in 0..archive.len() {
            let mut entry = archive.by_index(index).map_err(|err| err.to_string())?;
            let enclosed = entry
                .enclosed_name()
                .ok_or_else(|| format!("Chemin ZIP dangereux refusÃ© : {}", entry.name()))?
                .to_path_buf();
            if enclosed.as_os_str().is_empty() {
                continue;
            }
            if entry
                .unix_mode()
                .map(|mode| mode & 0o170000 == 0o120000)
                .unwrap_or(false)
            {
                return Err(format!(
                    "Lien symbolique refusÃ© dans le paquet HTML : {}",
                    entry.name()
                ));
            }
            let extension = enclosed
                .extension()
                .and_then(|value| value.to_str())
                .unwrap_or_default()
                .to_ascii_lowercase();
            if matches!(
                extension.as_str(),
                "exe" | "dll" | "msi" | "bat" | "cmd" | "com" | "scr" | "ps1" | "lnk"
            ) {
                return Err(format!(
                    "Fichier exÃ©cutable refusÃ© dans le paquet HTML : {}",
                    entry.name()
                ));
            }
            if entry.size() > HTML_PACKAGE_MAX_FILE_BYTES {
                return Err(format!(
                    "Fichier trop volumineux dans le paquet HTML : {}",
                    entry.name()
                ));
            }
            total_bytes = total_bytes.saturating_add(entry.size());
            if total_bytes > HTML_PACKAGE_MAX_BYTES {
                return Err("Le paquet HTML dÃ©compressÃ© dÃ©passe 250 Mo.".to_string());
            }

            let destination = staging_dir.join(&enclosed);
            if entry.is_dir() {
                fs::create_dir_all(&destination).map_err(|err| err.to_string())?;
                continue;
            }
            if let Some(parent) = destination.parent() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
            let mut output = fs::File::create(&destination).map_err(|err| err.to_string())?;
            std::io::copy(&mut entry, &mut output).map_err(|err| err.to_string())?;

            let relative = enclosed.to_string_lossy().replace('\\', "/");
            if matches!(extension.as_str(), "html" | "htm") {
                html_entries.push(relative.clone());
            }
            extracted_paths.push(relative);
        }

        let entry_relative = select_html_package_entry(&html_entries)?;
        let content_html = decode_html_bytes(
            &fs::read(staging_dir.join(&entry_relative)).map_err(|err| err.to_string())?,
        )?;
        fs::rename(&staging_dir, &final_dir).map_err(|err| err.to_string())?;

        let entry_parent = Path::new(&entry_relative)
            .parent()
            .filter(|value| !value.as_os_str().is_empty())
            .map(|value| value.to_string_lossy().replace('\\', "/"));
        let asset_root = match entry_parent {
            Some(parent) => format!("html/{folder_name}/{parent}"),
            None => format!("html/{folder_name}"),
        };
        let entry_file = format!("html/{folder_name}/{entry_relative}");
        let mut asset_refs = extracted_paths
            .into_iter()
            .map(|relative| format!("html/{folder_name}/{relative}"))
            .collect::<Vec<_>>();
        asset_refs.sort();
        asset_refs.dedup();

        Ok(ImportedHtmlPackage {
            content_html,
            asset_root: Some(asset_root),
            entry_file: Some(entry_file),
            package_name: Some(file_name.to_string()),
            asset_refs,
            staged_directory: Some(final_dir),
        })
    })();

    if result.is_err() {
        cleanup_staged_html_package(Some(&staging_dir));
    }
    result
}

fn select_html_package_entry(entries: &[String]) -> Result<String, String> {
    let mut index_entries = entries
        .iter()
        .filter(|entry| {
            Path::new(entry)
                .file_name()
                .and_then(|value| value.to_str())
                .map(|value| {
                    matches!(
                        value.to_ascii_lowercase().as_str(),
                        "index.html" | "index.htm"
                    )
                })
                .unwrap_or(false)
        })
        .cloned()
        .collect::<Vec<_>>();
    index_entries.sort_by_key(|entry| (entry.matches('/').count(), entry.len()));
    if let Some(entry) = index_entries.first() {
        return Ok(entry.clone());
    }
    if entries.len() == 1 {
        return Ok(entries[0].clone());
    }
    if entries.is_empty() {
        return Err("Le ZIP ne contient aucun fichier HTML ou HTM.".to_string());
    }
    Err("Plusieurs fichiers HTML ont Ã©tÃ© trouvÃ©s sans index.html. Ajoutez un point d'entrÃ©e index.html.".to_string())
}

fn cleanup_staged_html_package(path: Option<&Path>) {
    if let Some(path) = path.filter(|path| path.exists()) {
        let _ = fs::remove_dir_all(path);
    }
}

fn remove_previous_html_package(
    project_path: &str,
    project: &PaideiaProject,
    assets_dir: &Path,
    previous_root: &str,
    next_root: Option<&str>,
) {
    let normalized = normalize_scorm_asset_ref(previous_root);
    if !normalized.starts_with("html/")
        || next_root.map(normalize_scorm_asset_ref).as_deref() == Some(&normalized)
    {
        return;
    }
    let package_folder = normalized.split('/').take(2).collect::<Vec<_>>().join("/");
    if package_folder.starts_with("html/") {
        let package_prefix = format!("{package_folder}/");
        if project_asset_refs(project_path, project).iter().any(|asset_ref| {
            asset_ref == &package_folder || asset_ref.starts_with(&package_prefix)
        }) {
            return;
        }
        let _ = fs::remove_dir_all(assets_dir.join(package_folder));
    }
}

#[tauri::command]
pub fn upload_collection_image(
    library_root: String,
    collection_name: String,
    source_path: String,
) -> Result<String, String> {
    let root = PathBuf::from(library_root);
    let source = PathBuf::from(source_path);
    if !source.is_file() {
        return Err("Image de collection introuvable".to_string());
    }

    let extension = source
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !matches!(extension.as_str(), "gif" | "jpg" | "jpeg" | "png" | "webp") {
        return Err("Format d'image de collection non pris en charge".to_string());
    }

    let collection_slug = sanitize_filename(&collection_name)
        .trim_matches('-')
        .trim_matches('_')
        .to_string();
    let collection_slug = if collection_slug.is_empty() {
        "collection".to_string()
    } else {
        collection_slug
    };
    let file_name = format!(
        "{}-{}.{}",
        collection_slug,
        Utc::now().format("%Y%m%d%H%M%S%3f"),
        extension
    );
    let target_dir = root.join("assets").join("images").join("collections");
    fs::create_dir_all(&target_dir).map_err(|err| err.to_string())?;
    let target = target_dir.join(file_name);
    fs::copy(&source, &target).map_err(|err| err.to_string())?;

    Ok(target.to_string_lossy().to_string())
}

fn append_standard_event(
    project_path: &str,
    project: &PaideiaProject,
    aggregate_type: &str,
    aggregate_id: &str,
    event_type: &str,
    label: &str,
    target_path: &str,
    payload: serde_json::Value,
    diff: serde_json::Value,
) -> Result<(), String> {
    const MAX_AUDIT_FIELD_BYTES: usize = 32 * 1024;

    fn compact_audit_field(value: serde_json::Value, max_bytes: usize) -> serde_json::Value {
        let serialized_bytes = serde_json::to_vec(&value)
            .map(|bytes| bytes.len())
            .unwrap_or(0);
        if serialized_bytes <= max_bytes {
            return value;
        }
        serde_json::json!({
            "omitted": true,
            "reason": "audit-field-too-large",
            "originalBytes": serialized_bytes
        })
    }

    let event = EventRecord {
        id: format!("evt_{}", compact_timestamp()),
        project_id: project.id.clone(),
        aggregate_type: aggregate_type.to_string(),
        aggregate_id: aggregate_id.to_string(),
        event_type: event_type.to_string(),
        actor_user_id: "local-user".into(),
        actor_role: "author".into(),
        timestamp: now_iso(),
        machine: "local".into(),
        label: label.to_string(),
        target_path: target_path.to_string(),
        payload: compact_audit_field(payload, MAX_AUDIT_FIELD_BYTES),
        diff: compact_audit_field(diff, MAX_AUDIT_FIELD_BYTES),
    };
    append_event_record(project_path, &event)
}

fn next_numbered_id<'a>(prefix: &str, existing_ids: impl Iterator<Item = &'a str>) -> String {
    let expected_prefix = format!("{prefix}_");
    let existing_ids = existing_ids.collect::<HashSet<_>>();
    let mut ordinal = existing_ids
        .iter()
        .filter_map(|id| id.strip_prefix(&expected_prefix))
        .filter_map(|suffix| suffix.parse::<usize>().ok())
        .max()
        .unwrap_or(0)
        + 1;

    loop {
        let candidate = format!("{prefix}_{ordinal:02}");
        if !existing_ids.contains(candidate.as_str()) {
            return candidate;
        }
        ordinal += 1;
    }
}

fn normalize_course_background_color(value: &str) -> String {
    safe_css_color(value, "#FFFFFF").to_ascii_uppercase()
}

fn relative_luminance(value: &str) -> f64 {
    let color = safe_css_color(value, "#FFFFFF");
    let channel = |offset: usize| {
        let raw = u8::from_str_radix(&color[offset..offset + 2], 16).unwrap_or(255) as f64 / 255.0;
        if raw <= 0.03928 {
            raw / 12.92
        } else {
            ((raw + 0.055) / 1.055).powf(2.4)
        }
    };
    0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5)
}

fn contrast_ratio(first: &str, second: &str) -> f64 {
    let first_luminance = relative_luminance(first);
    let second_luminance = relative_luminance(second);
    let lighter = first_luminance.max(second_luminance);
    let darker = first_luminance.min(second_luminance);
    (lighter + 0.05) / (darker + 0.05)
}

fn resolve_contrasting_text_color(preferred: &str, background: &str) -> String {
    let preferred = safe_css_color(preferred, "#222222").to_ascii_uppercase();
    let background = safe_css_color(background, "#FFFFFF").to_ascii_uppercase();
    if contrast_ratio(&preferred, &background) >= 4.5 {
        return preferred;
    }

    if contrast_ratio("#FFFFFF", &background) >= contrast_ratio("#222222", &background) {
        "#FFFFFF".to_string()
    } else {
        "#222222".to_string()
    }
}

fn resolve_contextual_text_color(preferred: &str, background: &str) -> String {
    let preferred = safe_css_color(preferred, "#222222").to_ascii_uppercase();
    let background = safe_css_color(background, "#FFFFFF").to_ascii_uppercase();
    if contrast_ratio(&preferred, &background) >= 1.5 {
        return preferred;
    }
    resolve_contrasting_text_color(&preferred, &background)
}

fn situational_dialogue_decor_colors(background: &str) -> Option<(String, String)> {
    let trimmed = background.trim();
    if trimmed.len() != 7
        || !trimmed.starts_with('#')
        || !trimmed.chars().skip(1).all(|item| item.is_ascii_hexdigit())
    {
        return None;
    }
    let channels = [1usize, 3, 5]
        .map(|offset| u8::from_str_radix(&trimmed[offset..offset + 2], 16).ok())
        .into_iter()
        .collect::<Option<Vec<_>>>()?;
    let luminance =
        (0.2126 * channels[0] as f64 + 0.7152 * channels[1] as f64 + 0.0722 * channels[2] as f64)
            / 255.0;
    let target = if luminance <= 0.5 { 255.0 } else { 0.0 };
    let mix = |ratio: f64, alpha: f64| {
        let mixed = channels
            .iter()
            .map(|channel| (*channel as f64 + (target - *channel as f64) * ratio).round() as u8)
            .collect::<Vec<_>>();
        format!("rgba({}, {}, {}, {})", mixed[0], mixed[1], mixed[2], alpha)
    };
    Some((
        mix(if luminance <= 0.5 { 0.32 } else { 0.1 }, 0.73),
        mix(if luminance <= 0.5 { 0.58 } else { 0.34 }, 0.52),
    ))
}

fn next_available_module_id(project: &PaideiaProject) -> String {
    next_numbered_id(
        "mod",
        project
            .course
            .modules
            .iter()
            .map(|module| module.id.as_str()),
    )
}

fn next_available_chapter_id(project: &PaideiaProject) -> String {
    next_numbered_id(
        "chapter",
        project
            .course
            .modules
            .iter()
            .flat_map(|module| module.chapters.iter())
            .map(|chapter| chapter.id.as_str()),
    )
}

fn next_available_page_id(project: &PaideiaProject) -> String {
    next_numbered_id(
        "page",
        project
            .course
            .modules
            .iter()
            .flat_map(|module| module.chapters.iter())
            .flat_map(|chapter| chapter.pages.iter())
            .map(|page| page.id.as_str()),
    )
}

fn unique_chapter_index(module: &PaideiaModule, chapter_id: &str) -> Result<usize, String> {
    let mut matching_indexes = module
        .chapters
        .iter()
        .enumerate()
        .filter_map(|(index, chapter)| (chapter.id == chapter_id).then_some(index));
    let first_index = matching_indexes
        .next()
        .ok_or_else(|| "Target chapter not found".to_string())?;

    if matching_indexes.next().is_some() {
        return Err(format!(
            "Identifiant de chapitre dupliqué détecté ({chapter_id}). L’opération a été annulée afin de protéger le contenu de la leçon."
        ));
    }

    Ok(first_index)
}

fn next_available_block_id(project: &PaideiaProject) -> String {
    let existing_ids: HashSet<&str> = project
        .course
        .modules
        .iter()
        .flat_map(|module| module.chapters.iter())
        .flat_map(|chapter| chapter.pages.iter())
        .flat_map(|page| page.blocks.iter())
        .map(|block| block.id.as_str())
        .collect();
    loop {
        // A block identity must never be recycled after deletion. Several editor
        // and preview states are deliberately keyed by block id; reusing an old
        // ordinal could therefore attach stale state to an unrelated activity.
        let candidate = new_block_id_candidate();
        if !existing_ids.contains(candidate.as_str()) {
            return candidate;
        }
    }
}

