fn image_text_activity_export_css() -> String {
    let source = include_str!("../../src/components/activities/ImageTextActivity/ImageTextActivity.module.css");
    let globals = regex::Regex::new(r":global\(([^()]*)\)").unwrap().replace_all(source, "$1");
    regex::Regex::new(r"\.(activity|copy|frame|shell)\b")
        .unwrap().replace_all(&globals, ".paideia-image-text-$1").into_owned()
}

