    #[test]
    fn resource_character_dates_are_independent_and_survive_noop_saves() {
        let root = std::env::temp_dir().join(format!("paideia-character-dates-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(&root).unwrap();
        let mut metadata: UserCharacterBankFile = serde_json::from_value(serde_json::json!({"version":1,"characters":[
            {"id":"a","name":"Alpha","role":null,"description":null,"previewRef":null,"resourceModifiedAt":1000},
            {"id":"b","name":"Beta","role":null,"description":null,"previewRef":null,"resourceModifiedAt":2000}
        ]})).unwrap();
        fs::write(root.join("character-bank.json"), serde_json::to_vec(&metadata).unwrap()).unwrap();
        write_user_character_bank_metadata(&root, &metadata).unwrap();
        let unchanged = read_user_character_bank_metadata(&root).unwrap();
        assert_eq!(unchanged.characters, metadata.characters);
        metadata.characters[0].name = Some("Renamed".into());
        metadata.characters[0].resource_modified_at = None;
        write_user_character_bank_metadata(&root, &metadata).unwrap();
        let changed = read_user_character_bank_metadata(&root).unwrap();
        assert!(changed.characters[0].resource_modified_at.unwrap() > 2000);
        assert_eq!(changed.characters[1].resource_modified_at, Some(2000));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn scorm_course_exit_compositions_keep_rich_text_and_button_order() {
        let mut block = sample_quiz_block();
        block.block_type = "course-exit".to_string();
        block.summary = "Quitter".to_string();
        block.content_html = Some("<p>Texte d'accompagnement</p>".to_string());
        block.media_layout = Some("button-left-text-right".to_string());

        let rendered =
            render_scorm_block(&block, "course_exit", None, 36, None, "#222222", "#FFFFFF");
        assert!(rendered.contains("data-course-exit-layout=\"button-left-text-right\""));
        assert!(rendered.contains("continue-block course-exit-block course-exit-has-text"));
        assert!(rendered.contains("Texte d'accompagnement"));
        let button_index = rendered.find("<button").expect("course exit button");
        let copy_index = rendered.find("course-exit-copy").expect("course exit copy");
        assert!(button_index < copy_index);

        block.media_layout = Some("unknown-layout".to_string());
        let legacy =
            render_scorm_block(&block, "course_exit", None, 36, None, "#222222", "#FFFFFF");
        assert!(!legacy.contains("course-exit-copy"));
        assert!(legacy.contains("continue-block course-exit-block"));
        assert!(legacy.contains("class=\"continue-label\">Quitter</span>"));

        block.block_type = "continue".to_string();
        let continue_block =
            render_scorm_block(&block, "continue", None, 36, None, "#222222", "#FFFFFF");
        assert!(continue_block.contains("continue-block continue-navigation-block"));
        assert!(!continue_block.contains("course-exit-block"));
    }

