    #[test]
    fn lesson_rename_preserves_content_media_settings_and_snapshots() {
        let parent = std::env::temp_dir().join(format!("paideia-rename-{}", uuid::Uuid::new_v4()));
        let root = parent.join("original-20260928120000000");
        fs::create_dir_all(&root).unwrap();
        save_project_to_path(&root.to_string_lossy(), &sample_project(vec![])).unwrap();
        let mut original_meta: serde_json::Value = serde_json::from_slice(&fs::read(root.join("project.json")).unwrap()).unwrap();
        original_meta["futureSetting"] = serde_json::json!({ "preserve": true });
        fs::write(root.join("project.json"), serde_json::to_vec(&original_meta).unwrap()).unwrap();
        let original_course: serde_json::Value = serde_json::from_slice(&fs::read(root.join("content/course.json")).unwrap()).unwrap();
        let fixtures = [
            ("assets/video/unreferenced.mp4", "keep video"),
            ("assets/subtitles/captions.srt", "1\n00:00:00,000 --> 00:00:01,000\nÉcran"),
            ("assets/html/package/index.html", "<img src='image.png'>"),
            ("content/blocks/untouched.json", "{\"text\":\"&Eacute;\"}"),
            ("snapshots/.asset-store/ab/abcdef", "historic media"),
        ];
        for (relative, content) in fixtures {
            let path = root.join(relative);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, content.as_bytes()).unwrap();
        }
        let renamed = rename_project_title_impl(&root.to_string_lossy(), "Nouveau titre").unwrap();
        let next = PathBuf::from(&renamed.project_path);
        assert!(!root.exists());
        assert!(next.file_name().unwrap().to_string_lossy().starts_with("nouveau-titre-20260928120000000"));
        let meta: serde_json::Value = serde_json::from_slice(&fs::read(next.join("project.json")).unwrap()).unwrap();
        original_meta["title"] = serde_json::json!(renamed.title);
        original_meta["updatedAt"] = serde_json::json!(renamed.updated_at);
        original_meta["courseCoverTitleHtml"] = serde_json::json!(renamed.course_cover_title_html);
        assert_eq!(meta, original_meta);
        let mut expected_course = original_course;
        expected_course["title"] = serde_json::json!(renamed.title);
        let course: serde_json::Value = serde_json::from_slice(&fs::read(next.join("content/course.json")).unwrap()).unwrap();
        assert_eq!(course, expected_course);
        for (relative, content) in fixtures {
            assert_eq!(fs::read(next.join(relative)).unwrap(), content.as_bytes());
        }
        fs::remove_dir_all(parent).unwrap();
    }

