    #[test]
    fn lesson_keywords_persist_in_metadata_and_library() {
        let root = std::env::temp_dir().join(format!("paideia-keywords-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(root.join("content")).unwrap();
        std::fs::write(root.join("project.json"), serde_json::to_vec(&serde_json::json!({
            "id":"keywords-test", "slug":"keywords-test", "title":"Leçon test", "description":"",
            "createdAt":"2026-10-03", "updatedAt":"2026-10-03", "createdBy":"test",
            "defaultLocale":"fr", "locales":["fr"], "status":"draft",
            "currentVersion":"v1", "rootCourseId":"course"
        })).unwrap()).unwrap();
        std::fs::write(root.join("content/course.json"), br#"{"id":"course","title":"Test","modules":[]}"#).unwrap();
        let path = root.to_string_lossy().into_owned();
        let state = super::update_project_keywords(path.clone(), vec![
            " réglementation ".into(), "Réglementation".into(), "temps de travail".into()
        ]).unwrap();
        assert_eq!(state.project.keywords, ["réglementation", "temps de travail"]);
        let metadata: serde_json::Value = serde_json::from_slice(&std::fs::read(root.join("project.json")).unwrap()).unwrap();
        assert_eq!(metadata["keywords"], serde_json::json!(["réglementation", "temps de travail"]));
        let entry = super::build_library_project_entry(&root).unwrap();
        assert_eq!(entry.keywords, state.project.keywords);
        let archive = root.with_extension("paideia");
        super::zip_directory_to_file(&root, &archive).unwrap();
        let archive_state = super::update_project_keywords(archive.to_string_lossy().into_owned(), vec!["formation".into()]).unwrap();
        assert_eq!(archive_state.project.keywords, ["formation"]);
        let archive_entry = super::build_library_archive_entry(&archive).unwrap();
        assert_eq!(archive_entry.keywords, ["formation"]);
        let extracted = root.with_extension("extracted");
        super::extract_paideia_archive_to(&std::fs::read(&archive).unwrap(), &extracted).unwrap();
        assert_eq!(super::load_project_from_path(&extracted.to_string_lossy()).unwrap().keywords, ["formation"]);
        std::fs::remove_dir_all(extracted).unwrap();
        std::fs::remove_file(archive).unwrap();
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn user_preferences_round_trip_preserves_whisper_paths() {
        let root = std::env::temp_dir().join(format!(
            "paideia-whisper-preferences-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        let preferences = UserPreferencesFile {
            version: default_user_preferences_version(),
            app_language: Some("fr".to_string()),
            assistant_address_form: Some("feminine".to_string()),
            activity_favorites: Vec::new(),
            activity_favorites_limit: Some(10),
            library_project_favorites: Vec::new(),
            library_collection_overrides: HashMap::from([("lesson".into(), "SSI".into())]),
            custom_library_collections: vec!["SSI".into()],
            library_collection_images: HashMap::from([("SSI".into(), "cover.webp".into())]),
            library_collection_colors: HashMap::new(),
            library_keyword_catalog: vec!["réglementation".into(), "temps de travail".into()],
            library_pinned_keywords: vec!["réglementation".into()],
            library_recent_keywords: vec!["temps de travail".into(), "réglementation".into()],
            hidden_library_collection_tiles: Vec::new(),
            ffmpeg_path: Some(r"C:\ffmpeg\bin\ffmpeg.exe".to_string()),
            ffprobe_path: Some(r"C:\ffmpeg\bin\ffprobe.exe".to_string()),
            whisper_cli_path: Some(r"C:\whisper\bin\whisper-cli.exe".to_string()),
            whisper_small_model_path: Some(r"C:\whisper\models\ggml-small.bin".to_string()),
            whisper_medium_model_path: Some(r"C:\whisper\models\ggml-medium.bin".to_string()),
        };

        write_user_preferences_metadata(&root, &preferences)
            .expect("Whisper preferences should be written");
        let restored =
            read_user_preferences_metadata(&root).expect("Whisper preferences should be restored");

        assert_eq!(restored.whisper_cli_path, preferences.whisper_cli_path);
        assert_eq!(restored.library_collection_overrides, preferences.library_collection_overrides);
        assert_eq!(restored.custom_library_collections, preferences.custom_library_collections);
        assert_eq!(restored.library_collection_images, preferences.library_collection_images);
        assert_eq!(restored.library_keyword_catalog, preferences.library_keyword_catalog);
        assert_eq!(restored.library_pinned_keywords, preferences.library_pinned_keywords);
        assert_eq!(restored.library_recent_keywords, preferences.library_recent_keywords);
        let mut legacy = serde_json::to_value(&preferences).unwrap();
        legacy.as_object_mut().unwrap().remove("libraryPinnedKeywords");
        legacy.as_object_mut().unwrap().remove("libraryRecentKeywords");
        let legacy: UserPreferencesFile = serde_json::from_value(legacy).unwrap();
        assert!(legacy.library_pinned_keywords.is_empty());
        assert!(legacy.library_recent_keywords.is_empty());
        assert_eq!(
            restored.assistant_address_form,
            preferences.assistant_address_form
        );
        assert_eq!(
            restored.whisper_small_model_path,
            preferences.whisper_small_model_path
        );
        assert_eq!(
            restored.whisper_medium_model_path,
            preferences.whisper_medium_model_path
        );
        let _ = fs::remove_dir_all(root);
    }

    fn custom_video_optimization_options(rate_control: &str) -> VideoOptimizationOptions {
        VideoOptimizationOptions {
            profile: "custom".to_string(),
            rate_control: Some(rate_control.to_string()),
            crf: Some(27),
            max_height: Some(1080),
            video_bitrate_mbps: Some(4.5),
            audio_bitrate_kbps: Some(128),
            max_fps: Some(30),
        }
    }

    #[test]
    fn custom_video_crf_and_bitrate_modes_are_exclusive() {
        let crf_settings =
            validated_optimization_settings(&custom_video_optimization_options("crf"))
                .expect("custom CRF settings should be valid");
        assert_eq!(crf_settings, (1080, Some(30), None, 128, 27));

        let bitrate_settings =
            validated_optimization_settings(&custom_video_optimization_options("bitrate"))
                .expect("custom bitrate settings should be valid");
        assert_eq!(bitrate_settings, (1080, Some(30), Some(4.5), 128, 23));
    }

