    #[test]
    fn every_video_profile_uses_the_expected_bounding_box_and_bitrate() {
        let cases = [
            ("web-720", 1280, 720, 2.5),
            ("web-1080", 1920, 1080, 5.0),
            ("quality-1080", 1920, 1080, 8.0),
            ("strong", 1280, 720, 1.5),
        ];
        for (profile, expected_width, expected_height, expected_bitrate) in cases {
            let options = VideoOptimizationOptions {
                profile: profile.to_string(),
                rate_control: None,
                crf: None,
                max_height: None,
                video_bitrate_mbps: None,
                audio_bitrate_kbps: None,
                max_fps: None,
            };
            let settings = validated_optimization_settings(&options)
                .expect("profile settings should be valid");
            assert_eq!(settings.0, expected_height);
            assert_eq!(settings.2, Some(expected_bitrate));
            let arguments = ffmpeg_optimization_arguments(
                Path::new("source.webm"),
                Path::new("result.mp4"),
                &options,
                &sample_video_analysis(),
                Some(2),
                Some(Path::new("passlog")),
            )
            .expect("profile arguments should be valid");
            assert!(arguments
                .iter()
                .any(|argument| argument.contains(&format!("min(iw,{expected_width})"))));
            assert!(arguments
                .iter()
                .any(|argument| argument.contains(&format!("min(ih,{expected_height})"))));
        }

        for (height, width) in [(1440, 2560), (2160, 3840)] {
            let mut options = custom_video_optimization_options("crf");
            options.max_height = Some(height);
            let arguments = ffmpeg_optimization_arguments(
                Path::new("source.webm"),
                Path::new("result.mp4"),
                &options,
                &sample_video_analysis(),
                None,
                None,
            )
            .expect("custom dimensions should be valid");
            assert!(arguments
                .iter()
                .any(|argument| argument.contains(&format!("min(iw,{width})"))));
            assert!(arguments
                .iter()
                .any(|argument| argument.contains(&format!("min(ih,{height})"))));
        }
    }

    #[test]
    fn target_bitrate_uses_two_passes_but_crf_does_not() {
        let analysis = sample_video_analysis();
        let bitrate_options = custom_video_optimization_options("bitrate");
        let first_pass = ffmpeg_optimization_arguments(
            Path::new("source.webm"),
            Path::new("result.mp4"),
            &bitrate_options,
            &analysis,
            Some(1),
            Some(Path::new("passlog")),
        )
        .expect("first bitrate pass should be valid");
        let second_pass = ffmpeg_optimization_arguments(
            Path::new("source.webm"),
            Path::new("result.mp4"),
            &bitrate_options,
            &analysis,
            Some(2),
            Some(Path::new("passlog")),
        )
        .expect("second bitrate pass should be valid");
        assert!(first_pass.windows(2).any(|pair| pair == ["-pass", "1"]));
        assert!(first_pass.windows(2).any(|pair| pair == ["-f", "null"]));
        assert!(second_pass.windows(2).any(|pair| pair == ["-pass", "2"]));

        let crf_arguments = ffmpeg_optimization_arguments(
            Path::new("source.webm"),
            Path::new("result.mp4"),
            &custom_video_optimization_options("crf"),
            &analysis,
            None,
            None,
        )
        .expect("CRF arguments should be valid");
        assert!(!crf_arguments.iter().any(|argument| argument == "-pass"));
    }

