        write_scorm_archive(None, &root.to_string_lossy(), &project, &archive_path)
            .expect("write SCORM archive");

        let file = fs::File::open(&archive_path).expect("open SCORM archive");
        let mut archive = ZipArchive::new(file).expect("read SCORM archive");
        let mut runtime = String::new();
        archive
            .by_name("js/plyr-init.js")
            .expect("Plyr runtime entry")
