    #[test]
    fn dev_log_rotation_keeps_one_bounded_previous_segment() {
        let root = std::env::temp_dir().join(format!(
            "paideia-dev-log-rotation-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        fs::create_dir_all(&root).expect("dev log fixture root should be created");
        let log_path = root.join("paideia-dev.log");
        let archive_path = root.join(DEV_LOG_ARCHIVE_FILE_NAME);

        fs::write(&log_path, "1234").expect("active dev log fixture should be written");
        rotate_dev_log_if_needed_with_limit(&log_path, 1, 4).expect("dev log should rotate");
        assert!(!log_path.exists());
        assert_eq!(fs::read_to_string(&archive_path).unwrap(), "1234");

        fs::write(&log_path, "next").expect("next active dev log fixture should be written");
        rotate_dev_log_if_needed_with_limit(&log_path, 1, 4)
            .expect("dev log should replace its previous archive");
        assert!(!log_path.exists());
        assert_eq!(fs::read_to_string(&archive_path).unwrap(), "next");

        fs::remove_dir_all(root).expect("dev log fixture should be removed");
    }

    #[test]
    fn project_font_import_selection_and_deletion_are_independent() {
        let root = temporary_assets_dir("project-font-catalogue");
        let path = create_project(root.to_string_lossy().to_string(), "Fonts".into(), "Chapter".into(), "fr".into()).unwrap();
        let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("test-fixtures/fonts");
        let initial_default = load_project_from_path(&path).unwrap().custom_font.unwrap().id;
        for name in ["truetype.woff2", "cff.otf"] {
            upload_project_font(path.clone(), name.into(), fs::read(fixtures.join(name)).unwrap()).unwrap();
            assert_eq!(load_project_from_path(&path).unwrap().custom_font.unwrap().id, initial_default, "Import must not change the default");
        }
        let project = load_project_from_path(&path).unwrap();
        assert_eq!(project.imported_fonts.len(), 2);
        let first = project.imported_fonts[0].clone();
        let second = project.imported_fonts[1].clone();
        let scorm = root.join("font-export.zip");
        write_scorm_archive(None, &path, &project, &scorm).unwrap();
        let mut archive = zip::ZipArchive::new(fs::File::open(&scorm).unwrap()).unwrap();
        for font in &project.imported_fonts {
            for face in &font.faces { assert!(archive.by_name(&format!("assets/{}", face.asset_ref)).is_ok()); }
        }
        let package = root.join("fonts.paideia");
        zip_directory_to_file(Path::new(&path), &package).unwrap();
        let restored = root.join("restored");
        extract_paideia_archive_to(&fs::read(&package).unwrap(), &restored).unwrap();
        let restored_project = load_project_from_path(&restored.to_string_lossy()).unwrap();
        assert_eq!(restored_project.imported_fonts.len(), 2);
        for font in &restored_project.imported_fonts {
            for face in &font.faces { assert!(restored.join("assets").join(&face.asset_ref).exists()); }
        }
        select_imported_project_font(path.clone(), first.id.clone()).unwrap();
        select_imported_project_font(path.clone(), second.id.clone()).unwrap();
        let mut project = load_project_from_path(&path).unwrap();
        assert_eq!(project.imported_fonts.len(), 2);
        project.course_intro_html = format!(r#"<span data-paideia-font-id="{}" style="color:red;font-family:&quot;PaideiaRichFont-{}&quot;,sans-serif;font-size:20px"><b>Keep text</b></span><span style='font-family:PaideiaRichFont-{}-other'>Other</span>"#, first.id, first.id, first.id);
        save_project_to_path(&path, &project).unwrap();
        delete_imported_project_font(path.clone(), first.id.clone()).unwrap();
        let project = load_project_from_path(&path).unwrap();
        assert_eq!(project.custom_font.as_ref().unwrap().id, second.id);
        assert_eq!(project.imported_fonts.len(), 1);
        assert!(project.course_intro_html.contains("font-family:var(--lesson-custom-font, Inter, Arial, sans-serif)"));
        assert!(project.course_intro_html.contains("color:red"));
        assert!(project.course_intro_html.contains("font-size:20px"));
        assert!(project.course_intro_html.contains("<b>Keep text</b>"));
        assert!(project.course_intro_html.contains(&format!("PaideiaRichFont-{}-other", first.id)));
        assert!(!project.course_intro_html.contains("data-paideia-font-id"));
        for face in &first.faces { assert!(!Path::new(&path).join("assets").join(&face.asset_ref).exists()); }
        for face in &second.faces { assert!(Path::new(&path).join("assets").join(&face.asset_ref).exists()); }
        delete_imported_project_font(path.clone(), second.id.clone()).unwrap();
        let project = load_project_from_path(&path).unwrap();
        assert_eq!(project.custom_font.unwrap().id, "inter");
        assert!(project.imported_fonts.is_empty());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn legacy_project_font_survives_default_changes() {
        let root = temporary_assets_dir("legacy-project-font");
        let path = create_project(root.to_string_lossy().to_string(), "Legacy fonts".into(), "Chapter".into(), "fr".into()).unwrap();
        let bytes = include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/test-fixtures/fonts/truetype.woff2")).to_vec();
        let (family, converted) = convert_uploaded_font("truetype.woff2", bytes).unwrap();
        let mut project = load_project_from_path(&path).unwrap();
        store_project_font(&path, &mut project, family, converted, "project").unwrap();
        let legacy_id = project.custom_font.as_ref().unwrap().id.clone();
        save_project_to_path(&path, &project).unwrap();
        select_bundled_project_font(path.clone(), "inter".into()).unwrap();
        let project = load_project_from_path(&path).unwrap();
        assert_eq!(project.imported_fonts.len(), 1);
        assert_eq!(project.imported_fonts[0].id, rich_text_storage_id("project", &legacy_id));
        for face in &project.imported_fonts[0].faces { assert!(Path::new(&path).join("assets").join(&face.asset_ref).exists()); }
        select_imported_project_font(path.clone(), project.imported_fonts[0].id.clone()).unwrap();
        assert_eq!(link_project_rich_text_font(path.clone()).unwrap().len(), 1, "Already linked font must not be duplicated");
        delete_imported_project_font(path.clone(), legacy_id).unwrap();
        let project = load_project_from_path(&path).unwrap();
        assert!(project.imported_fonts.is_empty());
        assert_eq!(project.custom_font.unwrap().id, "inter");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn font_import_formats_survive_catalog_application_and_export() {
        let fixtures = Path::new(env!("CARGO_MANIFEST_DIR")).join("test-fixtures/fonts");
        let root = std::env::temp_dir().join(format!("paideia-font-formats-{}", uuid::Uuid::new_v4()));
        for (index, (name, expected_extension)) in [
            ("truetype.ttf", "woff2"),
            ("truetype.woff", "woff"),
            ("truetype.woff2", "woff2"),
            ("cff.otf", "otf"),
            ("cff.woff", "woff"),
            ("cff.woff2", "woff2"),
        ]
        .into_iter()
        .enumerate()
        {
            let library = root.join(format!("library-{}", index));
            let library_arg = Some(library.to_string_lossy().to_string());
            fs::create_dir_all(library.join("fonts/broken")).unwrap();
            fs::write(library.join("fonts/broken/invalid.woff2"), b"wOF2bad").unwrap();
            let bytes = fs::read(fixtures.join(name)).unwrap();
            let converted = convert_font_face(name.to_string(), bytes.clone()).expect(name);
            assert!(
                converted.file_name.ends_with(expected_extension),
                "{}",
                name
            );
            if !name.ends_with("ttf") {
                assert_eq!(
                    converted.bytes, bytes,
                    "native bytes must remain unchanged: {}",
                    name
                );
            }
            let catalog = upload_user_font(name.to_string(), bytes, library_arg.clone()).expect(name);
            let font = catalog
                .iter()
                .find(|font| font.font_family == converted.family)
                .unwrap();
            assert!(!catalog.iter().any(|font| font.id == "broken"));
            assert_eq!(catalog.len(), 1);
            assert_eq!(font.faces.len(), 1);
            assert!(font.file_name.ends_with(expected_extension));
            let target_path = create_project(
                root.to_string_lossy().to_string(),
                format!("Font test {}", index),
                "Chapitre".to_string(),
                "fr".to_string(),
            )
            .unwrap();
            select_user_project_font(target_path.clone(), font.id.clone(), library_arg.clone())
                .unwrap();
            let target = PathBuf::from(&target_path);
            let project = load_project_from_path(&target_path).unwrap();
            let custom = project.custom_font.as_ref().unwrap();
            for face in &custom.faces {
                assert!(target.join("assets").join(&face.asset_ref).is_file());
            }
            let css = project_font_face_css(Some(custom), |asset| asset.to_string());
            let format = font_css_format(&custom.asset_ref);
            assert!(css.contains(&format!("format(\"{}\")", format)));
            copy_project_font_to_rich_text_storage(&target.to_string_lossy(), custom).unwrap();
            let rich = scan_project_rich_text_fonts(&target.to_string_lossy()).unwrap();
            assert_eq!(rich.len(), 1);
            assert!(rich_text_font_faces_css(&rich, |asset| asset.to_string())
                .contains(&format!("format(\"{}\")", format)));
        }
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn font_import_invalid_web_font_reports_file_and_decode_stage() {
        for name in ["broken.woff", "broken.woff2"] {
            let bytes = if name.ends_with("woff2") {
                b"wOF2bad"
            } else {
                b"wOFFbad"
            };
            let error = convert_font_face(name.to_string(), bytes.to_vec()).unwrap_err();
            assert!(error.contains(name));
            assert!(error.contains("décodage"));
        }
    }

    #[test]
    fn font_import_archives_ignore_non_font_files() {
        let font = include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/test-fixtures/fonts/cff.otf"
        ));
        let mut zip = ZipWriter::new(Cursor::new(Vec::new()));
        for (name, bytes) in [
            ("fonts/Fixture.OTF", font.as_slice()),
            ("docs/README.txt", b"Readme, not a font".as_slice()),
            ("LICENSE.txt", b"License, not a font".as_slice()),
            ("preview.png", b"Preview, not a font".as_slice()),
            ("__MACOSX/._Fixture.otf", b"AppleDouble metadata".as_slice()),
        ] {
            zip.start_file(name, SimpleFileOptions::default()).unwrap();
            zip.write_all(bytes).unwrap();
        }
        let zip_bytes = zip.finish().unwrap().into_inner();
        let seven_zip = include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/test-fixtures/fonts/mixed.7z"
        ));
        for (name, bytes) in [("mixed.zip", zip_bytes), ("mixed.7z", seven_zip.to_vec())] {
            let (family, faces) = convert_uploaded_font(name, bytes).expect(name);
            assert_eq!(family, "Paideia Fixture CFF");
            assert_eq!(faces.len(), 1);
            assert_eq!(faces[0].bytes, font.to_vec());
        }
    }

    #[test]
    fn imported_woff_is_preserved() {
        let source = include_bytes!(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../public/fonts/Inter/Inter-Regular.woff"
        ));
        let converted = convert_font_face("Inter-Regular.woff".to_string(), source.to_vec())
            .expect("convert bundled Inter WOFF");
        assert_eq!(converted.family, "Inter");
        assert_eq!(converted.weight, 400);
        assert_eq!(converted.style, "normal");
        assert_eq!(converted.bytes, source.to_vec());
        assert!(converted.file_name.ends_with(".woff"));
    }

    #[test]
    fn complete_orientation_survives_serialization_and_scorm_defaults_to_portrait() {
        for orientation in [None, Some("portrait"), Some("landscape")] {
            let mut payload = serde_json::json!({"maxAttempts": 3, "successThreshold": 80});
            if let Some(value) = orientation { payload["orientation"] = serde_json::json!(value); }
            let activity: crate::models::CompleteActivityData = serde_json::from_value(payload).unwrap();
            let saved = serde_json::to_value(&activity).unwrap();
            let restored: crate::models::CompleteActivityData = serde_json::from_value(saved).unwrap();
            assert_eq!(restored.orientation.as_deref(), orientation);
            assert_eq!(restored.max_attempts, 3);
            assert_eq!(restored.success_threshold, 80);
            let mut block = sample_quiz_block();
            block.block_type = "complete".to_string();
            block.complete = Some(restored);
            let html = render_scorm_complete(&block, "", "activity");
            assert!(html.contains(&format!("data-complete-orientation=\"{}\"", orientation.unwrap_or("portrait"))));
            let project = sample_project(vec![sample_chapter("chapter", "Complete", block, None)]);
            let styles = build_scorm_styles_for_root(&project, None);
            let document = build_scorm_index(&project, None);
            for output in [styles, document] {
                assert!(output.contains("--complete-folio-width:min(calc(100% - 32px),900px)"));
                assert!(output.contains("aspect-ratio:1.41421356237 / 1"));
            }
        }
    }

    #[test]
    fn standalone_questions_do_not_inherit_quiz_gating_or_result_panels() {
        for block_type in ["question-multiple", "question-unique", "question-true-false"] {
            let mut block = sample_quiz_block();
            block.block_type = block_type.to_string();
            let html = render_scorm_standalone_question(&block, &scorm_tracking_attrs(&block, "activity"));
            assert!(html.contains("class=\"block standalone-question\""));
            assert!(html.contains("data-paideia-completion=\"view\""));
            assert!(html.contains("standalone-validate"));
            assert!(!html.contains("quiz-start-panel"));
            assert!(!html.contains("quiz-result"));
            assert!(!html.contains("data-quiz-passing-score"));
        }
    }

    #[test]
    fn random_questions_scorm_draws_without_quiz_panels() {
        let mut block = sample_quiz_block();
        block.block_type = "question-random".to_string();
        let quiz = block.quiz.as_mut().unwrap();
        quiz.settings.question_limit = 1;
        quiz.settings.limit_questions = true;
        let mut second = quiz.questions[0].clone();
        second.mode = "multiple".to_string();
        quiz.questions.push(second);
        let html = render_scorm_random_questions(&block, &scorm_tracking_attrs(&block, "activity"));
        assert!(html.contains("data-count=\"1\""));
        assert!(html.contains("random-question-candidate"));
        assert!(html.contains("random-question-candidate\" data-original-index=\"0\" hidden"));
        assert!(html.contains("random-question-progress"));
        assert!(html.contains("random-question-next"));
        assert!(html.contains("candidate.hidden=position!==index"));
        assert!(html.contains("standalone-validate"));
        assert!(html.contains("type=\"checkbox\""));
        assert!(html.contains("name=\"standalone-quiz_block-0\""));
        assert!(html.contains("name=\"standalone-quiz_block-1\""));
        assert!(!html.contains("quiz-start-panel"));
        assert!(!html.contains("quiz-result"));
    }

