    #[test]
    fn pasted_chapter_reuses_or_copies_identical_media_as_requested() {
        let root = std::env::temp_dir().join(format!(
            "paideia-chapter-paste-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        let source_root = root.join("source");
        let target_root = root.join("target");
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(source_root.join("assets/images")).expect("create source assets");
        fs::create_dir_all(target_root.join("assets/images")).expect("create target assets");

        let mut source_block = sample_quiz_block();
        source_block.asset_refs = vec!["images/source.png".to_string()];
        let source_chapter = sample_chapter("chapter-1", "Chapitre média", source_block, None);
        let source_project = sample_project(vec![source_chapter.clone()]);

        let mut target_block = sample_quiz_block();
        target_block.asset_refs = vec!["images/existing.png".to_string()];
        let target_project = sample_project(vec![sample_chapter(
            "chapter-1",
            "Chapitre existant",
            target_block,
            None,
        )]);
        let source_path = source_root.to_string_lossy().to_string();
        let target_path = target_root.to_string_lossy().to_string();
        save_project_to_path(&source_path, &source_project).expect("save source project");
        save_project_to_path(&target_path, &target_project).expect("save target project");
        fs::write(source_root.join("assets/images/source.png"), b"same-media")
            .expect("write source media");
        fs::write(
            target_root.join("assets/images/existing.png"),
            b"same-media",
        )
        .expect("write target media");

        let duplicates = inspect_chapter_asset_duplicates(
            source_path.clone(),
            target_path.clone(),
            source_chapter.clone(),
        )
        .expect("inspect chapter duplicates");
        assert_eq!(duplicates.len(), 1);
        assert_eq!(duplicates[0].existing_asset_ref, "images/existing.png");

        paste_chapter(
            source_path.clone(),
            "project_1".to_string(),
            target_path.clone(),
            "project_1".to_string(),
            "module_1".to_string(),
            1,
            source_chapter.clone(),
            vec![ChapterAssetReuse {
                source_asset_ref: "images/source.png".to_string(),
                target_asset_ref: "images/existing.png".to_string(),
            }],
        )
        .expect("paste chapter reusing media");
        let reused_project = load_project_from_path(&target_path).expect("reload reused project");
        assert_eq!(reused_project.course.modules[0].chapters.len(), 2);
        assert_eq!(
            reused_project.course.modules[0].chapters[1].pages[0].blocks[0].asset_refs,
            vec!["images/existing.png".to_string()]
        );

        paste_chapter(
            source_path,
            "project_1".to_string(),
            target_path.clone(),
            "project_1".to_string(),
            "module_1".to_string(),
            2,
            source_chapter,
            Vec::new(),
        )
        .expect("paste chapter copying media");
        let copied_project = load_project_from_path(&target_path).expect("reload copied project");
        assert_eq!(copied_project.course.modules[0].chapters.len(), 3);
        let copied_ref =
            &copied_project.course.modules[0].chapters[2].pages[0].blocks[0].asset_refs[0];
        assert!(copied_ref.starts_with("chapter-paste/"));
        assert_ne!(copied_ref, "images/existing.png");
        assert_eq!(
            fs::read(target_root.join("assets").join(copied_ref)).expect("read copied media"),
            b"same-media"
        );

        fs::remove_dir_all(root).expect("remove chapter paste fixture");
    }

    #[test]
    fn pasted_chapter_copies_its_rich_text_fonts_and_remaps_conflicting_ids() {
        let root = std::env::temp_dir().join(format!(
            "paideia-chapter-font-paste-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        let source_root = root.join("source");
        let target_root = root.join("target");
        let font_id = "rich-user-display";
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(source_root.join("assets/fonts").join(font_id)).unwrap();
        fs::create_dir_all(target_root.join("assets/fonts").join(font_id)).unwrap();
        fs::write(
            source_root
                .join("assets/fonts")
                .join(font_id)
                .join("Display.woff2"),
            b"source-font",
        )
        .unwrap();
        fs::write(
            source_root
                .join("assets/fonts")
                .join(font_id)
                .join("LICENSE.txt"),
            b"source-license",
        )
        .unwrap();
        fs::write(
            target_root
                .join("assets/fonts")
                .join(font_id)
                .join("Display.woff2"),
            b"different-font",
        )
        .unwrap();

        let mut source_block = sample_quiz_block();
        source_block.content_html = Some(format!(
            "<p><span data-paideia-font-id=\"{font_id}\" style=\"font-family:PaideiaRichFont-{font_id}\">Titre</span></p>"
        ));
        let source_chapter = sample_chapter("chapter-1", "Chapitre police", source_block, None);
        let source_project = sample_project(vec![source_chapter.clone()]);
        let target_project = sample_project(vec![sample_chapter(
            "chapter-1",
            "Chapitre existant",
            sample_quiz_block(),
            None,
        )]);
        let source_path = source_root.to_string_lossy().to_string();
        let target_path = target_root.to_string_lossy().to_string();
        save_project_to_path(&source_path, &source_project).unwrap();
        save_project_to_path(&target_path, &target_project).unwrap();

        paste_chapter(
            source_path,
            "project_1".to_string(),
            target_path.clone(),
            "project_1".to_string(),
            "module_1".to_string(),
            1,
            source_chapter,
            Vec::new(),
        )
        .expect("paste chapter with rich text font");

        let pasted = load_project_from_path(&target_path).unwrap();
        let html = pasted.course.modules[0].chapters[1].pages[0].blocks[0]
            .content_html
            .as_deref()
            .unwrap();
        let remapped_id = Regex::new(r#"data-paideia-font-id=\"([^\"]+)\""#)
            .unwrap()
            .captures(html)
            .unwrap()[1]
            .to_string();
        assert_ne!(remapped_id, font_id);
        assert!(html.contains(&format!("font-family:PaideiaRichFont-{remapped_id}")));
        assert_eq!(
            fs::read(
                target_root
                    .join("assets/fonts")
                    .join(&remapped_id)
                    .join("Display.woff2")
            )
            .unwrap(),
            b"source-font"
        );
        assert!(target_root
            .join("assets/fonts")
            .join(remapped_id)
            .join("LICENSE.txt")
            .is_file());

        fs::remove_dir_all(root).unwrap();
    }

