    fn build_zip(files: &[(&str, &[u8])]) -> Vec<u8> {
        let cursor = Cursor::new(Vec::<u8>::new());
        let mut writer = ZipWriter::new(cursor);
        let options = SimpleFileOptions::default().compression_method(CompressionMethod::Stored);
        let entries: Vec<_> = files
            .iter()
            .map(|(path, bytes)| PaideiaArchiveIntegrityEntry {
                path: (*path).to_string(),
                size: bytes.len() as u64,
                sha256: sha256_digest_hex(&Sha256::digest(bytes)),
            })
            .collect();
        let manifest = archive_integrity::create(&entries);
        for (path, bytes) in files {
            writer.start_file(*path, options).expect("start ZIP entry");
            writer.write_all(bytes).expect("write ZIP entry");
        }
        writer
            .start_file(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST, options)
            .expect("start integrity manifest");
        writer
            .write_all(&serde_json::to_vec(&manifest).expect("serialize integrity manifest"))
            .expect("write integrity manifest");
        writer.finish().expect("finish ZIP").into_inner()
    }

    fn build_unsigned_zip(files: &[(&str, &[u8])]) -> Vec<u8> {
        let cursor = Cursor::new(Vec::<u8>::new());
        let mut writer = ZipWriter::new(cursor);
        let options = SimpleFileOptions::default().compression_method(CompressionMethod::Stored);
        for (path, bytes) in files {
            writer.start_file(*path, options).expect("start ZIP entry");
            writer.write_all(bytes).expect("write ZIP entry");
        }
        writer.finish().expect("finish ZIP").into_inner()
    }

    #[test]
    fn paideia_archive_extraction_requires_a_safe_unique_project_tree() {
        let root = temporary_assets_dir("paideia-archive-safe");
        let valid = build_zip(&[("project.json", b"{}"), ("assets/reference.txt", b"ok")]);
        extract_paideia_archive_to(&valid, &root).expect("extract safe archive");
        assert_eq!(fs::read(root.join("assets/reference.txt")).unwrap(), b"ok");
        let _ = fs::remove_dir_all(&root);

        let missing_root = temporary_assets_dir("paideia-archive-missing-project");
        let missing = build_zip(&[("assets/reference.txt", b"ok")]);
        assert!(extract_paideia_archive_to(&missing, &missing_root).is_err());
        assert!(!missing_root.join("assets/reference.txt").exists());
        let _ = fs::remove_dir_all(&missing_root);

        let duplicate_root = temporary_assets_dir("paideia-archive-duplicate");
        let duplicate = build_zip(&[
            ("project.json", b"{}"),
            ("ASSETS/file.txt", b"a"),
            ("assets/file.txt", b"b"),
        ]);
        assert!(extract_paideia_archive_to(&duplicate, &duplicate_root).is_err());
        assert!(!duplicate_root.join("assets/file.txt").exists());
        let _ = fs::remove_dir_all(&duplicate_root);

        let executable_root = temporary_assets_dir("paideia-archive-executable");
        let executable = build_zip(&[("project.json", b"{}"), ("assets/tool.exe", b"payload")]);
        assert!(extract_paideia_archive_to(&executable, &executable_root).is_err());
        assert!(!executable_root.join("project.json").exists());
        let _ = fs::remove_dir_all(&executable_root);

        let disguised_root = temporary_assets_dir("paideia-archive-disguised-executable");
        let disguised = build_zip(&[("project.json", b"{}"), ("assets/image.png", b"MZpayload")]);
        assert!(extract_paideia_archive_to(&disguised, &disguised_root).is_err());
        assert!(!disguised_root.join("project.json").exists());
        let _ = fs::remove_dir_all(&disguised_root);
    }

    #[test]
    fn paideia_archive_extraction_limits_the_entry_count() {
        let cursor = Cursor::new(Vec::<u8>::new());
        let mut writer = ZipWriter::new(cursor);
        let options = SimpleFileOptions::default().compression_method(CompressionMethod::Stored);
        writer
            .start_file("project.json", options)
            .expect("start project entry");
        writer.write_all(b"{}").expect("write project entry");
        for index in 0..PAIDEIA_ARCHIVE_MAX_ENTRIES {
            writer
                .start_file(format!("assets/{index}.txt"), options)
                .expect("start bounded entry");
        }
        let bytes = writer.finish().expect("finish oversized ZIP").into_inner();
        let root = temporary_assets_dir("paideia-archive-entry-limit");
        assert!(extract_paideia_archive_to(&bytes, &root).is_err());
        assert!(!root.join("project.json").exists());
        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn paideia_shared_bank_import_keeps_local_and_shared_versions_without_duplicates() {
        use crate::resource_bank_store::{self as store, Family};
        let root = temporary_assets_dir("paideia-share-bank-dedup");
        let local = serde_json::json!({"id":"bank","name":"Local","entries":[],"revision":4,
            "projectPaths":["local-lesson"],"collectionIds":["local-collection"]});
        store::upsert(&root, Family::References, &[local.clone()]).unwrap();

        let same = serde_json::json!({"id":"bank","name":"Local","entries":[],"revision":1});
        persist_shared_bank(&root, Family::References, same, None, false, None).unwrap();
        assert_eq!(store::all(&root, Family::References).unwrap().len(), 1);

        let shared = serde_json::json!({"id":"bank","name":"Partagée","entries":[{"id":"one","term":"Mot","definitionHtml":"<p>Définition</p>"}],"revision":1});
        for _ in 0..2 {
            persist_shared_bank(&root, Family::References, shared.clone(), None, false, None).unwrap();
        }
        let banks = store::all(&root, Family::References).unwrap();
        assert_eq!(banks.len(), 2);
        assert!(banks.contains(&local));
        let copy = banks.iter().find(|bank| bank["name"] == "Partagée").unwrap();
        assert_ne!(copy["id"], "bank");
        assert_eq!(copy["entries"], shared["entries"]);
        let updated = persist_shared_bank(&root, Family::References, shared, None, true, Some("imported-lesson")).unwrap();
        assert_eq!(updated, "bank");
        let updated = store::load(&root, Family::References, "bank").unwrap();
        assert_eq!(updated["name"], "Partagée");
        assert_eq!(updated["revision"], 5);
        assert_eq!(updated["projectPaths"], serde_json::json!(["local-lesson", "imported-lesson"]));
        assert_eq!(updated["collectionIds"], local["collectionIds"]);
        assert_eq!(store::previous(&root, "bank").unwrap(), local);
    }

