    #[test]
    fn paideia_archive_requires_and_verifies_v2_integrity() {
        let unsigned_root = temporary_assets_dir("paideia-archive-unsigned");
        let unsigned = build_unsigned_zip(&[("project.json", b"{}")]);
        let unsigned_error = extract_paideia_archive_to(&unsigned, &unsigned_root)
            .expect_err("unsigned archive must be rejected");
        assert!(unsigned_error.starts_with(PAIDEIA_ARCHIVE_INTEGRITY_REJECTED));
        assert!(!unsigned_root.join("project.json").exists());

        let cursor = Cursor::new(Vec::<u8>::new());
        let mut writer = ZipWriter::new(cursor);
        let options = SimpleFileOptions::default().compression_method(CompressionMethod::Stored);
        writer
            .start_file("project.json", options)
            .expect("start tampered project entry");
        writer
            .write_all(b"{}")
            .expect("write tampered project entry");
        let mut stale_manifest = archive_integrity::create(&[]);
        stale_manifest.mac = "0".repeat(64);
        writer
            .start_file(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST, options)
            .expect("start stale integrity manifest");
        writer
            .write_all(&serde_json::to_vec(&stale_manifest).expect("serialize stale manifest"))
            .expect("write stale integrity manifest");
        let tampered = writer.finish().expect("finish tampered ZIP").into_inner();
        let tampered_root = temporary_assets_dir("paideia-archive-tampered");
        let tampered_error = extract_paideia_archive_to(&tampered, &tampered_root)
            .expect_err("tampered archive must be rejected");
        assert!(tampered_error.starts_with(PAIDEIA_ARCHIVE_INTEGRITY_REJECTED));
        assert!(!tampered_root.join("project.json").exists());

        let _ = fs::remove_dir_all(unsigned_root);
        let _ = fs::remove_dir_all(tampered_root);
    }

    #[test]
    fn paideia_archive_v2_rejects_tampering_before_extraction() {
        let original = [
            ("project.json", b"{}".as_slice()),
            ("assets/a.txt", b"abc".as_slice()),
        ];
        let entries: Vec<_> = original
            .iter()
            .map(|(path, bytes)| PaideiaArchiveIntegrityEntry {
                path: path.to_string(),
                size: bytes.len() as u64,
                sha256: sha256_digest_hex(&Sha256::digest(bytes)),
            })
            .collect();
        let manifest = serde_json::to_vec(&archive_integrity::create(&entries)).unwrap();
        let value: serde_json::Value = serde_json::from_slice(&manifest).unwrap();
        assert_eq!(value.as_object().unwrap().len(), 4);
        assert!(!String::from_utf8_lossy(&manifest).contains("assets"));
        let pack = |files: &[(&str, &[u8])], control: &[u8]| {
            let mut zip = ZipWriter::new(Cursor::new(Vec::new()));
            for (path, bytes) in files {
                zip.start_file(*path, SimpleFileOptions::default()).unwrap();
                zip.write_all(bytes).unwrap();
            }
            zip.start_file(
                PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST,
                SimpleFileOptions::default(),
            )
            .unwrap();
            zip.write_all(control).unwrap();
            zip.finish().unwrap().into_inner()
        };
        for files in [
            vec![
                ("project.json", b"{}".as_slice()),
                ("assets/a.txt", b"xyz".as_slice()),
            ],
            vec![
                ("project.json", b"{}".as_slice()),
                ("assets/b.txt", b"abc".as_slice()),
            ],
            vec![("project.json", b"{}".as_slice())],
            vec![
                ("project.json", b"{}".as_slice()),
                ("assets/a.txt", b"abc".as_slice()),
                ("extra", b"x".as_slice()),
            ],
        ] {
            let root = temporary_assets_dir("paideia-v2-tamper");
            fs::remove_dir(&root).unwrap();
            let error = extract_paideia_archive_to(&pack(&files, &manifest), &root).unwrap_err();
            assert!(error.starts_with(PAIDEIA_ARCHIVE_INTEGRITY_REJECTED));
            assert!(!root.exists(), "Integrity failure must precede extraction");
        }
        for control in [
            br#"{"schemaVersion":1,"algorithm":"SHA-256","files":[]}"#.as_slice(),
            br#"{"schemaVersion":2,"algorithm":"HMAC-SHA-256","keyId":"unknown","mac":"00"}"#.as_slice(),
            br#"{"schemaVersion":2,"algorithm":"HMAC-SHA-256","keyId":"paideia-v2","mac":"invalid"}"#.as_slice(),
        ] {
            let root = temporary_assets_dir("paideia-v2-invalid");
            fs::remove_dir(&root).unwrap();
            assert!(extract_paideia_archive_to(&pack(&original, control), &root).is_err());
            assert!(!root.exists());
        }
        // ZIP ordering is irrelevant, and the external archive name never enters the calculation.
        let root = temporary_assets_dir("paideia-v2-reorder");
        extract_paideia_archive_to(&pack(&[original[1], original[0]], &manifest), &root).unwrap();
        assert_eq!(fs::read(root.join("assets/a.txt")).unwrap(), b"abc");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn paideia_archive_export_embeds_a_manifest_and_roundtrips() {
        let source_root = temporary_assets_dir("paideia-archive-export-source");
        fs::create_dir_all(source_root.join("assets")).expect("create export assets");
        fs::create_dir_all(source_root.join("notes/history")).expect("create note history");
        fs::write(source_root.join("project.json"), b"{}").expect("write export project");
        fs::write(source_root.join("assets/reference.txt"), b"contenu")
            .expect("write export asset");
        fs::write(source_root.join("notes/history/purge.json"), b"{}").expect("write note history");
        let archive_path = source_root.with_extension("paideia");

        zip_directory_to_file(&source_root, &archive_path).expect("export signed archive");
        let archive_file = fs::File::open(&archive_path).expect("open signed archive");
        let mut archive = ZipArchive::new(archive_file).expect("read signed archive");
        let manifest: archive_integrity::Manifest = serde_json::from_reader(
            archive
                .by_name(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST)
                .expect("integrity manifest is embedded"),
        )
        .expect("parse embedded integrity manifest");
        assert_eq!(manifest.algorithm, "HMAC-SHA-256");
        assert_eq!(manifest.schema_version, 2);
        assert_eq!(manifest.mac.len(), 64);
        drop(archive);

        let extraction_root = temporary_assets_dir("paideia-archive-export-target");
        let bytes = fs::read(&archive_path).expect("read signed archive bytes");
        extract_paideia_archive_to(&bytes, &extraction_root).expect("verify and extract archive");
        assert_eq!(
            fs::read(extraction_root.join("assets/reference.txt")).unwrap(),
            b"contenu"
        );
        assert_eq!(
            fs::read(extraction_root.join("notes/history/purge.json")).unwrap(),
            b"{}"
        );
        assert!(!extraction_root
            .join(PAIDEIA_ARCHIVE_INTEGRITY_MANIFEST)
            .exists());

        let _ = fs::remove_dir_all(source_root);
        let _ = fs::remove_dir_all(extraction_root);
        let _ = fs::remove_file(archive_path);
    }

