    #[test]
    fn scorm_already_compressed_media_is_stored_without_deflate() {
        let cursor = std::io::Cursor::new(Vec::<u8>::new());
        let mut writer = ZipWriter::new(cursor);
        let default_options =
            SimpleFileOptions::default().compression_method(CompressionMethod::Deflated);
        writer
            .start_file(
                "assets/images/animation.gif",
                scorm_asset_zip_options("assets/images/animation.gif", default_options),
            )
            .expect("start GIF entry");
        writer.write_all(b"GIF89a").expect("write GIF entry");
        writer
            .start_file(
                "assets/documents/readme.txt",
                scorm_asset_zip_options("assets/documents/readme.txt", default_options),
            )
            .expect("start text entry");
        writer
            .write_all(b"texte texte texte")
            .expect("write text entry");
        let cursor = writer.finish().expect("finish archive");
        let mut archive = ZipArchive::new(cursor).expect("open archive");

        assert_eq!(
            archive
                .by_name("assets/images/animation.gif")
                .expect("GIF entry")
                .compression(),
            CompressionMethod::Stored
        );
        assert_eq!(
            archive
                .by_name("assets/documents/readme.txt")
                .expect("text entry")
                .compression(),
            CompressionMethod::Deflated
        );
    }

