    #[test]
    fn missing_video_is_empty_in_duplicate_and_existing_lesson_snapshot() {
        let source = temporary_assets_dir("paideia-missing-video-reconciliation");
        let source_path = source.to_string_lossy().to_string();
        fs::create_dir_all(source.join("assets/images/scorm")).unwrap();
        fs::write(source.join("assets/images/scorm/poster.png"), b"poster").unwrap();
        let mut block = sample_quiz_block();
        block.block_type = "media".to_string();
        block.variant = Some("video".to_string());
        block.asset_refs = vec![
            "images/scorm/poster.png".to_string(),
            "video/scorm/missing.mp4".to_string(),
        ];
        block.media_file_name = Some("missing.mp4".to_string());
        let project = sample_project(vec![sample_chapter("chapter", "Chapitre", block, None)]);
        save_project_to_path(&source_path, &project).unwrap();

        let library = temporary_assets_dir("paideia-missing-video-duplicate");
        let duplicate = duplicate_project(source_path.clone(), Some(library.to_string_lossy().to_string()), None).unwrap();
        let duplicated = load_project_from_path(&duplicate).unwrap();
        let duplicated_block = &duplicated.course.modules[0].chapters[0].pages[0].blocks[0];
        assert_eq!(duplicated_block.asset_refs, vec!["images/scorm/poster.png"]);
        assert_eq!(duplicated_block.media_file_name, None);

        create_snapshot(source_path.clone(), "Avant suppression".to_string(), "".to_string()).unwrap();
        let repaired = load_project_from_path(&source_path).unwrap();
        let repaired_block = &repaired.course.modules[0].chapters[0].pages[0].blocks[0];
        assert_eq!(repaired_block.asset_refs, vec!["images/scorm/poster.png"]);
        assert_eq!(repaired_block.media_file_name, None);
        fs::remove_dir_all(source).unwrap();
        fs::remove_dir_all(library).unwrap();
    }

