    #[test]
    fn html_duplicate_survives_source_deletion_replacement_and_snapshot_restore() {
        let root = temporary_assets_dir("html-duplicate-lifecycle");
        let project_path = root.to_string_lossy().to_string();
        let old_dir = root.join("assets/html/original");
        fs::create_dir_all(&old_dir).unwrap();
        let html = "<html><head><script src=\"runtime.js\"></script></head><body>Original</body></html>";
        fs::write(old_dir.join("index.html"), html).unwrap();
        fs::write(old_dir.join("runtime.js"), b"original runtime").unwrap();
        let mut source = sample_quiz_block();
        source.block_type = "html-custom".into();
        source.content_html = Some(html.into());
        source.html_asset_root = Some("html/original".into());
        source.html_entry_file = Some("html/original/index.html".into());
        source.html_package_name = Some("original.zip".into());
        source.asset_refs = vec!["html/original/index.html".into(), "html/original/runtime.js".into()];
        let source_id = source.id.clone();
        let project = sample_project(vec![sample_chapter("chapter", "Chapter", source.clone(), None)]);
        let page_id = project.course.modules[0].chapters[0].pages[0].id.clone();
        save_project_to_path(&project_path, &project).unwrap();

        // Use the real creation command with stale client content to prove that
        // duplication preserves the persisted source and its package together.
        let duplicated = create_block(
            project_path.clone(), // project_path
            page_id.clone(), // page_id
            Some(1), // target_index
            Some(source_id.clone()), // duplicate_source_block_id
            "html-custom".into(), // block_type
            "Copy".into(), // title
            String::new(), // summary
            Some("<main>stale draft</main>".into()), // content_html
            None, // quote_author_html
            None, // quote_show_author
            None, // media_layout
            None, // image_size
            None, // content_width
            None, // content_align
            None, // media_gap
            None, // vertical_align
            None, // image_rounded
            None, // media_file_name
            None, // image_crop
            None, // image_accessibility
            None, // video_caption_color
            None, // video_caption_background_enabled
            None, // video_caption_outline
            None, // video_subtitle_original_ref
            None, // video_allow_fullscreen
            None, // audio_autoplay_next
            None, // audio_allow_download
            None, // image360_initial_yaw
            None, // image360_initial_pitch
            None, // image360_zoom_enabled
            None, // image360_full_width
            None, // image360_allow_fullscreen
            None, // header_background_color
            None, // header_text_color
            None, // header_text_outline
            None, // header_text_outline_color
            None, // header_height
            None, // header_image_position_y
            None, // button_background_color
            None, // button_text_color
            None, // panel_background_color
            None, // panel_border_color
            None, // panel_border_width
            None, // panel_border_style
            None, // panel_padding
            None, // panel_rounded
            None, // panel_shadow
            None, // note_icon
            None, // note_show_icon
            None, // note_icon_color
            None, // note_icon_matches_border
            None, // flip_card_front_background_color
            None, // flip_card_back_background_color
            None, // flip_card_front_border_color
            None, // flip_card_back_border_color
            None, // slides_activity_background_color
            None, // slides_activity_border_color
            None, // slides_activity_border_width
            None, // slides_activity_border_style
            None, // slides_activity_rounded
            None, // slides_activity_shadow
            None, // section_background_color
            None, // section_background_image_ref
            None, // section_background_opacity
            None, // section_background_overlay_dark
            None, // section_background_blur
            None, // section_background_position_y
            None, // section_background_rounded
            None, // section_background_wide
            None, // section_background_height
            None, // divider_color
            None, // divider_width
            None, // divider_style
            None, // marker_scheme
            None, // marker_type
            None, // marker_text_color
            None, // point_of_interest_markers
            None, // image360_hotspots
            None, // activity_items
            None, // situational_dialogue_characters
            None, // attachment_files
            None, // quiz
            None, // find_elements
            None, // complete
            None, // card_sort
            None, // matching
            None, // marker_popup_width
            None, // marker_popup_height
            None, // padding_offset
            Some(Vec::new()), // asset_refs
            None, // subtitle_refs
        ).expect("duplicate imported HTML");
        let copy = duplicated.project.course.modules[0].chapters[0].pages[0].blocks[1].clone();
        assert_ne!(copy.id, source_id);
        assert_ne!(copy.tracking_key, source.tracking_key);
        assert_eq!(copy.content_html, source.content_html);
        assert_eq!(copy.html_asset_root, source.html_asset_root);
        assert_eq!(copy.html_entry_file, source.html_entry_file);
        assert_eq!(copy.html_package_name, source.html_package_name);
        assert_eq!(copy.asset_refs, source.asset_refs);
        let rendered = render_scorm_block(&copy, "copied-html", None, 36, None, "#222222", "#FFFFFF");
        assert!(rendered.contains("html/original/"), "export must resolve copied relative resources");

        create_snapshot(project_path.clone(), "Before source deletion".into(), "v1".into()).unwrap();
        let deleted = delete_block(project_path.clone(), page_id.clone(), source_id.clone()).unwrap();
        assert_eq!(deleted.project.course.modules[0].chapters[0].pages[0].blocks.len(), 1);
        assert!(old_dir.join("runtime.js").is_file(), "the surviving copy still uses the package");
        let snapshot = create_snapshot(project_path.clone(), "Before replacement".into(), "v1".into()).unwrap();
        let snapshot_id = snapshot.snapshots[0].id.clone();
        let zip = build_unsigned_zip(&[
            ("index.html", b"<html><body>Replacement</body></html>"),
            ("runtime.js", b"replacement runtime"),
        ]);
        let replaced = import_html_activity_package(project_path.clone(), page_id.clone(), copy.id.clone(), "replacement.zip".into(), zip).unwrap();
        let replacement = &replaced.project.course.modules[0].chapters[0].pages[0].blocks[0];
        assert_ne!(replacement.html_asset_root, copy.html_asset_root);
        assert!(!old_dir.exists(), "the old package is no longer active");
        let restored = restore_snapshot(project_path.clone(), snapshot_id).unwrap();
        let restored_copy = &restored.project.course.modules[0].chapters[0].pages[0].blocks[0];
        assert_eq!(restored_copy.id, copy.id);
        assert_eq!(restored_copy.html_asset_root, copy.html_asset_root);
        assert_eq!(restored_copy.html_entry_file, copy.html_entry_file);
        assert_eq!(restored_copy.content_html, copy.content_html);
        assert_eq!(fs::read(old_dir.join("runtime.js")).unwrap(), b"original runtime");
        assert!(!restored.project.course.modules[0].chapters[0].pages[0].blocks.iter().any(|block| block.id == source_id));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn html_duplicate_source_keeps_plain_html_and_rejects_invalid_packages() {
        let root = temporary_assets_dir("html-duplicate-validation");
        let project_path = root.to_string_lossy().to_string();
        let mut source = sample_quiz_block();
        source.block_type = "html-custom".into();
        source.content_html = Some("<p>Plain HTML</p>".into());
        source.asset_refs.clear();
        let source_id = source.id.clone();
        let mut project = sample_project(vec![sample_chapter("chapter", "Chapter", source.clone(), None)]);
        let page_id = project.course.modules[0].chapters[0].pages[0].id.clone();
        let plain = find_html_duplicate_source(&project_path, &project, &page_id, &source_id).unwrap();
        assert_eq!(plain.content_html, source.content_html);
        assert!(plain.html_asset_root.is_none());
        assert!(find_html_duplicate_source(&project_path, &project, "wrong-page", &source_id).is_err());
        let block = &mut project.course.modules[0].chapters[0].pages[0].blocks[0];
        block.html_asset_root = Some("html/package".into());
        block.html_entry_file = Some("html/another/index.html".into());
        assert!(find_html_duplicate_source(&project_path, &project, &page_id, &source_id).unwrap_err().contains("hors"));
        project.course.modules[0].chapters[0].pages[0].blocks[0].html_entry_file = Some("html/package/index.html".into());
        assert!(find_html_duplicate_source(&project_path, &project, &page_id, &source_id).is_err());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn replacing_a_shared_html_package_keeps_it_until_the_last_reference_is_gone() {
        let project_root = temporary_assets_dir("shared-package");
        let assets_dir = project_root.join("assets");
        let old_folder = assets_dir.join("html/old-package");
        fs::create_dir_all(&old_folder).expect("create old package");
        fs::write(old_folder.join("index.html"), b"old").expect("write old package");

        let mut block = sample_quiz_block();
        block.block_type = "html-custom".to_string();
        block.asset_refs = vec!["html/old-package/index.html".to_string()];
        let mut project = sample_project(vec![sample_chapter("chapter", "Chapter", block, None)]);
        let project_path = project_root.to_string_lossy().to_string();

        remove_previous_html_package(
            &project_path,
            &project,
            &assets_dir,
            "html/old-package",
            Some("html/new-package"),
        );
        assert!(old_folder.exists(), "a second activity still uses the old package");

        project.course.modules[0].chapters[0].pages[0].blocks[0].asset_refs.clear();
        remove_previous_html_package(
            &project_path,
            &project,
            &assets_dir,
            "html/old-package",
            Some("html/new-package"),
        );
        assert!(!old_folder.exists(), "the unreferenced package must be removed");
        let _ = fs::remove_dir_all(project_root);
    }

