    #[test]
    fn scorm_quote_preserves_image_layout_and_size() {
        let mut quote = sample_quiz_block();
        quote.block_type = "quote".to_string();
        quote.quiz = None;
        quote.content_html = Some("<p>Citation</p>".to_string());
        quote.asset_refs = vec!["images/portrait.png".to_string()];
        quote.media_layout = Some("image-right".to_string());
        quote.image_size = Some("large".to_string());

        let right_html = render_scorm_block(
            &quote,
            "activity_quote_right",
            None,
            36,
            None,
            "#222222",
            "#FFFFFF",
        );
        assert!(
            right_html.contains(r#"class="block rich quote has-avatar image-right"#),
            "unexpected quote markup: {right_html}"
        );
        assert!(right_html.contains("--quote-avatar-size:26%"));
        assert!(right_html.find("quote-avatar").unwrap() < right_html.find("quote-copy").unwrap());
        assert!(right_html
            .contains(r#"<span class="quote-mark open" aria-hidden="true">&ldquo;</span>"#));
        assert!(right_html
            .contains(r#"<span class="quote-mark close" aria-hidden="true">&rdquo;</span>"#));

        quote.media_layout = Some("image-center".to_string());
        quote.image_size = Some("small".to_string());
        let center_html = render_scorm_block(
            &quote,
            "activity_quote_center",
            None,
            36,
            None,
            "#222222",
            "#FFFFFF",
        );
        assert!(center_html.contains(r#"class="block rich quote has-avatar image-center"#));
        assert!(center_html.contains("--quote-avatar-size:20%"));

        let document = build_scorm_index(
            &sample_project(vec![sample_chapter("lesson_1", "Chapitre 1", quote, None)]),
            None,
        );
        assert!(document.contains(".block.rich.quote.image-right.has-avatar"));
        assert!(document.contains(".block.rich.quote.image-center .quote-avatar"));
        assert!(document.contains(".block.rich.quote.has-avatar:not(.image-center) .quote-avatar"));
        assert!(document.contains(
            "margin-top:calc(var(--quote-open-mark-height) + var(--quote-open-mark-gap))"
        ));
        assert!(document.contains(
            ".block.rich.quote .quote-body, .block.rich.quote .quote-body * { color:inherit; font-family:\"Paideia Quote\",Spectral,Georgia,\"Times New Roman\",serif; font-size:18px; font-style:italic; line-height:1.35; }"
        ));
        assert!(document.contains(
            r#"@font-face { font-family:"Paideia Quote"; src:url("vendor/fonts/Spectral-Regular.woff2")"#
        ));
        assert!(document.contains(
            r#"@font-face { font-family:"Paideia Quote Mark"; src:url("vendor/fonts/Bellefair-Regular.woff2")"#
        ));
    }

    #[test]
    fn scorm_course_appearance_resolves_inheritance_and_preserves_full_width_contract() {
        let appearance = CourseAppearance {
            rounded_corners: false,
            shadows: false,
            text_color_mode: "custom".to_string(),
            text_color: "#345678".to_string(),
            background_color: "#FFFFFF".to_string(),
        };
        let mut block = sample_quiz_block();
        block.image_rounded = None;
        block.panel_rounded = None;
        block.panel_shadow = None;
        block.activity_items = vec![serde_json::from_value(serde_json::json!({
            "id": "item-1",
            "title": "Item",
            "contentHtml": "<p>Contenu</p>",
            "imageRounded": null
        }))
        .expect("activity item")];

        let resolved = resolve_scorm_course_appearance(&block, &appearance);
        assert_eq!(resolved.image_rounded, Some(false));
        assert_eq!(resolved.panel_rounded, Some(false));
        assert_eq!(resolved.panel_shadow, Some(false));
        assert_eq!(resolved.activity_items[0].image_rounded, Some(false));

        let mut tabs = block.clone();
        tabs.block_type = "tabs".to_string();
        tabs.panel_rounded = Some(true);
        tabs.panel_shadow = Some(true);
        let inherited_tabs = resolve_scorm_course_appearance(&tabs, &appearance);
        assert_eq!(inherited_tabs.panel_rounded, Some(false));
        assert_eq!(inherited_tabs.panel_shadow, Some(false));
        tabs.panel_rounded = Some(false);
        tabs.panel_shadow = Some(false);
        let overridden_tabs = resolve_scorm_course_appearance(
            &tabs,
            &CourseAppearance {
                rounded_corners: true,
                shadows: true,
                text_color_mode: "default".to_string(),
                text_color: "#222222".to_string(),
                background_color: "#FFFFFF".to_string(),
            },
        );
        assert_eq!(overridden_tabs.panel_rounded, Some(false));
        assert_eq!(overridden_tabs.panel_shadow, Some(false));

        let mut full_width = block.clone();
        full_width.block_type = "image".to_string();
        full_width.media_layout = Some("page-width".to_string());
        full_width.image_rounded = Some(true);
        assert_eq!(
            resolve_scorm_course_appearance(
                &full_width,
                &CourseAppearance {
                    rounded_corners: true,
                    shadows: true,
                    text_color_mode: "default".to_string(),
                    text_color: "#222222".to_string(),
                    background_color: "#FFFFFF".to_string(),
                }
            )
            .image_rounded,
            Some(false)
        );

        let mut project =
            sample_project(vec![sample_chapter("lesson_1", "Chapitre 1", block, None)]);
        project.course_appearance = Some(appearance);
        let html = build_scorm_index(&project, None);
        assert!(html.contains("--content-text:#345678"));
    }

