    #[test]
    fn scorm_result_support_is_conditional_and_does_not_track_progress() {
        let mut block = sample_quiz_block();
        block.block_type = "result-message".to_string();
        block.quiz = None;
        block.panel_rounded = Some(true);
        block.panel_shadow = Some(true);
        block.activity_items = vec![
            serde_json::from_value(serde_json::json!({
                "id": "success",
                "title": "",
                "kind": "result-success",
                "nextNodeId": "quiz-source",
                "contentHtml": "<p>Bravo</p>"
            }))
            .expect("success branch"),
            serde_json::from_value(serde_json::json!({
                "id": "failure",
                "title": "",
                "kind": "result-failure",
                "nextNodeId": "quiz-source",
                "contentHtml": "<p>Continuez</p>"
            }))
            .expect("failure branch"),
        ];

        let html = render_scorm_block(&block, "support", None, 36, None, "#222222", "#FFFFFF");

        assert!(html.contains(r#"class="block result-message-block""#));
        assert!(html.contains(r#"data-result-source-quiz="quiz-source""#));
        assert!(html.contains(r#"role="status" aria-live="polite""#));
        assert!(html.contains("background:#edf4ff"));
        assert!(html.contains("border-color:#123a7a"));
        assert!(html.contains("border-radius:22px"));
        assert!(html.contains("box-shadow:0 16px 34px rgba(18,58,122,.14)"));
        assert!(!html.contains("data-paideia-activity"));

        let course_html = build_scorm_index(
            &sample_project(vec![sample_chapter(
                "lesson_1",
                "Chapitre 1",
                sample_quiz_block(),
                None,
            )]),
            None,
        );
        assert!(course_html.contains("sourceQuiz.compareDocumentPosition(block)"));
        assert!(course_html
            .contains("sourceQuiz.closest(\".chapter\") === block.closest(\".chapter\")"));
    }

    #[test]
    fn scorm_note_preserves_rounded_corners_and_shadow_choices() {
        let mut block = sample_quiz_block();
        block.block_type = "note".to_string();
        block.quiz = None;
        block.content_html = Some("<p>Information</p>".to_string());
        block.panel_rounded = Some(true);
        block.panel_shadow = Some(true);

        let rounded = render_scorm_block(&block, "note", None, 36, None, "#222222", "#FFFFFF");
        assert!(rounded.contains("border-radius:22px"));
        assert!(rounded.contains("box-shadow:0 16px 34px rgba(18,58,122,.14)"));
        assert!(rounded.contains("<circle cx=\"12\" cy=\"12\" r=\"18\"/>"));
        assert!(rounded.contains("M12 10.5v6"));

        block.panel_border_color = Some("#224466".to_string());
        block.note_icon_color = Some("#cc3322".to_string());
        block.note_icon_matches_border = Some(false);
        let custom_color =
            render_scorm_block(&block, "note", None, 36, None, "#222222", "#FFFFFF");
        assert!(custom_color.contains("--note-accent:#cc3322;border-color:#224466"));

        block.note_icon_matches_border = Some(true);
        let linked_color =
            render_scorm_block(&block, "note", None, 36, None, "#222222", "#FFFFFF");
        assert!(linked_color.contains("--note-accent:#224466;border-color:#224466"));

        block.panel_rounded = Some(false);
        block.panel_shadow = Some(false);
        block.note_icon = Some("warning-triangle".to_string());
        let square = render_scorm_block(&block, "note", None, 36, None, "#222222", "#FFFFFF");
        assert!(square.contains("border-radius:0px"));
        assert!(square.contains("box-shadow:none"));
        assert!(square.contains("M12 3.5 21 20H3L12 3.5Z"));

        block.note_show_icon = Some(false);
        let without_icon =
            render_scorm_block(&block, "note", None, 36, None, "#222222", "#FFFFFF");
        assert!(without_icon.contains("note-without-icon"));
        assert!(!without_icon.contains("<svg class=\"note-icon\""));
    }

