        let spaced = wrap_scorm_block_spacing(
            &block,
            "<article class=\"block\"><hr></article>".to_string(),
            30,
        );
        assert!(spaced.contains("--block-activity-padding:0px"));

        let rendered = wrap_scorm_section_style(&block, spaced);
