        assert!(html.contains("data-slide-title-template=\"Diapo {number}\""));
        assert!(html.contains("data-slides-fallback-title"));
        assert!(html.contains("event.key === \"ArrowLeft\""));
        assert!(html.contains("focus({ preventScroll: true })"));
        assert!(!html.contains("viewer.scrollIntoView({ behavior: \"auto\", block: \"start\" })"));
        assert!(html.contains("--slides-reference-height"));
