        assert!(wide_html.contains("--activity-section-bg-overlay-opacity:0.4"));
        assert!(wide_html.contains("--activity-section-bg-overlay-color:0,0,0"));
        assert!(wide_html.contains("--activity-section-bg-blur:8px"));
        assert!(wide_html.contains("--activity-section-extra-padding:150px"));
        assert!(wide_html.contains("--activity-section-radius:0px"));
