    #[test]
    fn scorm_presentation_preserves_authored_order_even_with_legacy_kinds() {
        let mut slides = sample_quiz_block();
        slides.block_type = "slides".to_string();
        slides.quiz = None;
        slides.activity_items = vec![
            serde_json::from_value(serde_json::json!({
                "id": "legacy-summary-first",
                "title": "Première dans l'ordre auteur",
                "kind": "summary",
                "contentHtml": "<p>Premier contenu</p>"
            }))
            .expect("first presentation slide"),
            serde_json::from_value(serde_json::json!({
                "id": "legacy-intro-second",
                "title": "Deuxième dans l'ordre auteur",
                "kind": "intro",
                "contentHtml": "<p>Deuxième contenu</p>"
            }))
            .expect("second presentation slide"),
        ];

        let html = build_scorm_index(
            &sample_project(vec![sample_chapter("lesson_1", "Chapitre 1", slides, None)]),
            None,
        );
        let first_position = html
            .find("Première dans l'ordre auteur")
            .expect("first authored slide should render");
        let second_position = html
            .find("Deuxième dans l'ordre auteur")
            .expect("second authored slide should render");
        assert!(first_position < second_position);
    }

