    #[test]
    fn scorm_image_text_uses_the_validated_component_layout() {
        let mut block = sample_quiz_block();
        block.block_type = "image-text".to_string();
        block.quiz = None;
        block.media_layout = Some("image-right".to_string());
        block.image_size = Some("medium".to_string());
        block.asset_refs = vec!["images/gap.png".to_string()];
        block.content_html = Some("<p>Texte à côté de l’image.</p>".to_string());
        let mut cropped = block.clone();
        cropped.image_crop = Some(crate::models::ImageCrop { x: 0.0, y: 0.0, width: 50.0, height: 50.0, shape: Some("rectangle".to_string()) });
        let crop_html = build_scorm_index(&sample_project(vec![sample_chapter("crop", "Recadrage", cropped, None)]), None);
        let project = sample_project(vec![sample_chapter("gap", "Espacement", block, None)]);
        let html = build_scorm_index(&project, None);
        let runtime = build_scorm_runtime();
        assert!(html.contains("--image-text-max-width: 970px"));
        assert!(html.contains("paideia-image-text-frame"));
        assert!(html.contains("paideia-image-text-copy image-copy"));
        assert!(html.contains("data-layout=\"image-right\""));
        assert!(!html.contains("paideia-image-text-activity image-right"));
        assert!(runtime.contains("function measureImageTextCroppedMedia"));
        assert!(!runtime.contains("__PAIDEIA_IMAGE_TEXT_MEDIA__"));
        if let Ok(directory) = std::env::var("PAIDEIA_IMAGE_TEXT_TEST_OUTPUT") {
            let directory = PathBuf::from(directory);
            fs::create_dir_all(&directory).unwrap();
            fs::write(directory.join("index.html"), html).unwrap();
            fs::write(directory.join("crop.html"), crop_html).unwrap();
            fs::write(directory.join("runtime.js"), runtime).unwrap();
        }
    }

