    #[test]
    fn pdf_export_atomic_write_never_replaces_with_invalid_bytes() {
        let root = std::env::temp_dir().join(format!(
            "paideia-pdf-atomic-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        let target = root.join("document.pdf");
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).expect("create PDF test directory");
        fs::write(&target, b"%PDF-old").expect("write previous PDF");

        assert!(write_pdf_export_atomic(
            target.to_string_lossy().to_string(),
            STANDARD.encode(b"not a pdf")
        )
        .is_err());
        assert_eq!(fs::read(&target).expect("read preserved PDF"), b"%PDF-old");

        write_pdf_export_atomic(
            target.to_string_lossy().to_string(),
            STANDARD.encode(b"%PDF-1.7\n%%EOF"),
        )
        .expect("replace PDF atomically");
        assert_eq!(
            fs::read(&target).expect("read exported PDF"),
            b"%PDF-1.7\n%%EOF"
        );
        let leftovers = fs::read_dir(&root)
            .expect("read PDF test directory")
            .filter_map(Result::ok)
            .filter(|entry| entry.file_name() != "document.pdf")
            .count();
        assert_eq!(leftovers, 0);
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn pdf_export_reads_project_and_assets_from_folder_and_archive() {
        let root = std::env::temp_dir().join(format!(
            "paideia-pdf-source-{}-{}",
            std::process::id(),
            compact_timestamp()
        ));
        let archive_path = root.with_extension("paideia");
        let _ = fs::remove_dir_all(&root);
        let _ = fs::remove_file(&archive_path);
        fs::create_dir_all(root.join("assets/images")).expect("create PDF source assets");
        let project = sample_project(vec![sample_chapter(
            "chapter",
            "Chapitre PDF",
            sample_quiz_block(),
            None,
        )]);
        save_project_to_path(&root.to_string_lossy(), &project).expect("save PDF source project");
        fs::write(root.join("assets/images/reference.png"), b"png-payload")
            .expect("write PDF source image");
        zip_directory_to_file(&root, &archive_path).expect("archive PDF source project");

        for source in [&root, &archive_path] {
            let loaded = load_project_for_pdf_export(source.to_string_lossy().to_string())
                .expect("load PDF source");
            assert_eq!(loaded.title, "Projet test");
            let files = read_project_files_for_pdf_export(
                source.to_string_lossy().to_string(),
                vec![
                    "images/reference.png".to_string(),
                    "images/refus.svg".to_string(),
                ],
            )
            .expect("read PDF source files");
            assert_eq!(files.len(), 1);
            assert_eq!(files[0].asset_ref, "images/reference.png");
            assert_eq!(files[0].data_base64, STANDARD.encode(b"png-payload"));
        }

        let _ = fs::remove_dir_all(root);
        let _ = fs::remove_file(archive_path);
    }

    #[test]
    fn scorm_interface_uses_the_export_language() {
        let source = concat!(
            "<html lang=\"fr\"><button>Commencer la le&ccedil;on</button>",
            "<p>Chapitre 1 / 2</p><button>Continuer</button>",
            "<button>Sortir de la le&ccedil;on</button>",
            "<button aria-label=\"__PAIDEIA_TRANSCRIPT_CONSULT__\"></button>",
            "<div data-transcript-close-label=\"__PAIDEIA_TRANSCRIPT_CLOSE__\" data-transcript-download-label=\"__PAIDEIA_TRANSCRIPT_DOWNLOAD__\"></div>",
            "<script>var message=__PAIDEIA_QUIZ_FINAL_FAILURE_CAN_CONTINUE__;</script></html>"
        );
        let english = localize_scorm_index(source.to_string(), "en");
        assert!(english.contains("Start lesson"));
        assert!(english.contains("Chapter 1 / 2"));
        assert!(english.contains("Continue"));
        assert!(english.contains("Exit lesson"));
        assert!(english.contains("aria-label=\"View transcript\""));
        assert!(english.contains("data-transcript-close-label=\"Close\""));
        assert!(english.contains("data-transcript-download-label=\"Download transcript\""));
        assert!(english.contains("You did not reach the passing score"));

        let french = localize_scorm_index(source.to_string(), "fr");
        assert_eq!(
            french,
            "<html lang=\"fr\"><button>Commencer la leçon</button><p>Chapitre 1 / 2</p><button>Continuer</button><button>Sortir de la leçon</button><button aria-label=\"Consulter la transcription\"></button><div data-transcript-close-label=\"Fermer\" data-transcript-download-label=\"Télécharger la transcription\"></div><script>var message=\"Vous n’avez pas atteint le seuil de réussite et vous avez utilisé toutes vos tentatives. Vous pouvez poursuivre le cours.\";</script></html>"
        );
    }

